fn renderer_turn_activity_hint(classification: &EnvelopeClass) -> Option<TurnActivity> {
    match classification {
        EnvelopeClass::DirectProgress { progress_type }
            if matches!(progress_type.as_str(), "agent_progress" | "skill_progress") =>
        {
            Some(TurnActivity::Waiting(WaitingReason::Subagent))
        }
        EnvelopeClass::DirectProgress { progress_type } if progress_type == "waiting_for_task" => {
            Some(TurnActivity::Waiting(WaitingReason::Task))
        }
        EnvelopeClass::DirectProgress { progress_type }
            if matches!(
                progress_type.as_str(),
                "bash_progress"
                    | "shell_progress"
                    | "mcp_progress"
                    | "query_update"
                    | "search_results_received"
            ) =>
        {
            Some(TurnActivity::ToolUse)
        }
        EnvelopeClass::ToolProgress => Some(TurnActivity::ToolUse),
        EnvelopeClass::System(SystemSubtype::ApiRetry)
        | EnvelopeClass::DirectSystem(DirectSystemSubtype::ApiError) => {
            Some(TurnActivity::Retrying)
        }
        _ => None,
    }
}

fn count_direct_watcher(watchers: &mut Watchers, task_type: DirectTaskType) {
    match task_type {
        DirectTaskType::LocalBash | DirectTaskType::Dream => watchers.commands += 1,
        DirectTaskType::MonitorMcp => watchers.monitors += 1,
        DirectTaskType::LocalAgent
        | DirectTaskType::RemoteAgent
        | DirectTaskType::InProcessTeammate => watchers.subagents += 1,
        DirectTaskType::LocalWorkflow => watchers.workflows += 1,
    }
}

fn count_sdk_watcher(watchers: &mut Watchers, task_type: Option<&str>) {
    let normalized = task_type
        .unwrap_or_default()
        .to_ascii_lowercase()
        .replace(['-', ' '], "_");
    if normalized.contains("monitor") {
        watchers.monitors += 1;
    } else if normalized.contains("workflow") {
        watchers.workflows += 1;
    } else if normalized.contains("agent") || normalized.contains("teammate") {
        watchers.subagents += 1;
    } else if normalized.contains("loop") || normalized.contains("cron") {
        watchers.loops += 1;
    } else {
        watchers.commands += 1;
    }
}

