pub(crate) enum ShellPhase {
    Welcome,
    Conversation,
}

#[derive(Clone, PartialEq)]
pub enum HostAction {
    SendUser {
        content: Value,
        priority: Option<String>,
    },
    SendControl {
        request: Value,
        purpose: OutboundPurpose,
    },
    SendPrivateRuntimeAction {
        request_id: String,
        action: Value,
        purpose: PrivateRuntimePurpose,
    },
    RespondPermission {
        request_id: String,
        response: Value,
    },
    RespondElicitation {
        request_id: String,
        response: Value,
    },
    RespondStartupInteraction {
        request_id: String,
        subtype: String,
        response: Value,
    },
    /// Release the existing SDK initialize request into the direct runtime.
    /// TypeScript may hold that one request while renderer-private historical
    /// setup runs, but this remains the original backend request rather than a
    /// new request subtype or second readiness protocol.
    Initialize,
    Interrupt,
    StopRuntime {
        reason: String,
    },
}

/// Result of routing one timestamped terminal event.
///
/// Host actions retain the historical public `handle_event` contract. The
/// renderer-private `needs_frame` bit mirrors the fixed renderer's
/// Changed/Unchanged outcome so cadence-suppressed wheel reports cannot each
/// enqueue an otherwise identical frame.
pub(crate) struct TerminalEventOutcome {
    pub(crate) actions: Vec<HostAction>,
    pub(crate) needs_frame: bool,
}

