impl fmt::Debug for HostAction {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::SendUser { content, priority } => formatter
                .debug_struct("SendUser")
                .field("content", content)
                .field("priority", priority)
                .finish(),
            Self::SendControl { request, purpose } => formatter
                .debug_struct("SendControl")
                .field("request", request)
                .field("purpose", purpose)
                .finish(),
            Self::SendPrivateRuntimeAction {
                request_id,
                action,
                purpose,
            } => formatter
                .debug_struct("SendPrivateRuntimeAction")
                .field("request_id", request_id)
                // Private runtime actions can contain model credentials. Keep
                // Debug useful for correlation without ever formatting the
                // payload, including on future error/reporting paths that use
                // `HostAction: Debug` indirectly.
                .field("action_kind", &action.get("kind").and_then(Value::as_str))
                .field("action", &"<redacted private runtime payload>")
                .field("purpose", purpose)
                .finish(),
            Self::RespondPermission {
                request_id,
                response,
            } => formatter
                .debug_struct("RespondPermission")
                .field("request_id", request_id)
                .field("response", response)
                .finish(),
            Self::RespondElicitation {
                request_id,
                response,
            } => formatter
                .debug_struct("RespondElicitation")
                .field("request_id", request_id)
                .field("response", response)
                .finish(),
            Self::RespondStartupInteraction {
                request_id,
                subtype,
                response,
            } => {
                let mut debug = formatter.debug_struct("RespondStartupInteraction");
                debug
                    .field("request_id", request_id)
                    .field("subtype", subtype);
                if response.get("kind").and_then(Value::as_str) == Some("onboarding")
                    && response.get("stage").and_then(Value::as_str) == Some("oauth")
                    && response.get("phase").and_then(Value::as_str) == Some("custom_api_key")
                {
                    debug.field("response", &"<redacted custom API key response>");
                } else {
                    debug.field("response", response);
                }
                debug.finish()
            }
            Self::Initialize => formatter.write_str("Initialize"),
            Self::Interrupt => formatter.write_str("Interrupt"),
            Self::StopRuntime { reason } => formatter
                .debug_struct("StopRuntime")
                .field("reason", reason)
                .finish(),
        }
    }
}

