/// Renderer-local model chooser.
///
/// The catalog and active model are existing SDK facts. Selection emits only
/// the historical `set_model { model }` control request; no picker state is
/// projected into the backend protocol.
#[derive(Debug, Clone)]
pub(crate) struct ModelPickerState {
    choices: Vec<ModelChoice>,
    matches: Vec<usize>,
    lifecycle: PickerState,
    initial_model: Option<String>,
}

impl ModelPickerState {
    fn from_catalog(
        catalog: &[ModelChoice],
        current_model: Option<&str>,
        language: UiLanguage,
    ) -> Self {
        let mut choices = catalog.to_vec();
        let initial_model = current_model
            .filter(|model| !model.is_empty())
            .map(str::to_string);
        let selected = initial_model.as_deref().and_then(|current| {
            choices
                .iter()
                .position(|choice| choice.id == current)
                .or_else(|| {
                    choices.push(ModelChoice {
                        id: current.to_string(),
                        label: current.to_string(),
                        description: Some(language.text("（当前）", "(current)").to_string()),
                        supports_effort: None,
                        supported_effort_levels: None,
                        supports_adaptive_thinking: None,
                        supports_fast_mode: None,
                        supports_auto_mode: None,
                    });
                    Some(choices.len() - 1)
                })
        });
        let selected = selected.or_else(|| (!choices.is_empty()).then_some(0));
        let matches = (0..choices.len()).collect::<Vec<_>>();
        let mut lifecycle = PickerState::input_active();
        if let Some(selected) = selected {
            lifecycle.set_selected(selected, matches.len());
        }
        let mut picker = Self {
            choices,
            matches,
            lifecycle,
            initial_model,
        };
        picker.ensure_selected_visible();
        picker
    }

    pub(crate) fn choices(&self) -> &[ModelChoice] {
        &self.choices
    }

    pub(crate) fn selected(&self) -> Option<usize> {
        self.lifecycle
            .selected_for(self.matches.len())
            .and_then(|index| self.matches.get(index).copied())
    }

    pub(crate) fn visible_from(&self) -> usize {
        self.lifecycle
            .selected_for(self.matches.len())
            .map(|selected| {
                selected
                    .saturating_add(1)
                    .saturating_sub(MODEL_PICKER_VISIBLE_OPTIONS)
            })
            .unwrap_or(0)
    }

    pub(crate) fn visible_to(&self) -> usize {
        self.visible_from()
            .saturating_add(MODEL_PICKER_VISIBLE_OPTIONS)
            .min(self.matches.len())
    }

    pub(crate) fn hidden_count(&self) -> usize {
        self.matches
            .len()
            .saturating_sub(MODEL_PICKER_VISIBLE_OPTIONS)
    }

    pub(crate) fn initial_model(&self) -> Option<&str> {
        self.initial_model.as_deref()
    }

    fn selected_choice(&self) -> Option<&ModelChoice> {
        self.selected().and_then(|index| self.choices.get(index))
    }

    fn focus_next(&mut self) {
        self.lifecycle.move_next(self.matches.len(), &[], true);
    }

    fn focus_previous(&mut self) {
        self.lifecycle.move_previous(self.matches.len(), &[], true);
    }

    fn select_number(&mut self, number: usize) -> bool {
        let Some(index) = number.checked_sub(1) else {
            return false;
        };
        if index >= self.matches.len() {
            return false;
        }
        self.lifecycle.set_selected(index, self.matches.len());
        true
    }

    pub(crate) fn query(&self) -> &str {
        self.lifecycle.query()
    }

    pub(crate) fn lifecycle(&self) -> &PickerState {
        &self.lifecycle
    }

    pub(crate) fn lifecycle_mut(&mut self) -> &mut PickerState {
        &mut self.lifecycle
    }

    pub(crate) fn choice_at_visible(&self, index: usize) -> Option<(usize, &ModelChoice)> {
        self.matches.get(index).copied().and_then(|choice_index| {
            self.choices
                .get(choice_index)
                .map(|choice| (choice_index, choice))
        })
    }

    pub(crate) fn match_count(&self) -> usize {
        self.matches.len()
    }

    fn handle_event(&mut self, event: &Event) -> PickerOutcome {
        let outcome = handle_picker_input(
            event,
            &mut self.lifecycle,
            self.matches.len(),
            &picker_config_default(),
        );
        if matches!(outcome, PickerOutcome::QueryChanged) {
            self.refresh_matches();
        }
        outcome
    }

    fn refresh_matches(&mut self) {
        let query = self.lifecycle.query();
        if query.is_empty() {
            self.matches = (0..self.choices.len()).collect();
        } else {
            let searchable = self
                .choices
                .iter()
                .map(|choice| {
                    format!(
                        "{} {} {}",
                        choice.id,
                        choice.label,
                        choice.description.as_deref().unwrap_or_default()
                    )
                })
                .collect::<Vec<_>>();
            self.matches = filter_indices(query, searchable.iter().map(String::as_str));
        }
        clamp_picker_selection(&mut self.lifecycle, self.matches.len(), &[]);
    }

    fn ensure_selected_visible(&mut self) {
        self.lifecycle.scroll_offset = None;
    }
}

fn normalized_model_picker_digit(input: char) -> Option<usize> {
    match input {
        '0'..='9' => input.to_digit(10).map(|digit| digit as usize),
        '０'..='９' => Some((u32::from(input) - u32::from('０')) as usize),
        _ => None,
    }
}

