#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum McpMenuAction {
    ViewTools,
    ClearAuthentication,
    Reconnect,
    Enable,
    Disable,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct McpMenuOption {
    pub(crate) action: McpMenuAction,
    pub(crate) label: &'static str,
}

/// Renderer-owned navigation over the existing `mcp_status` projection.
///
/// The state deliberately contains only fields already present in the SDK
/// response. In particular it cannot synthesize agent-frontmatter servers,
/// parser warnings, prompt/resource counts, OAuth-token presence, or a full
/// executable `Tool` object.
#[derive(Debug, Clone)]
pub(crate) struct McpSettingsState {
    servers: Vec<McpServerState>,
    view: McpSettingsView,
    lifecycle: PickerState,
    detail_scroll: usize,
    ui_language: UiLanguage,
}

impl McpSettingsState {
    fn from_servers(servers: &[McpServerState], ui_language: UiLanguage) -> Self {
        let mut servers = servers
            .iter()
            .filter(|server| server.name != "ide")
            .cloned()
            .collect::<Vec<_>>();
        servers.sort_by(|left, right| {
            mcp_server_group_rank(left)
                .cmp(&mcp_server_group_rank(right))
                .then_with(|| left.name.cmp(&right.name))
        });
        Self {
            servers,
            view: McpSettingsView::List,
            lifecycle: PickerState::default(),
            detail_scroll: 0,
            ui_language,
        }
    }

    pub(crate) fn servers(&self) -> &[McpServerState] {
        &self.servers
    }

    pub(crate) const fn view(&self) -> McpSettingsView {
        self.view
    }

    pub(crate) const fn lifecycle(&self) -> &PickerState {
        &self.lifecycle
    }

    pub(crate) fn lifecycle_mut(&mut self) -> &mut PickerState {
        &mut self.lifecycle
    }

    pub(crate) const fn detail_scroll(&self) -> usize {
        self.detail_scroll
    }

    fn set_servers(&mut self, servers: &[McpServerState]) {
        *self = Self::from_servers(servers, self.ui_language);
    }

    fn entry_count(&self) -> usize {
        match self.view {
            McpSettingsView::List => self.servers.len(),
            McpSettingsView::Server { server_index } => self
                .servers
                .get(server_index)
                .map_or(0, |server| self.server_menu_options(server).len()),
            McpSettingsView::Tools { server_index } => self
                .servers
                .get(server_index)
                .map_or(0, |server| server.tools.len()),
            McpSettingsView::ToolDetail { .. } => 0,
        }
    }

    pub(crate) fn server_menu_options(&self, server: &McpServerState) -> Vec<McpMenuOption> {
        let mut options = Vec::new();
        if server.status == "connected" && !server.tools.is_empty() {
            options.push(McpMenuOption {
                action: McpMenuAction::ViewTools,
                label: self.ui_language.text("查看工具", "View tools"),
            });
        }

        let transport = server.config.as_ref().map(|config| config.transport);
        if transport.is_some_and(|transport| transport.is_remote_oauth())
            && server.status == "connected"
            && !server.tools.is_empty()
        {
            // This is the only token-independent arm of the historical
            // `isEffectivelyAuthenticated` predicate. `mcp_status` does not
            // project OAuth-token presence, so a needs-auth/failed/pending
            // status cannot truthfully choose between Authenticate and
            // Re-authenticate/Clear. Historical reauthentication additionally
            // revokes existing tokens before OAuth and has no equivalent
            // existing renderer control.
            options.push(McpMenuOption {
                action: McpMenuAction::ClearAuthentication,
                label: self
                    .ui_language
                    .text("清除身份验证", "Clear authentication"),
            });
        }

        let remote_menu = transport.is_some_and(|transport| {
            matches!(
                transport,
                McpServerTransport::Sse
                    | McpServerTransport::Http
                    | McpServerTransport::AcosmiProxy
            )
        });
        if server.status != "disabled" && (!remote_menu || server.status != "needs-auth") {
            options.push(McpMenuOption {
                action: McpMenuAction::Reconnect,
                label: self.ui_language.text("重新连接", "Reconnect"),
            });
        }
        options.push(if server.status == "disabled" {
            McpMenuOption {
                action: McpMenuAction::Enable,
                label: self.ui_language.text("启用", "Enable"),
            }
        } else {
            McpMenuOption {
                action: McpMenuAction::Disable,
                label: self.ui_language.text("禁用", "Disable"),
            }
        });
        options
    }

    fn reset_picker(&mut self) {
        self.lifecycle = PickerState::default();
        self.detail_scroll = 0;
    }

    fn open_selected(&mut self) -> Option<McpMenuAction> {
        match self.view {
            McpSettingsView::List => {
                let server_index = self.lifecycle.selected_for(self.servers.len())?;
                self.view = McpSettingsView::Server { server_index };
                self.reset_picker();
                None
            }
            McpSettingsView::Server { server_index } => {
                let server = self.servers.get(server_index)?;
                let options = self.server_menu_options(server);
                let selected = self.lifecycle.selected_for(options.len())?;
                let action = options.get(selected)?.action;
                match action {
                    McpMenuAction::ViewTools => {
                        self.view = McpSettingsView::Tools { server_index };
                        self.reset_picker();
                        None
                    }
                    _ => Some(action),
                }
            }
            McpSettingsView::Tools { server_index } => {
                let server = self.servers.get(server_index)?;
                let tool_index = self.lifecycle.selected_for(server.tools.len())?;
                self.view = McpSettingsView::ToolDetail {
                    server_index,
                    tool_index,
                };
                self.reset_picker();
                None
            }
            McpSettingsView::ToolDetail { .. } => None,
        }
    }

    /// Return true when the outer settings surface should close.
    fn back(&mut self) -> bool {
        match self.view {
            McpSettingsView::List => true,
            McpSettingsView::Server { .. } => {
                self.view = McpSettingsView::List;
                self.reset_picker();
                false
            }
            McpSettingsView::Tools { server_index } => {
                self.view = McpSettingsView::Server { server_index };
                self.reset_picker();
                false
            }
            McpSettingsView::ToolDetail { server_index, .. } => {
                self.view = McpSettingsView::Tools { server_index };
                self.reset_picker();
                false
            }
        }
    }

    fn selected_server(&self) -> Option<&McpServerState> {
        let server_index = match self.view {
            McpSettingsView::Server { server_index }
            | McpSettingsView::Tools { server_index }
            | McpSettingsView::ToolDetail { server_index, .. } => server_index,
            McpSettingsView::List => self.lifecycle.selected_for(self.servers.len())?,
        };
        self.servers.get(server_index)
    }

    fn handle_detail_key(&mut self, key: KeyEvent) -> bool {
        match key {
            KeyEvent {
                code: KeyCode::Up,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.detail_scroll = self.detail_scroll.saturating_sub(1);
                true
            }
            KeyEvent {
                code: KeyCode::Down,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.detail_scroll = self.detail_scroll.saturating_add(1);
                true
            }
            KeyEvent {
                code: KeyCode::PageUp,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.detail_scroll = self
                    .detail_scroll
                    .saturating_sub(MCP_SETTINGS_VISIBLE_OPTIONS);
                true
            }
            KeyEvent {
                code: KeyCode::PageDown,
                modifiers: KeyModifiers::NONE,
                ..
            } => {
                self.detail_scroll = self
                    .detail_scroll
                    .saturating_add(MCP_SETTINGS_VISIBLE_OPTIONS);
                true
            }
            _ => false,
        }
    }
}

fn mcp_server_group_rank(server: &McpServerState) -> u8 {
    if server
        .config
        .as_ref()
        .is_some_and(|config| config.transport == McpServerTransport::AcosmiProxy)
    {
        return 4;
    }
    match server.scope.as_deref() {
        Some("project") => 0,
        Some("local") => 1,
        Some("user") => 2,
        Some("enterprise") => 3,
        Some("dynamic") => 6,
        Some(_) | None => 5,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OverlayKind {
    Help,
    Json,
    /// Renderer-owned plain-text summary derived only from typed cardinalities
    /// in the existing reload response. It must never enter a JSON formatter.
    ReloadSummary,
    Context,
    BlockViewer,
    /// Input-ownership marker for the fixed historical inline GoalConsole.
    /// The panel is laid out above the composer rather than painted as a
    /// centered overlay.
    GoalConsole,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Overlay {
    pub kind: OverlayKind,
    pub title: String,
    pub body: String,
    pub scroll: usize,
    /// Content rows measured by the most recent renderer layout. `None`
    /// before first paint keeps scrolling inert instead of guessing a
    /// viewport from transcript geometry.
    pub(crate) body_viewport_height: Option<u16>,
    pub(crate) lifecycle: OverlayState,
    pub(crate) window: ModalWindowState,
    pub(crate) help_tabs: Vec<HelpTabDocument>,
    pub(crate) context_visualization: Option<ContextVisualization>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct HelpTabDocument {
    pub(crate) label: &'static str,
    pub(crate) body: String,
}

impl Overlay {
    pub(crate) fn new(
        kind: OverlayKind,
        title: impl Into<String>,
        body: impl Into<String>,
    ) -> Self {
        let mut lifecycle = OverlayState::hidden();
        lifecycle.show();
        let _ = lifecycle.toggle();
        Self {
            kind,
            title: title.into(),
            body: body.into(),
            scroll: 0,
            body_viewport_height: None,
            lifecycle,
            window: ModalWindowState::new(),
            help_tabs: Vec::new(),
            context_visualization: None,
        }
    }

    fn total_body_lines(&self) -> usize {
        self.context_visualization.as_ref().map_or_else(
            || self.active_body().split('\n').count(),
            ContextVisualization::line_count,
        )
    }

    pub(crate) fn active_body(&self) -> &str {
        self.help_tabs
            .get(self.window.active_tab)
            .map_or(self.body.as_str(), |tab| tab.body.as_str())
    }

    fn max_scroll_offset(&self) -> Option<usize> {
        self.body_viewport_height
            .map(|height| self.total_body_lines().saturating_sub(usize::from(height)))
    }

    pub(crate) fn set_body_viewport_height(&mut self, height: u16) {
        self.body_viewport_height = Some(height);
        self.scroll = self.scroll.min(self.max_scroll_offset().unwrap_or(0));
    }

    pub(crate) fn context(visualization: ContextVisualization, language: UiLanguage) -> Self {
        let mut overlay = Self::new(
            OverlayKind::Context,
            language.text("上下文用量", "Context Usage"),
            "",
        );
        overlay.context_visualization = Some(visualization);
        overlay
    }

    fn scroll_by(&mut self, lines: i32) -> bool {
        let Some(max_offset) = self.max_scroll_offset() else {
            return false;
        };
        let before = self.scroll;
        if lines < 0 {
            self.scroll = self.scroll.saturating_sub(lines.unsigned_abs() as usize);
        } else {
            self.scroll = self.scroll.saturating_add(lines as usize).min(max_offset);
        }
        before != self.scroll
    }

    fn page_rows(&self) -> Option<i32> {
        self.body_viewport_height
            .map(|height| i32::from(height.max(1)))
    }
}

