#[derive(Debug)]
struct OAuthBrowserPrompt {
    opening_message: String,
    manual_message: String,
    copy_hint: String,
    url: String,
    reveal_at: Instant,
    next_spinner_at: Instant,
    spinner_tick: u64,
    revealed: bool,
    copied_until: Option<Instant>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum OAuthBrowserNotice<'a> {
    Opening {
        spinner: &'static str,
        message: &'a str,
    },
    Manual {
        message: &'a str,
        hint: &'a str,
        copied: bool,
        url: &'a str,
    },
}

impl OAuthBrowserPrompt {
    fn new_at(
        opening_message: String,
        manual_message: String,
        copy_hint: String,
        url: String,
        now: Instant,
        reveal_immediately: bool,
    ) -> Self {
        Self {
            opening_message,
            manual_message,
            copy_hint,
            url,
            reveal_at: now + OAUTH_BROWSER_REVEAL_DELAY,
            next_spinner_at: now + RENDERER_ANIMATION_TICK,
            spinner_tick: 0,
            revealed: reveal_immediately,
            copied_until: None,
        }
    }

    fn next_deadline(&self) -> Option<Instant> {
        if !self.revealed {
            Some(self.reveal_at.min(self.next_spinner_at))
        } else {
            self.copied_until
        }
    }

    fn tick_at(&mut self, now: Instant) -> (bool, bool) {
        let mut changed = false;
        let mut newly_revealed = false;
        if !self.revealed && now >= self.reveal_at {
            self.revealed = true;
            newly_revealed = true;
            changed = true;
        } else if !self.revealed && now >= self.next_spinner_at {
            let interval_nanos = RENDERER_ANIMATION_TICK.as_nanos();
            let overdue_nanos = now.duration_since(self.next_spinner_at).as_nanos();
            let elapsed_steps = 1 + overdue_nanos / interval_nanos;
            self.spinner_tick = self
                .spinner_tick
                .wrapping_add(elapsed_steps.min(u128::from(u64::MAX)) as u64);
            let nanos_until_next = interval_nanos - overdue_nanos % interval_nanos;
            self.next_spinner_at = now + Duration::from_nanos(nanos_until_next as u64);
            changed = true;
        }
        if self.copied_until.is_some_and(|deadline| now >= deadline) {
            self.copied_until = None;
            changed = true;
        }
        (changed, newly_revealed)
    }

    fn spinner_frame(&self) -> &'static str {
        let frames = crabcode_pager_render::audited_glyphs::braille_spinner_frames();
        let index = (self.spinner_tick / RENDERER_SPINNER_DIVISOR) as usize % frames.len().max(1);
        frames.get(index).copied().unwrap_or("|")
    }
}

/// Closed, renderer-private notification preference projected by the fixed
/// CrabCode configuration authority. Retaining it here does not authorize a
/// backend request or a notification trigger.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum RendererNotificationChannel {
    Auto,
    Iterm2,
    Iterm2WithBell,
    TerminalBell,
    Kitty,
    Ghostty,
    NotificationsDisabled,
}

impl RendererNotificationChannel {
    fn parse(value: Option<&Value>) -> Result<Self, String> {
        match value.and_then(Value::as_str) {
            Some("auto") => Ok(Self::Auto),
            Some("iterm2") => Ok(Self::Iterm2),
            Some("iterm2_with_bell") => Ok(Self::Iterm2WithBell),
            Some("terminal_bell") => Ok(Self::TerminalBell),
            Some("kitty") => Ok(Self::Kitty),
            Some("ghostty") => Ok(Self::Ghostty),
            Some("notifications_disabled") => Ok(Self::NotificationsDisabled),
            Some(value) => Err(format!(
                "renderer preferred_notification_channel has unsupported value `{value}`"
            )),
            None => Err(
                "renderer preferred_notification_channel must be one of the closed string values"
                    .to_string(),
            ),
        }
    }

    pub(crate) const fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Iterm2 => "iterm2",
            Self::Iterm2WithBell => "iterm2_with_bell",
            Self::TerminalBell => "terminal_bell",
            Self::Kitty => "kitty",
            Self::Ghostty => "ghostty",
            Self::NotificationsDisabled => "notifications_disabled",
        }
    }
}

