impl DeferredInputJob {
    fn shift_insert_at_after(&mut self, anchor: usize, inserted: usize) {
        let insert_at = match self {
            Self::Clipboard(probe) => &mut probe.insert_at,
            Self::ImagePaths(paste) => &mut paste.insert_at,
        };
        if *insert_at >= anchor {
            *insert_at = insert_at.saturating_add(inserted);
        }
    }
}

