    #[cfg(test)]
    pub(crate) fn take_composer_draft(&mut self) -> ComposerDraft {
        self.clear_composer_image_preview();
        ComposerDraft {
            text: self.composer.text().to_string(),
            cursor: self.composer.cursor(),
            attachments: std::mem::take(&mut self.attachments),
        }
    }

    pub(crate) fn restore_composer_draft(&mut self, draft: ComposerDraft) {
        self.composer.set_text(&draft.text);
        self.composer.set_cursor(draft.cursor.min(draft.text.len()));
        self.composer_state = TextAreaState::default();
        self.attachments = draft.attachments;
        self.clear_composer_image_preview();
    }

    fn clear_composer_image_preview(&mut self) {
        self.composer_image_preview = None;
        self.composer_attachment_navigation_active = false;
        self.composer_attachment_hitboxes.clear();
    }

    fn preview_latest_attachment(&mut self) {
        self.composer_image_preview = self.attachments.len().checked_sub(1);
    }

    fn select_latest_attachment(&mut self) {
        self.preview_latest_attachment();
        self.composer_attachment_navigation_active = self.composer_image_preview.is_some();
    }

    fn cycle_composer_attachment(&mut self, forward: bool) {
        let len = self.attachments.len();
        if len == 0 {
            self.clear_composer_image_preview();
            return;
        }
        let current = self
            .composer_image_preview
            .filter(|index| *index < len)
            .unwrap_or(len - 1);
        self.composer_image_preview = Some(if forward {
            (current + 1) % len
        } else {
            (current + len - 1) % len
        });
        self.composer_attachment_navigation_active = true;
    }

    fn remove_selected_composer_attachment(&mut self) {
        let Some(index) = self
            .composer_image_preview
            .filter(|index| *index < self.attachments.len())
            .or_else(|| self.attachments.len().checked_sub(1))
        else {
            self.clear_composer_image_preview();
            return;
        };
        let keep_navigation = self.composer_attachment_navigation_active;
        let removed = self.attachments.remove(index);
        self.composer_attachment_hitboxes.clear();
        if keep_navigation && !self.attachments.is_empty() {
            self.composer_image_preview = Some(index.min(self.attachments.len() - 1));
            self.composer_attachment_navigation_active = true;
        } else {
            self.composer_image_preview = None;
            self.composer_attachment_navigation_active = false;
        }
        self.status = match self.renderer_ui_language {
            UiLanguage::ZhCn => format!("已移除图片附件 {}", removed.filename),
            UiLanguage::EnUs => format!("Removed image attachment {}", removed.filename),
        };
    }

