    /// Fixed AgentTool's Ctrl-O transcript state is renderer-local. The native
    /// lifecycle represents it by entering scrollback interaction context;
    /// it does not mutate verbose configuration or send a backend request.
    pub(crate) fn direct_agent_transcript_mode(&self) -> bool {
        self.interaction_context == InteractionContext::Scrollback
    }

    /// Reconcile renderer-only interaction state against the current
    /// projection. Identity is the projection's stable key rather than its
    /// current vector index, so history insertion and reflow cannot move a
    /// fold or selection to another item.
    #[cfg(test)]
    pub(crate) fn synchronize_transcript_interactions(&mut self) {
        let retained_keys = self
            .projection
            .items()
            .iter()
            .map(|item| item.key.clone())
            .collect::<HashSet<_>>();
        let old_len = self.transcript_item_interactions.len();
        self.transcript_item_interactions
            .retain(|key, _| retained_keys.contains(key));
        let mut changed = self.transcript_item_interactions.len() != old_len;

        for item in self.projection.items() {
            match self.transcript_item_interactions.entry(item.key.clone()) {
                std::collections::hash_map::Entry::Vacant(slot) => {
                    slot.insert(TranscriptItemInteraction {
                        mode: projected_item_default_display_mode(
                            item,
                            self.presentation_verbose,
                            self.thinking_display_mode,
                        ),
                        pinned: false,
                        raw: false,
                        was_streaming: item.streaming,
                    });
                    changed = true;
                }
                std::collections::hash_map::Entry::Occupied(mut slot) => {
                    let state = slot.get_mut();
                    if state.was_streaming
                        && !item.streaming
                        && !state.pinned
                        && item.kind == ProjectedKind::Thinking
                        && state.mode != TranscriptDisplayMode::Expanded
                    {
                        let finished_mode = self.thinking_display_mode;
                        if state.mode != finished_mode {
                            state.mode = finished_mode;
                            changed = true;
                        }
                    }
                    state.was_streaming = item.streaming;
                }
            }
        }

        if self.selected_transcript_key.as_ref().is_some_and(|key| {
            !retained_keys.contains(key)
                || !self.projection.items().iter().any(|item| {
                    item.key == *key && projected_item_is_visible(item, self.presentation_verbose)
                })
        }) {
            self.selected_transcript_key = None;
            changed = true;
        }
        if changed {
            self.bump_transcript_presentation_generation();
        }
    }

