    /// Drop renderer pointer observations that were accepted by the product
    /// router but not yet consumed by `AppView` when terminal ownership
    /// changes. A blocked writer ACK must not let a pre-suspend press pair with
    /// a post-resume release.
    pub(crate) fn retire_input_side_channels_for_terminal_generation(&mut self) {
        self.pending_transcript_view_actions
            .retain(|action| !action.is_terminal_generation_scoped_pointer_action());
        self.retire_focus_scoped_pointer_state();
    }

    fn retire_focus_scoped_pointer_state(&mut self) {
        self.composer.cancel_transient_mouse_interaction();
        self.last_mouse_position = None;
        self.mouse_scroll.cancel_stream();
    }

