    #[cfg(test)]
    fn bump_transcript_presentation_generation(&mut self) {
        self.transcript_presentation_generation =
            self.transcript_presentation_generation.wrapping_add(1);
    }

    #[cfg(test)]
    fn navigable_transcript_keys(&self) -> Vec<String> {
        self.projection
            .items()
            .iter()
            .filter(|item| projected_item_is_visible(item, self.presentation_verbose))
            .map(|item| item.key.clone())
            .collect()
    }

    #[cfg(test)]
    fn activate_scrollback_selection(&mut self) {
        self.synchronize_transcript_interactions();
        if self.selected_transcript_key.is_none() {
            self.selected_transcript_key = self.navigable_transcript_keys().pop();
            if self.selected_transcript_key.is_some() {
                self.pending_transcript_selection_scroll = Some(TranscriptSelectionDirection::Up);
                self.bump_transcript_presentation_generation();
            }
        }
    }

    #[cfg(test)]
    fn select_transcript_item(&mut self, direction: TranscriptSelectionDirection) {
        self.synchronize_transcript_interactions();
        let keys = self.navigable_transcript_keys();
        if keys.is_empty() {
            return;
        }
        let selected = self
            .selected_transcript_key
            .as_deref()
            .and_then(|key| keys.iter().position(|candidate| candidate == key));
        let next = match (selected, direction) {
            (None, TranscriptSelectionDirection::Down) => 0,
            (None, TranscriptSelectionDirection::Up) => keys.len() - 1,
            (Some(index), TranscriptSelectionDirection::Down) if index + 1 < keys.len() => {
                index + 1
            }
            (Some(index), TranscriptSelectionDirection::Up) if index > 0 => index - 1,
            (Some(index), TranscriptSelectionDirection::Down) => {
                self.scroll
                    .follow(self.transcript_line_count, self.transcript_viewport_height);
                index
            }
            (Some(index), TranscriptSelectionDirection::Up) => index,
        };
        if self.selected_transcript_key.as_ref() != Some(&keys[next]) {
            self.selected_transcript_key = Some(keys[next].clone());
            self.pending_transcript_selection_scroll = Some(direction);
            self.bump_transcript_presentation_generation();
        }
    }

    /// Select the topmost/bottommost visible entry after page or edge
    /// navigation. This mirrors the pinned scrollback's viewport-edge
    /// selection and never changes backend state.
    #[cfg(test)]
    fn select_transcript_viewport_edge(&mut self, prefer_top: bool) {
        if self.transcript_viewport_height == 0 || self.transcript_layout.width() == 0 {
            return;
        }
        let viewport_start = self.scroll.offset();
        let viewport_end = viewport_start.saturating_add(self.transcript_viewport_height);
        let candidate = self
            .navigable_transcript_keys()
            .into_iter()
            .filter_map(|key| {
                let (start, height) = self.transcript_layout.item_bounds(&key)?;
                let end = start.saturating_add(height);
                (start < viewport_end && end > viewport_start).then_some((key, start))
            });
        let candidate = if prefer_top {
            candidate.min_by_key(|(_, start)| *start)
        } else {
            candidate.max_by_key(|(_, start)| *start)
        };
        let Some((key, _)) = candidate else {
            return;
        };
        if self.selected_transcript_key.as_ref() != Some(&key) {
            self.selected_transcript_key = Some(key);
            self.pending_transcript_selection_scroll = None;
            self.bump_transcript_presentation_generation();
        }
    }

    #[cfg(test)]
    fn transcript_page_scroll_rows(&self) -> usize {
        let sticky_header = self
            .projection
            .items()
            .iter()
            .filter(|item| item.kind == ProjectedKind::User)
            .filter_map(|item| {
                let (start, height) = self.transcript_layout.item_bounds(&item.key)?;
                (start < self.scroll.offset()).then_some((start, height))
            })
            .max_by_key(|(start, _)| *start)
            .map_or(0, |(start, height)| {
                usize::from(crate::tui_ui::gradual_sticky_height(
                    u16::try_from(height).unwrap_or(u16::MAX),
                    4,
                    self.scroll.offset().saturating_sub(start),
                    u16::try_from(self.transcript_viewport_height).unwrap_or(u16::MAX),
                ))
            });
        self.transcript_viewport_height
            .saturating_sub(sticky_header)
            .saturating_sub(2)
            .max(1)
    }

    /// Return the first non-empty assistant entry in each turn's trailing
    /// assistant run. User projections delimit turns; renderer work
    /// projections delimit the final response run. System/status projections
    /// are skipped, matching the pinned scrollback response-anchor contract.
    #[cfg(test)]
    fn response_anchor_keys(&self) -> Vec<String> {
        let items = self.projection.items();
        let turn_starts = self.turn_start_indices();
        let mut anchors = Vec::with_capacity(turn_starts.len());
        for (turn_position, start) in turn_starts.iter().copied().enumerate() {
            let end = turn_starts
                .get(turn_position + 1)
                .copied()
                .unwrap_or(items.len());
            let mut anchor = None;
            for item in items[start..end].iter().rev() {
                match item.kind {
                    ProjectedKind::Assistant if !item.text.is_empty() => {
                        anchor = Some(item.key.clone());
                    }
                    ProjectedKind::Thinking
                    | ProjectedKind::ToolUse
                    | ProjectedKind::ToolResult
                    | ProjectedKind::TerminalOutput
                    | ProjectedKind::Progress => break,
                    ProjectedKind::User
                    | ProjectedKind::Assistant
                    | ProjectedKind::System
                    | ProjectedKind::Warning
                    | ProjectedKind::Error => {}
                }
            }
            if let Some(anchor) = anchor {
                anchors.push(anchor);
            }
        }
        anchors
    }

    #[cfg(test)]
    fn navigate_response_anchor(&mut self, direction: TranscriptSelectionDirection) {
        if self.transcript_viewport_height == 0 || self.transcript_layout.width() == 0 {
            return;
        }
        let current = self.scroll.offset();
        let anchors = self
            .response_anchor_keys()
            .into_iter()
            .filter_map(|key| {
                self.transcript_layout
                    .item_bounds(&key)
                    .map(|(start, _)| (key, start))
            })
            .collect::<Vec<_>>();
        let target = match direction {
            TranscriptSelectionDirection::Down => {
                anchors.into_iter().find(|(_, start)| *start > current)
            }
            TranscriptSelectionDirection::Up => anchors
                .into_iter()
                .rev()
                .find(|(_, start)| *start < current),
        };
        let Some((key, target)) = target else {
            return;
        };
        self.selected_transcript_key = Some(key);
        self.pending_transcript_selection_scroll = None;
        self.scroll.snap_to_offset(
            target,
            self.transcript_layout.total_lines(),
            self.transcript_viewport_height,
        );
        self.bump_transcript_presentation_generation();
    }

    /// Return the first projected user row for every backend user message.
    ///
    /// One SDK user envelope may contain multiple content blocks, while the
    /// pinned scrollback owns one turn per envelope. Consecutive user rows
    /// carrying the same envelope UUID in their stable projection keys are
    /// therefore one prompt, not multiple turns. Nested direct-progress user
    /// rows are not top-level turn delimiters.
    #[cfg(test)]
    fn turn_start_indices(&self) -> Vec<usize> {
        let mut last_identity: Option<&str> = None;
        self.projection
            .items()
            .iter()
            .enumerate()
            .filter_map(|(index, item)| {
                if !projected_item_is_visible(item, self.presentation_verbose) {
                    return None;
                }
                let identity = projected_turn_prompt_identity(item)?;
                if Some(identity) == last_identity {
                    return None;
                }
                last_identity = Some(identity);
                Some(index)
            })
            .collect()
    }

    #[cfg(test)]
    fn activate_turn_start(&mut self, index: usize) {
        let Some(item) = self.projection.items().get(index) else {
            return;
        };
        self.selected_transcript_key = Some(item.key.clone());
        self.pending_transcript_selection_scroll = None;
        if let Some((start, _)) = self.transcript_layout.item_bounds(&item.key) {
            self.scroll.snap_to_offset(
                start,
                self.transcript_layout.total_lines(),
                self.transcript_viewport_height,
            );
        } else {
            self.pending_transcript_selection_scroll = Some(TranscriptSelectionDirection::Down);
        }
        self.bump_transcript_presentation_generation();
    }

    #[cfg(test)]
    fn navigate_turn(&mut self, direction: TranscriptSelectionDirection) {
        self.synchronize_transcript_interactions();
        let starts = self.turn_start_indices();
        if starts.is_empty() {
            return;
        }
        let selected_index = self.selected_transcript_key.as_deref().and_then(|key| {
            self.projection
                .items()
                .iter()
                .position(|item| item.key == key)
        });
        let current_turn = selected_index.and_then(|selected| {
            starts
                .iter()
                .enumerate()
                .rev()
                .find(|(_, start)| **start <= selected)
                .map(|(turn, _)| turn)
        });
        let target = match direction {
            TranscriptSelectionDirection::Down => match current_turn {
                Some(current) => (current + 1).min(starts.len() - 1),
                None => 0,
            },
            TranscriptSelectionDirection::Up => {
                let Some(current) = current_turn else {
                    return;
                };
                let current_start = starts[current];
                if selected_index != Some(current_start) {
                    current_start
                } else if current > 0 {
                    starts[current - 1]
                } else {
                    let Some(pre_turn) =
                        self.projection.items()[..current_start]
                            .iter()
                            .position(|item| {
                                projected_item_is_visible(item, self.presentation_verbose)
                            })
                    else {
                        return;
                    };
                    pre_turn
                }
            }
        };
        let index = if direction == TranscriptSelectionDirection::Down {
            starts[target]
        } else {
            target
        };
        self.activate_turn_start(index);
    }

    #[cfg(test)]
    fn toggle_selected_raw(&mut self) {
        self.synchronize_transcript_interactions();
        let Some(key) = self.selected_transcript_key.clone() else {
            self.status = self
                .renderer_ui_language
                .text("尚未选择对话条目", "No transcript item selected")
                .to_string();
            return;
        };
        let supports_raw = self
            .projection
            .items()
            .iter()
            .find(|item| item.key == key)
            .is_some_and(|item| {
                matches!(
                    item.kind,
                    ProjectedKind::Assistant | ProjectedKind::Thinking
                )
            });
        if !supports_raw {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选对话条目不支持 Markdown 源码模式",
                    "Selected transcript item has no raw Markdown mode",
                )
                .to_string();
            return;
        }
        let Some(interaction) = self.transcript_item_interactions.get_mut(&key) else {
            return;
        };
        interaction.raw = !interaction.raw;
        self.status = match (self.renderer_ui_language, interaction.raw) {
            (UiLanguage::ZhCn, true) => "正在显示 Markdown 源码".to_string(),
            (UiLanguage::ZhCn, false) => "正在显示渲染后的 Markdown".to_string(),
            (UiLanguage::EnUs, true) => "Showing raw Markdown source".to_string(),
            (UiLanguage::EnUs, false) => "Showing rendered Markdown".to_string(),
        };
        self.pending_transcript_selection_scroll = Some(TranscriptSelectionDirection::Down);
        self.bump_transcript_presentation_generation();
    }

    fn selected_block_source_index(&self) -> Option<usize> {
        let selected = self.selected_transcript_key.as_deref()?;
        self.projection
            .items()
            .iter()
            .position(|item| item.key == selected)
    }

    fn correlated_result_index(&self, source_index: usize) -> Option<usize> {
        let item = self.projection.items().get(source_index)?;
        if item.kind != ProjectedKind::ToolUse {
            return Some(source_index);
        }
        let tool_use_id = item.tool_use_id.as_deref()?;
        self.projection
            .items()
            .iter()
            .enumerate()
            .skip(source_index + 1)
            .filter(|(_, candidate)| {
                candidate.tool_use_id.as_deref() == Some(tool_use_id)
                    && matches!(
                        candidate.kind,
                        ProjectedKind::ToolResult | ProjectedKind::TerminalOutput
                    )
            })
            .map(|(index, _)| index)
            .next_back()
    }

    fn copy_selected_block_content(&mut self) {
        #[cfg(test)]
        self.synchronize_transcript_interactions();
        let Some(source_index) = self.selected_block_source_index() else {
            self.status = self
                .renderer_ui_language
                .text("尚未选择对话条目", "No transcript item selected")
                .to_string();
            return;
        };
        let Some(content_index) = self.correlated_result_index(source_index) else {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块暂时没有可复制内容",
                    "Selected block has no copyable content yet",
                )
                .to_string();
            return;
        };
        #[cfg(test)]
        let source = &self.projection.items()[source_index];
        let content = &self.projection.items()[content_index];
        #[cfg(test)]
        let raw = self
            .transcript_item_interactions
            .get(&source.key)
            .is_some_and(|interaction| interaction.raw);
        #[cfg(not(test))]
        let raw = self.renderer_selected_raw;
        let Some(text) = crate::tui_ui::projected_item_copy_text(content, raw) else {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块不支持复制内容",
                    "Selected block does not support content copy",
                )
                .to_string();
            return;
        };
        if text.is_empty() {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块暂时没有可复制内容",
                    "Selected block has no copyable content yet",
                )
                .to_string();
            return;
        }
        match crate::tui_clipboard::set_text(&text) {
            Ok(()) => {
                self.status = self
                    .renderer_ui_language
                    .text("已复制所选内容块", "Copied selected block content")
                    .to_string();
            }
            Err(error) => {
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("复制所选内容块失败：{error}"),
                    UiLanguage::EnUs => format!("Failed to copy selected block: {error}"),
                };
            }
        }
    }

    fn copy_selected_block_meta(&mut self) {
        #[cfg(test)]
        self.synchronize_transcript_interactions();
        let Some(selected_index) = self.selected_block_source_index() else {
            self.status = self
                .renderer_ui_language
                .text("尚未选择对话条目", "No transcript item selected")
                .to_string();
            return;
        };
        let selected = &self.projection.items()[selected_index];
        let tool_use = selected
            .tool_use_id
            .as_deref()
            .and_then(|tool_use_id| {
                self.projection.items()[..=selected_index]
                    .iter()
                    .rev()
                    .find(|candidate| {
                        candidate.tool_use_id.as_deref() == Some(tool_use_id)
                            && candidate.kind == ProjectedKind::ToolUse
                    })
            })
            .or_else(|| (selected.kind == ProjectedKind::ToolUse).then_some(selected));
        let Some(text) = tool_use.and_then(projected_tool_copy_meta) else {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块没有可复制的命令或路径",
                    "Selected block has no copyable command or path",
                )
                .to_string();
            return;
        };
        match crate::tui_clipboard::set_text(&text) {
            Ok(()) => {
                self.status = self
                    .renderer_ui_language
                    .text("已复制所选内容块的元数据", "Copied selected block metadata")
                    .to_string();
            }
            Err(error) => {
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("复制所选内容块元数据失败：{error}"),
                    UiLanguage::EnUs => {
                        format!("Failed to copy selected block metadata: {error}")
                    }
                };
            }
        }
    }

    /// Complete the fixed textarea clipboard lifecycle through CrabCode's
    /// existing direct-TUI route. The textarea reports copy/cut gestures
    /// through this notification slot unless its host installs a provider;
    /// leaving it unread makes selection appear locally without reaching the
    /// native, tmux, or OSC 52 clipboard legs.
    fn deliver_composer_clipboard(&mut self) {
        let Some(text) = self.composer.take_clipboard() else {
            return;
        };
        match crate::tui_clipboard::set_text(&text) {
            Ok(()) => {
                self.status = self
                    .renderer_ui_language
                    .text("已复制输入区选中内容", "Copied composer selection")
                    .to_string();
            }
            Err(error) => {
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("复制输入区选中内容失败：{error}"),
                    UiLanguage::EnUs => {
                        format!("Failed to copy composer selection: {error}")
                    }
                };
            }
        }
    }

    pub(crate) fn open_selected_block_viewer_without_link(&mut self) {
        #[cfg(test)]
        self.synchronize_transcript_interactions();
        let Some(source_index) = self.selected_block_source_index() else {
            return;
        };
        let source = &self.projection.items()[source_index];
        if !matches!(
            source.kind,
            ProjectedKind::Assistant
                | ProjectedKind::Thinking
                | ProjectedKind::ToolUse
                | ProjectedKind::ToolResult
                | ProjectedKind::TerminalOutput
        ) {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块不支持全屏查看",
                    "Selected block has no full-screen viewer",
                )
                .to_string();
            return;
        }
        let content_index = self
            .correlated_result_index(source_index)
            .unwrap_or(source_index);
        let content = &self.projection.items()[content_index];
        let body = if content.text.is_empty() {
            source.text.clone()
        } else {
            content.text.clone()
        };
        if body.is_empty() {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块暂时没有可查看内容",
                    "Selected block has no viewable content yet",
                )
                .to_string();
            return;
        }
        self.overlay = Some(Overlay::new(
            OverlayKind::BlockViewer,
            source.title.clone(),
            body,
        ));
    }

    fn stop_selected_background_task(&mut self) -> Vec<HostAction> {
        let Some(task_id) = self
            .selected_transcript_key
            .as_deref()
            .and_then(|key| key.strip_prefix("task:"))
            .filter(|task_id| self.active_tasks.contains_key(*task_id))
            .map(str::to_string)
        else {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选内容块不是正在运行的后台任务",
                    "Selected block is not a running background task",
                )
                .to_string();
            return Vec::new();
        };
        vec![HostAction::SendControl {
            request: json!({"subtype": "stop_task", "task_id": task_id}),
            purpose: OutboundPurpose::StopTask { task_id },
        }]
    }

    #[cfg(test)]
    fn mutate_selected_display_mode(
        &mut self,
        mutate: impl FnOnce(
            &crate::sdk_projection::ProjectedItem,
            TranscriptDisplayMode,
        ) -> TranscriptDisplayMode,
    ) {
        self.synchronize_transcript_interactions();
        let Some(key) = self.selected_transcript_key.clone() else {
            self.status = self
                .renderer_ui_language
                .text("尚未选择对话条目", "No transcript item selected")
                .to_string();
            return;
        };
        let Some(item) = self.projection.items().iter().find(|item| item.key == key) else {
            return;
        };
        if !projected_item_is_collapsible(item) {
            self.status = self
                .renderer_ui_language
                .text(
                    "所选对话条目不可折叠",
                    "Selected transcript item is not foldable",
                )
                .to_string();
            return;
        }
        let Some(state) = self.transcript_item_interactions.get_mut(&key) else {
            return;
        };
        let next = mutate(item, state.mode);
        if state.mode != next || !state.pinned {
            state.mode = next;
            state.pinned = true;
            self.pending_transcript_selection_scroll = Some(TranscriptSelectionDirection::Down);
            self.bump_transcript_presentation_generation();
        }
        self.status = match (self.renderer_ui_language, next) {
            (UiLanguage::ZhCn, TranscriptDisplayMode::Collapsed) => {
                "所选对话条目已折叠".to_string()
            }
            (UiLanguage::ZhCn, TranscriptDisplayMode::Truncated) => {
                "所选对话条目已截短".to_string()
            }
            (UiLanguage::ZhCn, TranscriptDisplayMode::Expanded) => "所选对话条目已展开".to_string(),
            (UiLanguage::EnUs, TranscriptDisplayMode::Collapsed) => {
                "Selected transcript item collapsed".to_string()
            }
            (UiLanguage::EnUs, TranscriptDisplayMode::Truncated) => {
                "Selected transcript item truncated".to_string()
            }
            (UiLanguage::EnUs, TranscriptDisplayMode::Expanded) => {
                "Selected transcript item expanded".to_string()
            }
        };
    }

    #[cfg(test)]
    fn toggle_expand_all(&mut self) {
        self.synchronize_transcript_interactions();
        let any_collapsed = self.projection.items().iter().any(|item| {
            projected_item_is_collapsible(item)
                && self
                    .transcript_item_interactions
                    .get(&item.key)
                    .is_some_and(|state| state.mode == TranscriptDisplayMode::Collapsed)
        });
        let target = if any_collapsed {
            TranscriptDisplayMode::Expanded
        } else {
            TranscriptDisplayMode::Collapsed
        };
        let mut changed = false;
        for item in self.projection.items() {
            if !projected_item_is_collapsible(item) {
                continue;
            }
            if let Some(state) = self.transcript_item_interactions.get_mut(&item.key)
                && (state.mode != target || state.pinned)
            {
                state.mode = target;
                // The upstream all-entry action clears per-entry manual fold
                // pins; only a selected-entry fold establishes one.
                state.pinned = false;
                changed = true;
            }
        }
        if changed {
            self.pending_transcript_selection_scroll = Some(TranscriptSelectionDirection::Down);
            self.bump_transcript_presentation_generation();
        }
        self.status = match (self.renderer_ui_language, target) {
            (UiLanguage::ZhCn, TranscriptDisplayMode::Expanded) => {
                "已展开所有可折叠对话条目".to_string()
            }
            (UiLanguage::ZhCn, _) => "已折叠所有可折叠对话条目".to_string(),
            (UiLanguage::EnUs, TranscriptDisplayMode::Expanded) => {
                "Expanded all foldable transcript items".to_string()
            }
            (UiLanguage::EnUs, _) => "Collapsed all foldable transcript items".to_string(),
        };
    }

    #[cfg(test)]
    fn toggle_all_thinking(&mut self) {
        self.synchronize_transcript_interactions();
        let any_collapsed = self.projection.items().iter().any(|item| {
            item.kind == ProjectedKind::Thinking
                && self
                    .transcript_item_interactions
                    .get(&item.key)
                    .is_some_and(|state| state.mode == TranscriptDisplayMode::Collapsed)
        });
        let target = if any_collapsed {
            TranscriptDisplayMode::Expanded
        } else {
            TranscriptDisplayMode::Collapsed
        };
        self.thinking_display_mode = target;
        let mut changed = false;
        for item in self
            .projection
            .items()
            .iter()
            .filter(|item| item.kind == ProjectedKind::Thinking)
        {
            if let Some(state) = self.transcript_item_interactions.get_mut(&item.key)
                && (state.mode != target || state.pinned)
            {
                state.mode = target;
                // The upstream all-thinking action establishes a sticky
                // session default rather than a per-entry manual pin.
                state.pinned = false;
                changed = true;
            }
        }
        if changed {
            self.pending_transcript_selection_scroll = Some(TranscriptSelectionDirection::Down);
            self.bump_transcript_presentation_generation();
        }
        self.status = match (self.renderer_ui_language, target) {
            (UiLanguage::ZhCn, TranscriptDisplayMode::Expanded) => {
                "已展开所有思考内容块".to_string()
            }
            (UiLanguage::ZhCn, _) => "已折叠所有思考内容块".to_string(),
            (UiLanguage::EnUs, TranscriptDisplayMode::Expanded) => {
                "Expanded all thinking blocks".to_string()
            }
            (UiLanguage::EnUs, _) => "Collapsed all thinking blocks".to_string(),
        };
    }

    pub fn initial_actions(&mut self) -> Vec<HostAction> {
        if self.setup_lifecycle_phase == SetupLifecyclePhase::InitializeAuthorized {
            // Emit the existing SDK initialize exactly once. The renderer
            // session stashes it until historical setup has completed, then
            // transfers it unchanged as StructuredIO's first runtime line.
            self.setup_lifecycle_phase = SetupLifecyclePhase::Initializing;
            self.status = self
                .renderer_ui_language
                .text(
                    "CrabCode 设置 · 正在初始化直连运行环境",
                    "CrabCode setup · initializing direct runtime",
                )
                .to_string();
            return vec![HostAction::Initialize];
        }
        if self.setup_lifecycle_phase != SetupLifecyclePhase::Initialized {
            return Vec::new();
        }
        if self.initial_dispatched || self.startup_barrier_pending {
            return Vec::new();
        }
        self.initial_dispatched = true;
        self.take_initial_prompt_action().into_iter().collect()
    }

    /// Transfer a prompt held while replacing one direct runtime with another.
    pub fn take_deferred_initial_prompt(&mut self) -> Option<String> {
        self.initial_prompt.take()
    }

    pub fn handle_runtime_event(&mut self, event: RuntimeEvent) -> Vec<HostAction> {
        match event {
            RuntimeEvent::Envelope(envelope) => {
                let is_hidden_or_replayed_context = [
                    "isMeta",
                    "isSynthetic",
                    "isReplay",
                    "isReconstructedHistory",
                    "isVirtual",
                    "isVisibleInTranscriptOnly",
                ]
                .iter()
                .any(|field| {
                    envelope
                        .value
                        .get(*field)
                        .and_then(Value::as_bool)
                        .unwrap_or(false)
                });
                let observes_conversation_context = matches!(
                    &envelope.classification,
                    crate::sdk_runtime::EnvelopeClass::Assistant
                        | crate::sdk_runtime::EnvelopeClass::User
                ) && !is_hidden_or_replayed_context;
                let stream_event_type = match &envelope.classification {
                    crate::sdk_runtime::EnvelopeClass::StreamEvent { event_type } => {
                        event_type.clone()
                    }
                    _ => None,
                };
                let stream_sources_nonempty = stream_event_type.as_deref() == Some("sources")
                    && envelope
                        .value
                        .pointer("/event/sources")
                        .and_then(Value::as_array)
                        .is_some_and(|sources| !sources.is_empty());
                let request_activity_class = match &envelope.classification {
                    crate::sdk_runtime::EnvelopeClass::StreamEvent { .. } => 1_u8,
                    crate::sdk_runtime::EnvelopeClass::Assistant
                    | crate::sdk_runtime::EnvelopeClass::Result => 2_u8,
                    _ => 0_u8,
                };
                let turn_activity_hint = renderer_turn_activity_hint(&envelope.classification);
                if self.observe_extra_usage_runtime_pair(&envelope) {
                    // The historical JSX command replaced a successful
                    // browser-opened result with Login instead of rendering
                    // the intermediate text. Reuse the already-established
                    // authentication control; no renderer field is added to
                    // the direct event or public protocol.
                    self.status = self
                        .renderer_ui_language
                        .text(
                            "正在根据 /extra-usage 启动新登录。按 Ctrl-C 退出并使用现有账户。",
                            EXTRA_USAGE_LOGIN_STARTING_MESSAGE,
                        )
                        .to_string();
                    return vec![HostAction::SendControl {
                        request: json!({"subtype": "crabcode_authenticate"}),
                        purpose: OutboundPurpose::LoginStart,
                    }];
                }
                let private_runtime_result = match &envelope.classification {
                    crate::sdk_runtime::EnvelopeClass::PrivateRuntimeResult {
                        request_id,
                        result_kind,
                        validation_error,
                    } => Some((
                        request_id.clone(),
                        result_kind.clone(),
                        validation_error.clone(),
                        envelope.value.clone(),
                    )),
                    _ => None,
                };
                self.observe_client_runtime_state(&envelope);
                // A raw diagnostic envelope may be evicted immediately when
                // Projection enforces its byte budget. Retain only the typed
                // media-artifact provenance needed by presentation before
                // that lossless diagnostic retention policy runs.
                self.transcript_artifacts.ingest_envelope(&envelope);
                let effect = self.projection.ingest(envelope);
                self.turn_status.observe_direct_stream(
                    self.projection.direct_stream_activity(),
                    Instant::now(),
                );
                if let Some(activity) = turn_activity_hint {
                    self.turn_status.set_activity(activity, Instant::now());
                } else if self.turn_status.activity() == Some(TurnActivity::Retrying)
                    && self.projection.direct_stream_activity().turn_generation == 0
                {
                    // A standalone historical API retry is presentation-only;
                    // the first later record closes it when no model-request
                    // lifecycle was ever opened.
                    self.turn_status.finish(TurnOutcome::Complete);
                }
                let transition_envelope =
                    matches!(&effect, ProjectionEffect::SessionTransition { .. }).then(|| {
                        self.projection
                            .raw_envelopes()
                            .last()
                            .expect("the transition envelope remains in the diagnostic window")
                            .clone()
                    });
                // A validated Some(old) -> Some(new) SDK identity is the
                // existing backend's /clear boundary. Reset old
                // renderer-owned state before observing the triggering
                // envelope so its task/artifact state enters the new session
                // normally.
                let (effect, mut transition_actions) = self.prepare_projection_effect(effect);
                if observes_conversation_context {
                    // This runs after a validated session transition resets
                    // renderer state, so the triggering visible record starts
                    // the new conversation instead of being overwritten by
                    // the reset.
                    self.mark_conversation_started();
                    self.context_usage_is_baseline = false;
                    self.baseline_context_send_users_pending = 0;
                }
                if let Some(envelope) = transition_envelope.as_ref() {
                    self.observe_client_runtime_state(envelope);
                    self.transcript_artifacts.ingest_envelope(envelope);
                }
                self.synchronize_goal_report_projection();
                self.synchronize_renderer_watchers(Instant::now());
                let effect_allows_request_activity = !matches!(
                    &effect,
                    ProjectionEffect::CompatibilityFault { .. }
                        | ProjectionEffect::AbortTurn { .. }
                        | ProjectionEffect::FailClosed { .. }
                );
                let stream_event_advances_request_activity = match stream_event_type.as_deref() {
                    Some("sources") => stream_sources_nonempty && effect_allows_request_activity,
                    Some("ping") | None => false,
                    Some(_) => effect_allows_request_activity,
                };
                let advances_request_activity = self.stream_requesting
                    && ((request_activity_class == 2 && effect_allows_request_activity)
                        || (request_activity_class == 1 && stream_event_advances_request_activity));
                if advances_request_activity {
                    self.stream_requesting = false;
                    self.status = self
                        .renderer_ui_language
                        .text("CrabCode 正在回复", "CrabCode is responding")
                        .to_string();
                }
                #[cfg(test)]
                {
                    self.synchronize_transcript_interactions();
                    self.scroll
                        .clamp(self.transcript_line_count, self.transcript_viewport_height);
                }
                transition_actions.extend(self.handle_projection_effect(effect));
                let mut actions = transition_actions;
                if let Some((request_id, result_kind, validation_error, value)) =
                    private_runtime_result
                {
                    actions.extend(self.handle_private_runtime_result(
                        request_id,
                        result_kind,
                        validation_error,
                        &value,
                    ));
                }
                actions
            }
            RuntimeEvent::Fatal(fatal) => {
                self.pending_extra_usage_output = false;
                self.turn_status
                    .set_watchers(Watchers::default(), Instant::now());
                self.turn_status.finish(TurnOutcome::RuntimeStopped);
                self.fail_closed_after_runtime_stopped(fatal.reason);
                Vec::new()
            }
            RuntimeEvent::ChildExited(exit) => {
                self.pending_extra_usage_output = false;
                self.turn_status
                    .set_watchers(Watchers::default(), Instant::now());
                self.turn_status.finish(if exit.expected {
                    TurnOutcome::Complete
                } else {
                    TurnOutcome::RuntimeStopped
                });
                if !exit.expected {
                    if self.fatal.is_none() {
                        self.fail_closed_after_runtime_stopped(format!(
                            "CrabCode runtime exited unexpectedly (success={}, code={:?})",
                            exit.success, exit.code
                        ));
                    }
                } else if self.fatal.is_none() {
                    self.status = self
                        .renderer_ui_language
                        .text("CrabCode 运行环境已关闭", "CrabCode runtime closed")
                        .to_string();
                }
                Vec::new()
            }
        }
    }

    pub fn record_control_request(&mut self, request_id: String, purpose: OutboundPurpose) {
        self.pending_outbound.insert(request_id, purpose);
    }

    pub(crate) fn set_renderer_diagnostics(
        &mut self,
        diagnostics: crate::renderer_diagnostics::RendererDiagnostics,
    ) {
        self.projection.set_renderer_diagnostics(diagnostics);
    }

    pub(crate) fn interrupt_outbound_purpose(&self) -> OutboundPurpose {
        self.turn_abort_pending
            .as_ref()
            .map_or(OutboundPurpose::Interrupt, |abort| {
                OutboundPurpose::AbortTurnInterrupt {
                    sequence: abort.sequence,
                    code: abort.code.clone(),
                }
            })
    }

    /// Build one request in the closed post-setup native TUI action lane.
    /// The SDK transport validates the concrete action object before it can
    /// enter the writer queue; this counter is only process-local correlation.
    pub(crate) fn private_runtime_action(
        &mut self,
        action: Value,
        purpose: PrivateRuntimePurpose,
    ) -> HostAction {
        let request_id = format!(
            "crabcode-tui-runtime-{}",
            self.next_private_runtime_request_id
        );
        self.next_private_runtime_request_id =
            self.next_private_runtime_request_id.saturating_add(1);
        if purpose == PrivateRuntimePurpose::BugReportSubmit {
            debug_assert!(
                self.bug_report_inflight_request_id.is_none(),
                "the renderer must admit at most one bug report at a time"
            );
            self.bug_report_inflight_request_id = Some(request_id.clone());
        }
        HostAction::SendPrivateRuntimeAction {
            request_id,
            action,
            purpose,
        }
    }

    pub(crate) fn private_runtime_health_snapshot_action(&mut self) -> HostAction {
        self.private_runtime_action(
            json!({"kind":"health_snapshot"}),
            PrivateRuntimePurpose::HealthSnapshot,
        )
    }

    fn model_management_effects(
        &mut self,
        effects: impl IntoIterator<Item = ModelManagementEffect>,
    ) -> Vec<HostAction> {
        let mut actions = Vec::new();
        for effect in effects {
            match effect {
                ModelManagementEffect::Private { action, purpose } => {
                    actions.push(self.private_runtime_action(action, purpose));
                }
                ModelManagementEffect::SetModel(model) => {
                    self.retire_model_management_private_requests();
                    self.model_management = None;
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => format!("已请求切换模型为 {model}"),
                        UiLanguage::EnUs => format!("Requested model change to {model}"),
                    };
                    actions.push(HostAction::SendControl {
                        request: json!({"subtype":"set_model","model":model}),
                        purpose: OutboundPurpose::SetModel,
                    });
                }
                ModelManagementEffect::OpenUrl(url) => {
                    if safe_standard_url_target(&url).is_some() {
                        self.pending_link_open = Some(LinkTarget::Url(Arc::from(url)));
                    } else if let Some(management) = self.model_management.as_mut() {
                        management
                            .apply_error(self.renderer_ui_language, "account-login-url-unsafe");
                    }
                }
                ModelManagementEffect::Close => {
                    self.retire_model_management_private_requests();
                    self.model_management = None;
                    self.status = self
                        .renderer_ui_language
                        .text("已退出模型管理", "Closed model management")
                        .to_string();
                }
            }
        }
        actions
    }

    fn open_model_management(&mut self, local: bool) -> Vec<HostAction> {
        self.command_palette = CommandPaletteState::default();
        let (state, initial) = if local {
            ModelManagementState::open_local()
        } else {
            ModelManagementState::open()
        };
        self.model_management = Some(state);
        self.status = self
            .renderer_ui_language
            .text(
                "正在读取直连模型管理状态",
                "Loading direct model management state",
            )
            .to_string();
        self.model_management_effects([initial])
    }

    fn retained_command_effect(
        &mut self,
        effect: Option<RetainedCommandEffect>,
    ) -> Vec<HostAction> {
        let Some(effect) = effect else {
            if let Some(notice) = self.retained_commands.notice() {
                self.status = notice.to_string();
            }
            return Vec::new();
        };
        let purpose = PrivateRuntimePurpose::from_retained(effect.purpose);
        vec![self.private_runtime_action(effect.action, purpose)]
    }

    fn request_retained_identity_snapshot(&mut self) -> Vec<HostAction> {
        let effect = self.retained_commands.identity_snapshot();
        self.retained_command_effect(effect)
    }

    fn run_retained_color(&mut self, argument: &str) -> Vec<HostAction> {
        let effect = self
            .retained_commands
            .color(argument, self.renderer_ui_language);
        if effect.is_none() {
            return self.retained_command_effect(effect);
        }
        self.status = self
            .renderer_ui_language
            .text("正在设置会话颜色", "Setting session color")
            .to_string();
        let mut actions = if self.retained_commands.identity_snapshot_retry_needed() {
            self.request_retained_identity_snapshot()
        } else {
            Vec::new()
        };
        actions.extend(self.retained_command_effect(effect));
        actions
    }

    fn run_retained_rename(&mut self, argument: &str) -> Vec<HostAction> {
        let effect = self.retained_commands.rename(argument);
        if effect.is_none() {
            return self.retained_command_effect(effect);
        }
        self.status = self
            .renderer_ui_language
            .text("正在重命名会话", "Renaming session")
            .to_string();
        let mut actions = if self.retained_commands.identity_snapshot_retry_needed() {
            self.request_retained_identity_snapshot()
        } else {
            Vec::new()
        };
        actions.extend(self.retained_command_effect(effect));
        actions
    }

    fn usage_plugin_management_effects(
        &mut self,
        effects: impl IntoIterator<Item = UsagePluginManagementEffect>,
    ) -> Vec<HostAction> {
        let mut actions = Vec::new();
        for effect in effects {
            match effect {
                UsagePluginManagementEffect::Private {
                    token,
                    purpose,
                    action,
                } => {
                    let purpose = PrivateRuntimePurpose::from_usage_plugin(token, purpose);
                    actions.push(self.private_runtime_action(action.value(), purpose));
                }
                UsagePluginManagementEffect::Close => {
                    self.retire_usage_plugin_management_private_requests();
                    self.usage_plugin_management = None;
                    self.status = self
                        .renderer_ui_language
                        .text("已关闭用量/插件管理面板", "Closed usage/plugin management")
                        .to_string();
                }
            }
        }
        actions
    }

    fn open_usage_management(&mut self) -> Vec<HostAction> {
        self.command_palette = CommandPaletteState::default();
        let (state, initial) = UsagePluginManagementState::open_usage();
        self.usage_plugin_management = Some(state);
        self.status = self
            .renderer_ui_language
            .text("正在读取直连用量状态", "Loading direct usage state")
            .to_string();
        self.usage_plugin_management_effects([initial])
    }

    fn open_plugin_management(&mut self, arguments: &str) -> Vec<HostAction> {
        self.command_palette = CommandPaletteState::default();
        let (state, initial) = UsagePluginManagementState::open_plugin(arguments);
        self.usage_plugin_management = Some(state);
        self.status = self
            .renderer_ui_language
            .text(
                "正在读取直连插件管理状态",
                "Loading direct plugin management state",
            )
            .to_string();
        self.usage_plugin_management_effects(initial)
    }

    pub(crate) fn record_private_runtime_action(
        &mut self,
        request_id: String,
        purpose: PrivateRuntimePurpose,
    ) {
        if purpose == PrivateRuntimePurpose::BugReportSubmit {
            debug_assert_eq!(
                self.bug_report_inflight_request_id.as_deref(),
                Some(request_id.as_str()),
                "bug-report writer admission must retain exact renderer correlation"
            );
        }
        self.pending_private_runtime.insert(
            request_id,
            PendingPrivateRuntimeRequest {
                purpose,
                renderer_target_active: true,
            },
        );
    }

    fn retire_model_management_private_requests(&mut self) {
        for request in self.pending_private_runtime.values_mut() {
            if request.purpose.is_model_management() {
                request.renderer_target_active = false;
            }
        }
    }

    fn retire_usage_plugin_management_private_requests(&mut self) {
        for request in self.pending_private_runtime.values_mut() {
            if request.purpose.usage_plugin_token().is_some() {
                request.renderer_target_active = false;
            }
        }
    }

    #[cfg(test)]
    pub(crate) fn private_runtime_health_ready(&self) -> bool {
        self.private_runtime_health_ready
    }

    fn handle_private_runtime_result(
        &mut self,
        request_id: Option<String>,
        result_kind: Option<String>,
        validation_error: Option<String>,
        value: &Value,
    ) -> Vec<HostAction> {
        let Some(request_id) = request_id else {
            self.status = self
                .renderer_ui_language
                .text(
                    "已拒绝无法关联的 TUI 私有运行结果；会话继续运行",
                    "Rejected an uncorrelatable private TUI runtime result; session remains active",
                )
                .to_string();
            return Vec::new();
        };
        let pending = self.pending_private_runtime.remove(&request_id);
        if pending
            .as_ref()
            .is_some_and(|request| !request.renderer_target_active)
        {
            // A user may close one management instance and immediately open
            // another. The old request still owns its process correlation,
            // but its result must never mutate the replacement surface.
            return Vec::new();
        }
        let purpose = pending.map(|request| request.purpose);
        if purpose.as_ref() == Some(&PrivateRuntimePurpose::BugReportSubmit) {
            if self.bug_report_inflight_request_id.as_deref() != Some(request_id.as_str()) {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "已忽略与当前错误报告不匹配的过期结果",
                        "Ignored a stale result that did not match the active bug report",
                    )
                    .to_string();
                return Vec::new();
            }
            // Every terminal correlated result closes the one-shot in-flight
            // lifecycle, including invalid, unconfirmed, and action-error
            // results. A later explicit command may then create a fresh id.
            self.bug_report_inflight_request_id = None;
        }
        if let Some(validation_error) = validation_error {
            if let Some(purpose) = purpose.as_ref() {
                if purpose == &PrivateRuntimePurpose::BugReportSubmit {
                    self.status = self
                        .renderer_ui_language
                        .text(
                            "错误报告返回了无效结果；无法确认是否提交成功",
                            "The bug report returned an invalid result; submission could not be confirmed",
                        )
                        .to_string();
                    return Vec::new();
                } else if let Some(token) = purpose.usage_plugin_token() {
                    if let Some(management) = self.usage_plugin_management.as_mut() {
                        management.apply_protocol_failure(
                            token,
                            self.renderer_ui_language,
                            &validation_error,
                        );
                    }
                } else if let Some(retained) = purpose.retained() {
                    self.retained_commands.apply_error(
                        retained,
                        self.renderer_ui_language,
                        &validation_error,
                    );
                } else if purpose.is_model_management()
                    && let Some(management) = self.model_management.as_mut()
                {
                    management.apply_error(self.renderer_ui_language, &validation_error);
                }
            }
            self.status = match self.renderer_ui_language {
                UiLanguage::ZhCn => format!(
                    "已拒绝 TUI 私有运行结果 {request_id}；会话继续运行：{validation_error}"
                ),
                UiLanguage::EnUs => format!(
                    "Rejected private TUI runtime result {request_id}; session remains active: {validation_error}"
                ),
            };
            return Vec::new();
        }
        let Some(purpose) = purpose else {
            self.status = match self.renderer_ui_language {
                UiLanguage::ZhCn => {
                    format!("已忽略无待处理请求的 TUI 私有运行结果 {request_id}")
                }
                UiLanguage::EnUs => {
                    format!(
                        "Ignored private TUI runtime result without a pending request: {request_id}"
                    )
                }
            };
            return Vec::new();
        };

        match (purpose.clone(), result_kind.as_deref()) {
            (PrivateRuntimePurpose::BugReportSubmit, Some("bug_report_submitted")) => {
                match protocol_bug_report_feedback_id(value.pointer("/result/feedback_id")) {
                    Ok(feedback_id) => {
                        self.status = match self.renderer_ui_language {
                            UiLanguage::ZhCn => {
                                format!("错误报告已提交 · 反馈 ID：{feedback_id}")
                            }
                            UiLanguage::EnUs => {
                                format!("Bug report submitted · Feedback ID: {feedback_id}")
                            }
                        };
                    }
                    Err(_) => {
                        self.status = self
                            .renderer_ui_language
                            .text(
                                "错误报告已返回，但反馈 ID 无效；无法确认提交结果",
                                "The bug report returned an invalid feedback ID; submission could not be confirmed",
                            )
                            .to_string();
                    }
                }
            }
            (PrivateRuntimePurpose::BugReportSubmit, Some("bug_report_unconfirmed")) => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "服务可能已收到错误报告，但未返回反馈 ID；请勿立即重复提交",
                        "The service may have received the bug report but returned no feedback ID; do not resubmit immediately",
                    )
                    .to_string();
            }
            (PrivateRuntimePurpose::BugReportSubmit, Some(result_kind))
                if result_kind != "runtime_action_error" =>
            {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "错误报告结果与请求不匹配；无法确认是否提交成功",
                        "The bug report result did not match the request; submission could not be confirmed",
                    )
                    .to_string();
            }
            (PrivateRuntimePurpose::HealthSnapshot, Some("health_snapshot"))
                if value.pointer("/result/status").and_then(Value::as_str) == Some("ready") =>
            {
                self.private_runtime_health_ready = true;
            }
            (_, Some("runtime_action_error")) => {
                let code = value
                    .pointer("/result/code")
                    .and_then(Value::as_str)
                    .unwrap_or("invalid_request");
                self.status = if purpose == PrivateRuntimePurpose::BugReportSubmit {
                    match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("错误报告发送失败或结果无法确认：{code}；请勿立即重复提交")
                        }
                        UiLanguage::EnUs => format!(
                            "Bug report delivery failed or could not be confirmed: {code}; do not resubmit immediately"
                        ),
                    }
                } else {
                    match self.renderer_ui_language {
                        UiLanguage::ZhCn => format!("TUI 私有运行请求被拒绝：{code}"),
                        UiLanguage::EnUs => {
                            format!("Private TUI runtime request was rejected: {code}")
                        }
                    }
                };
                if purpose == PrivateRuntimePurpose::BugReportSubmit {
                    // The status above is the complete renderer lifecycle for
                    // this one-shot command.
                } else if let Some(token) = purpose.usage_plugin_token() {
                    let Some(management) = self.usage_plugin_management.as_mut() else {
                        // Closing a busy panel must not recreate it when the
                        // already-admitted request settles late.
                        return Vec::new();
                    };
                    management.apply_send_failure(token, self.renderer_ui_language, code);
                } else if let Some(retained) = purpose.retained() {
                    self.retained_commands
                        .apply_error(retained, self.renderer_ui_language, code);
                } else if purpose.is_model_management() {
                    let Some(management) = self.model_management.as_mut() else {
                        return Vec::new();
                    };
                    management.apply_error(self.renderer_ui_language, code);
                }
            }
            (PrivateRuntimePurpose::HealthSnapshot, _) => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "TUI 私有运行健康结果与请求不匹配；会话继续运行",
                        "Private TUI runtime health result did not match its request; session remains active",
                    )
                    .to_string();
            }
            (purpose, Some("retained_command_error")) if purpose.retained().is_some() => {
                let retained = purpose
                    .retained()
                    .expect("guarded retained private runtime purpose");
                if let Err(error) = self.retained_commands.apply_command_error(
                    retained,
                    value,
                    self.renderer_ui_language,
                ) {
                    self.retained_commands
                        .apply_error(retained, self.renderer_ui_language, &error);
                }
                if let Some(notice) = self.retained_commands.notice() {
                    self.status = notice.to_string();
                }
            }
            (purpose, Some(result_kind)) if purpose.retained().is_some() => {
                let retained = purpose
                    .retained()
                    .expect("guarded retained private runtime purpose");
                if let Err(error) = self.retained_commands.apply_result(
                    retained,
                    result_kind,
                    value,
                    self.renderer_ui_language,
                ) {
                    self.retained_commands
                        .apply_error(retained, self.renderer_ui_language, &error);
                }
                if let Some(notice) = self.retained_commands.notice() {
                    self.status = notice.to_string();
                }
            }
            (purpose, Some(_)) if purpose.usage_plugin_token().is_some() => {
                let Some(token) = purpose.usage_plugin_token() else {
                    return Vec::new();
                };
                let Some(management) = self.usage_plugin_management.as_mut() else {
                    // The user may close a busy management surface. Consume
                    // correlation, but never recreate state or project the
                    // late private result into the transcript.
                    return Vec::new();
                };
                let result = value.get("result").cloned().unwrap_or(Value::Null);
                let effects = management.apply_result(token, result, self.renderer_ui_language);
                return self.usage_plugin_management_effects(effects);
            }
            (purpose, Some(result_kind)) => {
                if self.model_management.is_none() {
                    // The user may close a busy model-management surface.
                    // Correlation still consumes the already-admitted result,
                    // but a late response never recreates renderer state or
                    // reaches the transcript projection.
                    return Vec::new();
                }
                let result = self
                    .model_management
                    .as_mut()
                    .ok_or_else(|| "model-management-modal-not-open".to_string())
                    .and_then(|management| {
                        management.apply_result(
                            &purpose,
                            result_kind,
                            value,
                            self.renderer_ui_language,
                        )
                    });
                match result {
                    Ok(effects) => return self.model_management_effects(effects),
                    Err(error) => {
                        if let Some(management) = self.model_management.as_mut() {
                            management.apply_error(self.renderer_ui_language, &error);
                        }
                        self.status = match self.renderer_ui_language {
                            UiLanguage::ZhCn => {
                                format!("已拒绝无效模型管理结果；会话继续运行：{error}")
                            }
                            UiLanguage::EnUs => format!(
                                "Rejected invalid model management result; session remains active: {error}"
                            ),
                        };
                    }
                }
            }
            (purpose, None) => {
                if purpose == PrivateRuntimePurpose::BugReportSubmit {
                    self.status = self
                        .renderer_ui_language
                        .text(
                            "错误报告结果缺少类型；无法确认是否提交成功",
                            "The bug report result omitted its kind; submission could not be confirmed",
                        )
                        .to_string();
                } else if let Some(token) = purpose.usage_plugin_token() {
                    if let Some(management) = self.usage_plugin_management.as_mut() {
                        management.apply_protocol_failure(
                            token,
                            self.renderer_ui_language,
                            "private-usage-plugin-result-kind-missing",
                        );
                    }
                    self.status = self
                        .renderer_ui_language
                        .text(
                            "用量/插件管理结果缺少类型；会话继续运行",
                            "Usage/plugin management result omitted its kind; session remains active",
                        )
                        .to_string();
                } else if let Some(retained) = purpose.retained() {
                    self.retained_commands.apply_error(
                        retained,
                        self.renderer_ui_language,
                        "private-retained-result-kind-missing",
                    );
                    if let Some(notice) = self.retained_commands.notice() {
                        self.status = notice.to_string();
                    }
                } else {
                    if let Some(management) = self.model_management.as_mut() {
                        management.apply_error(
                            self.renderer_ui_language,
                            "private-model-result-kind-missing",
                        );
                    }
                    self.status = self
                        .renderer_ui_language
                        .text(
                            "模型管理结果缺少类型；会话继续运行",
                            "Model management result omitted its kind; session remains active",
                        )
                        .to_string();
                }
            }
        }
        Vec::new()
    }

    /// Observe renderer-queue acceptance of an outbound action.
    ///
    /// For process-private setup responses, queue acceptance is the earliest
    /// safe point at which the child can read the response and publish its
    /// serial successor. Close the prior modal here so that successor cannot
    /// be mistaken for a concurrent interaction. Delivery failure after this
    /// point is fatal and never retried.
    pub(crate) fn action_admitted(&mut self, action: &HostAction) {
        if matches!(action, HostAction::SendUser { .. }) {
            // Renderer-queue acceptance is the single admission boundary for
            // interactive, initial, and programmatic prompts.
            self.mark_conversation_started();
            if self.context_usage_is_baseline || self.baseline_context_send_users_pending > 0 {
                self.context_usage_is_baseline = false;
                self.baseline_context_send_users_pending =
                    self.baseline_context_send_users_pending.saturating_add(1);
            }
            return;
        }
        let HostAction::RespondStartupInteraction {
            request_id,
            subtype,
            response,
        } = action
        else {
            return;
        };
        if subtype != CRABCODE_TUI_SETUP_SUBTYPE {
            return;
        }
        if !self
            .setup_responses_awaiting_completion
            .insert(request_id.clone())
        {
            self.fail_closed(format!(
                "CrabCode setup response {request_id} was admitted more than once"
            ));
            return;
        }
        let Some(kind) = response.get("kind").and_then(Value::as_str) else {
            self.fail_closed(format!(
                "admitted CrabCode setup response {request_id} omitted kind"
            ));
            return;
        };
        if kind == "workspace_trust"
            && response.get("decision").and_then(Value::as_str) == Some("reject")
        {
            self.status = self
                .renderer_ui_language
                .text(
                    "已拒绝工作区信任 · 正在等待直连运行环境退出",
                    "Workspace trust declined · waiting for direct runtime exit",
                )
                .to_string();
        }
        if dialog_request_id(self.dialog.as_ref()) == Some(request_id.as_str()) {
            self.finish_dialog();
        } else {
            self.projection.resolve_pending_control(request_id);
        }
    }

    pub fn action_failed(&mut self, action: &HostAction, error: impl ToString) {
        let error = error.to_string();
        match action {
            HostAction::RespondPermission { request_id, .. }
            | HostAction::RespondElicitation { request_id, .. } => {
                self.dialog_response_inflight = false;
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("回复请求 {request_id} 失败：{error}"),
                    UiLanguage::EnUs => {
                        format!("Failed to respond to request {request_id}: {error}")
                    }
                };
            }
            HostAction::RespondStartupInteraction {
                request_id,
                subtype,
                response,
            } => {
                self.setup_responses_awaiting_completion.remove(request_id);
                self.dialog_response_inflight = false;
                if subtype == CRABCODE_TUI_SETUP_SUBTYPE {
                    self.fail_closed(format!(
                        "failed to deliver CrabCode setup response {request_id} \
                         (kind={}): {error}",
                        response
                            .get("kind")
                            .and_then(Value::as_str)
                            .unwrap_or("<missing>")
                    ));
                } else if subtype == CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE {
                    self.fail_closed(format!(
                        "failed to acknowledge command catalog refresh {request_id}: {error}"
                    ));
                } else {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => format!("回复请求 {request_id} 失败：{error}"),
                        UiLanguage::EnUs => {
                            format!("Failed to respond to request {request_id}: {error}")
                        }
                    };
                }
            }
            HostAction::Initialize => {
                self.fail_closed(format!(
                    "failed to release the existing SDK initialize request after setup: {error}"
                ));
            }
            HostAction::Interrupt => {
                if let Some(abort) = self.turn_abort_pending.take() {
                    self.interrupt_pending = false;
                    self.fail_closed(format!(
                        "turn abort interrupt delivery failed at sequence {} ({}): {error}",
                        abort.sequence, abort.code
                    ));
                    return;
                }
                self.resume_after_interrupt_failure();
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("中断失败：{error}"),
                    UiLanguage::EnUs => format!("Interrupt failed: {error}"),
                };
            }
            HostAction::StopRuntime { .. } => {
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("协议错误后停止运行环境失败：{error}"),
                    UiLanguage::EnUs => {
                        format!("Runtime stop failed after protocol error: {error}")
                    }
                };
            }
            HostAction::SendControl {
                purpose: OutboundPurpose::SideQuestion { question },
                ..
            } => {
                self.restore_pending_composer_submission();
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::FinishSideQuestion {
                        question: question.clone(),
                        result: Err(match self.renderer_ui_language {
                            UiLanguage::ZhCn => format!("运行环境操作失败：{error}"),
                            UiLanguage::EnUs => format!("Runtime action failed: {error}"),
                        }),
                    },
                );
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("旁路提问发送失败：{error}"),
                    UiLanguage::EnUs => format!("Side question could not be sent: {error}"),
                };
            }
            HostAction::SendControl {
                purpose: OutboundPurpose::ContextUsageRefresh,
                ..
            } => {
                self.context_usage_refresh_pending = false;
            }
            HostAction::SendPrivateRuntimeAction {
                request_id,
                purpose,
                ..
            } => {
                let pending = self.pending_private_runtime.remove(request_id);
                if purpose == &PrivateRuntimePurpose::BugReportSubmit {
                    if self.bug_report_inflight_request_id.as_deref() != Some(request_id.as_str()) {
                        // A late failure for an already-settled report must
                        // neither release nor overwrite a newer report.
                        return;
                    }
                    self.bug_report_inflight_request_id = None;
                }
                if pending
                    .as_ref()
                    .is_some_and(|request| !request.renderer_target_active)
                {
                    // The originating management surface was deliberately
                    // closed. A late writer failure belongs to that retired
                    // instance and is not an error on a newly opened panel.
                    return;
                }
                debug_assert!(
                    pending
                        .as_ref()
                        .is_none_or(|request| request.purpose == *purpose)
                );
                if purpose == &PrivateRuntimePurpose::BugReportSubmit {
                    // This command has no modal state to retire or restore.
                } else if let Some(token) = purpose.usage_plugin_token() {
                    if let Some(management) = self.usage_plugin_management.as_mut() {
                        management.apply_send_failure(token, self.renderer_ui_language, &error);
                    }
                } else if let Some(retained) = purpose.retained() {
                    self.retained_commands
                        .apply_error(retained, self.renderer_ui_language, &error);
                } else if purpose.is_model_management()
                    && let Some(management) = self.model_management.as_mut()
                {
                    management.apply_error(self.renderer_ui_language, &error);
                }
                self.status = if purpose == &PrivateRuntimePurpose::BugReportSubmit {
                    match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("错误报告发送失败或结果无法确认：{error}；请勿立即重复提交")
                        }
                        UiLanguage::EnUs => format!(
                            "Bug report delivery failed or could not be confirmed: {error}; do not resubmit immediately"
                        ),
                    }
                } else {
                    match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("TUI 私有运行请求 {request_id} 发送失败；会话继续运行：{error}")
                        }
                        UiLanguage::EnUs => format!(
                            "Private TUI runtime request {request_id} could not be sent; session remains active: {error}"
                        ),
                    }
                };
            }
            HostAction::SendUser { .. } => {
                if self.baseline_context_send_users_pending > 0 {
                    self.baseline_context_send_users_pending -= 1;
                    if self.baseline_context_send_users_pending == 0 {
                        self.context_usage_is_baseline = true;
                    }
                }
                self.restore_pending_composer_submission();
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("运行环境操作失败；已恢复输入草稿：{error}"),
                    UiLanguage::EnUs => {
                        format!("Runtime action failed; composer restored: {error}")
                    }
                };
            }
            HostAction::SendControl { .. } => {
                self.restore_pending_composer_submission();
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("运行环境操作失败；已恢复输入草稿：{error}"),
                    UiLanguage::EnUs => {
                        format!("Runtime action failed; composer restored: {error}")
                    }
                };
            }
        }
    }

    pub fn action_succeeded(&mut self, action: &HostAction) {
        match action {
            HostAction::SendUser { content, .. } => {
                if self.baseline_context_send_users_pending > 0 {
                    self.baseline_context_send_users_pending = 0;
                    self.context_usage_is_baseline = false;
                }
                if let Some(submission) = self.pending_composer_submission.take() {
                    self.remember_composer_submission(&submission.text);
                    self.observe_successful_goal_submission(&submission.text);
                } else if let Some(submitted) = content.as_str() {
                    self.observe_successful_goal_submission(submitted);
                } else if self
                    .active_goal
                    .as_ref()
                    .is_some_and(|goal| goal.completed_sequence.is_some())
                {
                    self.active_goal = None;
                }
            }
            HostAction::SendControl { .. } => {
                if let Some(submission) = self.pending_composer_submission.take() {
                    self.remember_composer_submission(&submission.text);
                }
            }
            HostAction::SendPrivateRuntimeAction { .. } => {}
            HostAction::RespondPermission { request_id, .. }
            | HostAction::RespondElicitation { request_id, .. } => {
                if dialog_request_id(self.dialog.as_ref()) == Some(request_id.as_str()) {
                    self.finish_dialog();
                }
            }
            HostAction::RespondStartupInteraction {
                request_id,
                subtype,
                response,
            } => {
                if subtype == CRABCODE_TUI_SETUP_SUBTYPE {
                    if !self
                        .setup_responses_awaiting_completion
                        .contains(request_id)
                    {
                        self.action_admitted(action);
                        if self.fatal.is_some() {
                            return;
                        }
                    }
                    if !self.setup_responses_awaiting_completion.remove(request_id) {
                        self.fail_closed(format!(
                            "CrabCode setup response {request_id} completed without renderer-queue \
                             acceptance"
                        ));
                        return;
                    }
                    if self.session_picker_quit_after_response.as_deref()
                        == Some(request_id.as_str())
                        && response.get("kind").and_then(Value::as_str) == Some("session_picker")
                        && response.get("decision").and_then(Value::as_str) == Some("cancel")
                    {
                        self.session_picker_quit_after_response = None;
                        self.should_quit = true;
                    } else if response.get("kind").and_then(Value::as_str)
                        == Some("workspace_trust")
                        && response.get("decision").and_then(Value::as_str) == Some("reject")
                    {
                        // The response is now fully written, so the setup
                        // runtime can observe the rejection. Exit through the
                        // ordinary pre-handoff shutdown path instead of
                        // waiting for its intentional status-1 termination to
                        // be misclassified as a protocol/runtime crash.
                        self.status = self
                            .renderer_ui_language
                            .text(
                                "已拒绝工作区信任 · 正在安全退出",
                                "Workspace trust declined · exiting safely",
                            )
                            .to_string();
                        self.should_quit = true;
                    }
                } else if subtype == CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE {
                    self.projection.resolve_pending_control(request_id);
                } else if dialog_request_id(self.dialog.as_ref()) == Some(request_id.as_str()) {
                    self.finish_dialog();
                }
            }
            HostAction::Initialize => {
                match self.setup_lifecycle_phase {
                    SetupLifecyclePhase::Initializing => {}
                    SetupLifecyclePhase::Initialized => {
                        // The child can publish its correlated initialize
                        // response after reading the frame but before the
                        // renderer observes the writer ACK. Never regress the
                        // already-authoritative initialized state.
                    }
                    phase => self.fail_closed(format!(
                        "initialize delivery completed in an invalid setup lifecycle phase \
                         {phase:?}"
                    )),
                }
            }
            HostAction::Interrupt | HostAction::StopRuntime { .. } => {}
        }
    }

    fn observe_successful_goal_submission(&mut self, submitted: &str) {
        if self
            .active_goal
            .as_ref()
            .is_some_and(|goal| goal.completed_sequence.is_some())
        {
            self.active_goal = None;
        }

        let trimmed = submitted.trim();
        let (command, objective) = trimmed
            .split_once(char::is_whitespace)
            .map_or((trimmed, ""), |(command, objective)| {
                (command, objective.trim())
            });
        if command != "/goal" || objective.is_empty() || !self.runtime_catalog_contains("/goal") {
            return;
        }

        self.goal_submission_sequence = self.goal_submission_sequence.saturating_add(1);
        self.active_goal = Some(ActiveGoalState {
            text: objective.to_string(),
            started_sequence: self.goal_submission_sequence,
            phase: None,
            phase_detail: None,
            phase_history: Vec::new(),
            completed_sequence: None,
            verdict: None,
            summary: None,
        });
    }

    pub fn transport_failed_indeterminate(&mut self, error: impl ToString) {
        self.fail_closed_after_runtime_stopped(format!(
            "direct runtime transport failed and delivery may be indeterminate; do not retry this action automatically: {}",
            error.to_string()
        ));
    }

    pub(crate) fn transport_failed_before_delivery(&mut self, error: impl ToString) {
        self.fail_closed(format!(
            "direct runtime transport bookkeeping failed before delivery was admitted: {}",
            error.to_string()
        ));
    }

    fn restore_pending_composer_submission(&mut self) {
        let Some(submission) = self.pending_composer_submission.take() else {
            return;
        };
        self.reset_composer_history_navigation();
        self.composer.set_text(&submission.text);
        self.composer.set_cursor(submission.cursor);
        self.composer_state = TextAreaState::default();
        self.attachments = submission.attachments;
        self.clear_composer_image_preview();
        self.refresh_command_palette();
    }

    pub fn push_stderr(&mut self, bytes: &[u8], truncated: bool) {
        let mut text = sanitize_terminal_text(&String::from_utf8_lossy(bytes)).into_owned();
        if truncated {
            text.push_str(self.renderer_ui_language.text(" ⟪已截断⟫", " ⟪truncated⟫"));
        }
        if self.stderr_notices.len() == MAX_STDERR_NOTICES {
            self.stderr_notices.pop_front();
        }
        self.stderr_notices.push_back(text);
    }

    pub fn stderr_notices(&self) -> impl DoubleEndedIterator<Item = &str> {
        self.stderr_notices.iter().map(String::as_str)
    }

    fn push_renderer_notice(
        &mut self,
        placement: TuiRendererNoticePlacement,
        content: TuiRendererNoticeContent,
    ) {
        let id = self.next_renderer_notice_id;
        self.next_renderer_notice_id = self
            .next_renderer_notice_id
            .checked_add(1)
            .expect("renderer notice identity exhausted");
        self.renderer_notices.push(TuiRendererNotice {
            id,
            placement,
            content,
        });
    }

    #[cfg(test)]
    pub(crate) fn push_startup_notice(&mut self, notice: String) {
        self.push_renderer_notice(
            TuiRendererNoticePlacement::BootPrefix,
            TuiRendererNoticeContent::Fixed(notice),
        );
    }

    pub(crate) fn push_localized_startup_notice(&mut self, zh_cn: String, en_us: String) {
        self.push_renderer_notice(
            TuiRendererNoticePlacement::BootPrefix,
            TuiRendererNoticeContent::Localized { zh_cn, en_us },
        );
    }

    pub(crate) fn push_runtime_notice(&mut self, notice: String) {
        let after_sequence = self
            .projection
            .raw_envelopes()
            .last()
            .map(|envelope| envelope.sequence);
        self.push_renderer_notice(
            TuiRendererNoticePlacement::AfterRawSequence(after_sequence),
            TuiRendererNoticeContent::Fixed(notice),
        );
    }

    #[cfg(test)]
    pub(crate) fn startup_notices(&self) -> impl Iterator<Item = &str> {
        let language = self.renderer_ui_language;
        self.renderer_notices
            .iter()
            .filter(|notice| notice.placement() == TuiRendererNoticePlacement::BootPrefix)
            .map(move |notice| notice.text(language))
    }

    pub(crate) fn renderer_notices(&self) -> impl Iterator<Item = &TuiRendererNotice> {
        self.renderer_notices.iter()
    }

    pub(crate) fn oauth_browser_notice(&self) -> Option<OAuthBrowserNotice<'_>> {
        let prompt = self.oauth_browser_prompt.as_ref()?;
        if !prompt.revealed {
            return Some(OAuthBrowserNotice::Opening {
                spinner: prompt.spinner_frame(),
                message: &prompt.opening_message,
            });
        }
        Some(OAuthBrowserNotice::Manual {
            message: &prompt.manual_message,
            hint: if prompt.copied_until.is_some() {
                self.renderer_ui_language.text("（已复制）", "(Copied!)")
            } else {
                &prompt.copy_hint
            },
            copied: prompt.copied_until.is_some(),
            url: &prompt.url,
        })
    }

    #[cfg(test)]
    pub(crate) fn oauth_browser_notice_lines(&self) -> Vec<String> {
        match self.oauth_browser_notice() {
            None => Vec::new(),
            Some(OAuthBrowserNotice::Opening { spinner, message }) => {
                vec![format!("{spinner} {message}")]
            }
            Some(OAuthBrowserNotice::Manual {
                message, hint, url, ..
            }) => vec![format!("{message} {hint}"), url.to_string()],
        }
    }

    pub(crate) fn renderer_animation_deadline(&self) -> Option<Instant> {
        let oauth = self
            .oauth_browser_prompt
            .as_ref()
            .and_then(OAuthBrowserPrompt::next_deadline);
        [
            oauth,
            self.session_picker_exit_at,
            self.turn_status.animation_deadline(),
            self.turn_abort_pending.as_ref().map(|abort| abort.deadline),
        ]
        .into_iter()
        .flatten()
        .min()
    }

    pub(crate) fn tick_renderer_animation(&mut self, now: Instant) -> bool {
        let mut changed = self.turn_status.tick(now);
        if self
            .turn_abort_pending
            .as_ref()
            .is_some_and(|abort| now >= abort.deadline)
        {
            let abort = self
                .turn_abort_pending
                .take()
                .expect("the turn-abort deadline was just observed");
            self.interrupt_pending = false;
            self.fail_closed(format!(
                "turn abort interrupt acknowledgement timed out at sequence {} ({})",
                abort.sequence, abort.code
            ));
            changed = true;
        }
        if let Some(prompt) = self.oauth_browser_prompt.as_mut() {
            let (prompt_changed, newly_revealed) = prompt.tick_at(now);
            changed |= prompt_changed;
            if newly_revealed {
                self.oauth_browser_manual_reveal_requested = true;
                self.status = prompt.manual_message.clone();
            }
        }
        if self
            .session_picker_exit_at
            .is_some_and(|deadline| now >= deadline)
        {
            self.session_picker_exit_at = None;
            self.should_quit = true;
            changed = true;
        }
        changed
    }

    pub(crate) const fn session_picker_active(&self) -> bool {
        self.session_picker.is_some()
    }

    pub(crate) fn render_session_picker(&mut self, frame: &mut ratatui::Frame<'_>) {
        let action = self
            .session_picker
            .as_mut()
            .map(|picker| picker.prepare_frame(frame.area().height))
            .unwrap_or(SessionPickerAction::None);
        if action != SessionPickerAction::None {
            self.pending_session_picker_actions.push_back(action);
        }
        if let Some(picker) = self.session_picker.as_mut() {
            picker.render(
                frame,
                &self.renderer_theme,
                self.renderer_theme_kind,
                self.renderer_syntax_highlighting_disabled.unwrap_or(false),
                self.renderer_ui_language,
            );
        }
    }

    #[cfg(test)]
    pub(crate) fn take_startup_notices(&mut self) -> Vec<TuiRendererNotice> {
        std::mem::take(&mut self.renderer_notices)
    }

    #[cfg(test)]
    pub(crate) fn restore_startup_notices(&mut self, notices: Vec<TuiRendererNotice>) {
        let next_id = notices
            .iter()
            .map(TuiRendererNotice::id)
            .max()
            .and_then(|id| id.checked_add(1))
            .unwrap_or(0);
        self.next_renderer_notice_id = self.next_renderer_notice_id.max(next_id);
        self.renderer_notices = notices;
    }

    pub fn dialog_response_inflight(&self) -> bool {
        self.dialog_response_inflight
    }

    pub fn take_runtime_stop_action(&mut self) -> Option<HostAction> {
        self.runtime_stop_reason
            .take()
            .map(|reason| HostAction::StopRuntime { reason })
    }

    pub fn busy(&self) -> bool {
        self.turn_status.is_running()
            || self.stream_requesting
            || matches!(
                self.projection.session_state(),
                Some("running" | "requires_action")
            )
    }

    pub(crate) fn stream_requesting(&self) -> bool {
        self.stream_requesting
    }

    pub(crate) fn turn_status(&self) -> &TurnStatus {
        &self.turn_status
    }

    pub fn composer_enabled(&self) -> bool {
        self.fatal.is_none()
            && !self.startup_barrier_pending
            && self.session_picker.is_none()
            && self.dialog.is_none()
            && self.history_search.is_none()
            && self.workspace_search.is_none()
            && self.model_picker.is_none()
            && self.usage_plugin_management.is_none()
            && self.mcp_settings.is_none()
            && self.pending_composer_submission.is_none()
    }

    pub fn set_slash_commands_enabled(&mut self, enabled: bool) {
        if self.slash_commands_enabled == enabled {
            return;
        }
        self.slash_commands_enabled = enabled;
        self.rebuild_completion_commands();
    }

    /// Return a discoverable command from the same renderer/runtime catalog
    /// that drives completion and Help. Welcome surfaces use this instead of
    /// advertising names that merely happen to exist in design copy.
    pub(crate) fn welcome_command(&self, name: &str) -> Option<&SlashCommandChoice> {
        self.slash_commands_enabled.then_some(())?;
        let name = name.strip_prefix('/').unwrap_or(name);
        self.completion_commands
            .iter()
            .find(|command| !command.hidden && command.name == name)
    }

    pub(crate) fn workspace_cwd(&self) -> Option<&std::path::Path> {
        self.projection
            .cwd()
            .map(std::path::Path::new)
            .or(self.setup_source_cwd.as_deref())
    }

    fn rebuild_completion_commands(&mut self) {
        if !self.slash_commands_enabled {
            self.completion_commands.clear();
            self.command_palette = CommandPaletteState::default();
            return;
        }
        let ui_language = self.renderer_ui_language;
        let mut commands = self
            .commands
            .iter()
            .filter(|command| !command.hidden && !reserved_private_local_command(&command.name))
            .cloned()
            .collect::<Vec<_>>();
        commands.extend(
            FIXED_LOCAL_COMMAND_COMPLETIONS
                .iter()
                .filter(|(name, _, _)| {
                    reserved_private_local_command(name)
                        || !self.commands.iter().any(|command| command.name == *name)
                })
                .map(|(name, description, argument_hint)| SlashCommandChoice {
                    name: (*name).to_string(),
                    description: fixed_local_command_description(ui_language, name, description)
                        .to_string(),
                    argument_hint: (*argument_hint).to_string(),
                    hidden: false,
                    builtin: true,
                }),
        );
        self.completion_commands = commands;
    }

    pub fn visible_command_suggestions(&self) -> impl Iterator<Item = (bool, &SlashCommandChoice)> {
        self.command_palette
            .matches
            .iter()
            .enumerate()
            .filter_map(|(row, index)| {
                self.completion_commands
                    .get(*index)
                    .map(|command| (row == self.command_palette.lifecycle.selected, command))
            })
    }

    pub(crate) fn command_palette_picker_mut(&mut self) -> &mut PickerState {
        &mut self.command_palette.lifecycle
    }

    fn renderer_watchers(&self) -> Watchers {
        let mut watchers = Watchers::default();
        let mut seen = HashSet::new();

        for (task_id, task_type) in self.projection.active_direct_tasks() {
            seen.insert(task_id.clone());
            count_direct_watcher(&mut watchers, *task_type);
        }
        for task_id in self.active_tasks.keys() {
            if !seen.insert(task_id.clone()) {
                continue;
            }
            count_sdk_watcher(
                &mut watchers,
                self.goal_tasks
                    .get(task_id)
                    .and_then(|task| task.task_type.as_deref()),
            );
        }
        if self.processing_background_task && watchers.total() == 0 {
            watchers.commands = 1;
        }
        watchers
    }

    fn synchronize_renderer_watchers(&mut self, now: Instant) {
        let watchers = self.renderer_watchers();
        self.turn_status.set_watchers(watchers, now);
    }

    fn observe_client_runtime_state(&mut self, envelope: &crate::sdk_runtime::RawEnvelope) {
        if matches!(
            &envelope.classification,
            crate::sdk_runtime::EnvelopeClass::System(crate::sdk_runtime::SystemSubtype::Status)
        ) {
            self.processing_background_task = envelope.value.get("status").and_then(Value::as_str)
                == Some("processing_background_task");
            return;
        }

        let subtype = match &envelope.classification {
            crate::sdk_runtime::EnvelopeClass::System(
                crate::sdk_runtime::SystemSubtype::TaskStarted,
            ) => "task_started",
            crate::sdk_runtime::EnvelopeClass::System(
                crate::sdk_runtime::SystemSubtype::TaskProgress,
            ) => "task_progress",
            crate::sdk_runtime::EnvelopeClass::System(
                crate::sdk_runtime::SystemSubtype::TaskNotification,
            ) => "task_notification",
            _ => return,
        };
        let Some(task_id) = envelope.value.get("task_id").and_then(Value::as_str) else {
            return;
        };
        match subtype {
            "task_started" => {
                let Some(summary) = envelope.value.get("description").and_then(Value::as_str)
                else {
                    return;
                };
                self.active_tasks
                    .insert(task_id.to_string(), summary.to_string());
                self.goal_tasks.insert(
                    task_id.to_string(),
                    GoalTaskObservation {
                        id: task_id.to_string(),
                        description: summary.to_string(),
                        task_type: envelope
                            .value
                            .get("task_type")
                            .and_then(Value::as_str)
                            .map(str::to_string),
                        tool_use_id: envelope
                            .value
                            .get("tool_use_id")
                            .and_then(Value::as_str)
                            .map(str::to_string),
                        state: GoalTaskState::Executing,
                        started_sequence: envelope.sequence,
                        terminal_sequence: None,
                    },
                );
            }
            "task_progress" => {
                let Some(summary) = envelope.value.get("description").and_then(Value::as_str)
                else {
                    return;
                };
                self.active_tasks
                    .insert(task_id.to_string(), summary.to_string());
                if let Some(task) = self.goal_tasks.get_mut(task_id) {
                    task.description = summary.to_string();
                    if task.tool_use_id.is_none() {
                        task.tool_use_id = envelope
                            .value
                            .get("tool_use_id")
                            .and_then(Value::as_str)
                            .map(str::to_string);
                    }
                }
            }
            "task_notification" => {
                self.active_tasks.remove(task_id);
                if let Some(task) = self.goal_tasks.get_mut(task_id) {
                    task.description = envelope
                        .value
                        .get("summary")
                        .and_then(Value::as_str)
                        .filter(|summary| !summary.is_empty())
                        .unwrap_or(&task.description)
                        .to_string();
                    task.state = match envelope.value.get("status").and_then(Value::as_str) {
                        Some("completed") => GoalTaskState::Completed,
                        Some("failed") => GoalTaskState::Failed,
                        Some("stopped") => GoalTaskState::Stopped,
                        _ => return,
                    };
                    task.terminal_sequence = Some(envelope.sequence);
                    if task.tool_use_id.is_none() {
                        task.tool_use_id = envelope
                            .value
                            .get("tool_use_id")
                            .and_then(Value::as_str)
                            .map(str::to_string);
                    }
                }
            }
            _ => {}
        }
    }

    /// Observe the fixed direct-query event pair produced by one local
    /// `/extra-usage` invocation.
    ///
    /// QueryEngine publishes `messagesFromUserInput` synchronously and in
    /// source order at its process-local observer boundary: the exact direct
    /// user object is immediately followed by its local-command result. This
    /// renderer state therefore uses event provenance and ordering, not an
    /// inferred SDK shape or a new correlation field.
    fn observe_extra_usage_runtime_pair(
        &mut self,
        envelope: &crate::sdk_runtime::RawEnvelope,
    ) -> bool {
        match &envelope.classification {
            crate::sdk_runtime::EnvelopeClass::User => {
                let Some(text) = envelope
                    .value
                    .pointer("/message/content")
                    .and_then(Value::as_str)
                else {
                    return false;
                };
                let command_name = text
                    .trim()
                    .split_once(char::is_whitespace)
                    .map_or(text.trim(), |(name, _)| name);
                if command_name == "/extra-usage" && self.runtime_catalog_contains("/extra-usage") {
                    self.pending_extra_usage_output = true;
                }
                false
            }
            crate::sdk_runtime::EnvelopeClass::DirectSystem(
                crate::sdk_runtime::DirectSystemSubtype::LocalCommand,
            ) if self.pending_extra_usage_output => {
                self.pending_extra_usage_output = false;
                envelope
                    .value
                    .get("content")
                    .and_then(Value::as_str)
                    .is_some_and(is_extra_usage_browser_opened_output)
            }
            _ => false,
        }
    }

    fn synchronize_goal_report_projection(&mut self) {
        let completed_results = self
            .projection
            .items()
            .iter()
            .filter(|item| item.kind == ProjectedKind::ToolResult && !item.streaming)
            .filter_map(|result| {
                let tool_use_id = result.tool_use_id.as_deref()?;
                if self.processed_goal_report_results.contains(tool_use_id) {
                    return None;
                }
                let presentation = result.presentation.tool.as_ref()?;
                if presentation.is_error == Some(true) || presentation.result.is_none() {
                    return None;
                }
                let use_item = self.projection.items().iter().find(|candidate| {
                    candidate.kind == ProjectedKind::ToolUse
                        && candidate.tool_use_id.as_deref() == Some(tool_use_id)
                        && candidate
                            .presentation
                            .tool
                            .as_ref()
                            .and_then(|tool| tool.name.as_deref())
                            == Some(GOAL_REPORT_TOOL_NAME)
                })?;
                let input = use_item
                    .presentation
                    .tool
                    .as_ref()
                    .and_then(|tool| tool.input.as_ref())
                    .and_then(parse_goal_report_input);
                let sequence = result.raw_sequences.last().copied().unwrap_or_default();
                Some((tool_use_id.to_string(), sequence, input))
            })
            .collect::<Vec<_>>();

        for (tool_use_id, sequence, input) in completed_results {
            self.processed_goal_report_results.insert(tool_use_id);
            if let Some(input) = input {
                self.apply_goal_report(input, sequence);
            }
        }
    }

    fn apply_goal_report(&mut self, report: GoalReportInput, reported_sequence: u64) {
        let Some(goal) = self.active_goal.as_mut() else {
            return;
        };
        if goal.completed_sequence.is_some() {
            return;
        }

        if let Some(verdict) = report.verdict {
            goal.completed_sequence = Some(reported_sequence);
            goal.verdict = Some(verdict);
            goal.summary = Some(report.summary);
            return;
        }

        if goal.phase.as_deref() == report.phase.as_deref()
            && goal.phase_detail.as_deref() == Some(report.summary.as_str())
        {
            return;
        }
        goal.phase = report.phase.clone();
        goal.phase_detail = Some(report.summary.clone());

        let Some(phase) = report.phase else {
            return;
        };
        let normalized = normalize_goal_phase(&phase);
        if let Some(existing) = goal
            .phase_history
            .iter_mut()
            .find(|entry| normalize_goal_phase(&entry.phase) == normalized)
        {
            if existing.detail.as_deref() != Some(report.summary.as_str()) {
                existing.phase = phase;
                existing.detail = Some(report.summary);
            }
            return;
        }
        goal.phase_history.push(GoalPhaseHistoryEntry {
            phase,
            detail: Some(report.summary),
            reported_sequence,
        });
    }

    fn remember_composer_submission(&mut self, text: &str) {
        if text.is_empty()
            || self
                .composer_history
                .entries
                .back()
                .is_some_and(|previous| previous == text)
        {
            return;
        }
        if text.len() > MAX_COMPOSER_HISTORY_BYTES {
            return;
        }
        while self.composer_history.entries.len() >= MAX_COMPOSER_HISTORY_ENTRIES
            || self
                .composer_history
                .retained_bytes
                .saturating_add(text.len())
                > MAX_COMPOSER_HISTORY_BYTES
        {
            let Some(removed) = self.composer_history.entries.pop_front() else {
                break;
            };
            let _ = self.composer_history.timestamps.pop_front();
            self.composer_history.retained_bytes = self
                .composer_history
                .retained_bytes
                .saturating_sub(removed.len());
        }
        self.composer_history.retained_bytes = self
            .composer_history
            .retained_bytes
            .saturating_add(text.len());
        self.composer_history.entries.push_back(text.to_string());
        self.composer_history
            .timestamps
            .push_back(SystemTime::now());
    }

    fn reset_composer_history_navigation(&mut self) {
        self.composer_history.selected = None;
        self.composer_history.draft = None;
    }

    fn composer_cursor_on_first_line(&self) -> bool {
        self.composer
            .text()
            .get(..self.composer.cursor())
            .is_some_and(|prefix| !prefix.contains('\n'))
    }

    fn composer_history_previous(&mut self) {
        if self.composer_history.entries.is_empty() {
            self.status = self
                .renderer_ui_language
                .text(
                    "当前 TUI 进程中没有输入历史",
                    "No in-memory composer history in this TUI process",
                )
                .to_string();
            return;
        }
        let next = match self.composer_history.selected {
            Some(0) => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "已经是最早的输入历史",
                        "Already at the oldest in-memory composer entry",
                    )
                    .to_string();
                return;
            }
            Some(index) => index - 1,
            None => {
                self.composer_history.draft = Some(PendingComposerSubmission {
                    text: self.composer.text().to_string(),
                    cursor: self.composer.cursor(),
                    attachments: self.attachments.clone(),
                });
                self.composer_history.entries.len() - 1
            }
        };
        self.composer_history.selected = Some(next);
        let text = self.composer_history.entries[next].clone();
        self.composer.set_text(&text);
        self.composer.set_cursor(0);
        self.composer_state = TextAreaState::default();
        self.attachments.clear();
        self.clear_composer_image_preview();
        self.refresh_command_palette();
        self.status = match self.renderer_ui_language {
            UiLanguage::ZhCn => format!(
                "输入历史 {}/{} · 按 Down 返回已保存的草稿",
                next + 1,
                self.composer_history.entries.len()
            ),
            UiLanguage::EnUs => format!(
                "Composer history {}/{} · Down returns toward the saved draft",
                next + 1,
                self.composer_history.entries.len()
            ),
        };
    }

    fn composer_history_next(&mut self) {
        let Some(current) = self.composer_history.selected else {
            return;
        };
        if current + 1 < self.composer_history.entries.len() {
            let next = current + 1;
            self.composer_history.selected = Some(next);
            let text = self.composer_history.entries[next].clone();
            self.composer.set_text(&text);
            self.composer.set_cursor(text.len());
            self.composer_state = TextAreaState::default();
            self.attachments.clear();
            self.clear_composer_image_preview();
            self.refresh_command_palette();
            self.status = match self.renderer_ui_language {
                UiLanguage::ZhCn => format!(
                    "输入历史 {}/{} · 按 Down 返回已保存的草稿",
                    next + 1,
                    self.composer_history.entries.len()
                ),
                UiLanguage::EnUs => format!(
                    "Composer history {}/{} · Down returns toward the saved draft",
                    next + 1,
                    self.composer_history.entries.len()
                ),
            };
            return;
        }
        let draft = self.composer_history.draft.take();
        self.composer_history.selected = None;
        if let Some(draft) = draft {
            self.composer.set_text(&draft.text);
            self.composer.set_cursor(draft.cursor);
            self.composer_state = TextAreaState::default();
            self.attachments = draft.attachments;
            self.clear_composer_image_preview();
        }
        self.refresh_command_palette();
        self.status = self
            .renderer_ui_language
            .text(
                "已恢复浏览历史前的原始草稿",
                "Restored the exact draft from before history navigation",
            )
            .to_string();
    }

    fn refresh_command_palette(&mut self) {
        self.command_palette.matches.clear();
        self.command_palette.lifecycle = PickerState::default();
        let Some(query) = command_palette_query(self.composer.text()) else {
            return;
        };
        self.command_palette.lifecycle.set_query(query);
        let query = query.to_ascii_lowercase();
        let mut matches = self
            .completion_commands
            .iter()
            .enumerate()
            .filter(|(_, command)| {
                command.name.to_ascii_lowercase().starts_with(&query)
                    || command.description.to_ascii_lowercase().contains(&query)
            })
            .map(|(index, _)| index)
            .collect::<Vec<_>>();
        // Fixed historical CrabCode suggestion ordering puts an exact command
        // name before prefix-name matches, and among prefixes prefers the
        // shorter name. Preserve registry order for equal classes so the
        // first-wins backend ownership projection remains deterministic.
        matches.sort_by_key(|index| {
            let command = &self.completion_commands[*index];
            let name = command.name.to_ascii_lowercase();
            if name == query {
                (0, 0)
            } else if name.starts_with(&query) {
                (1, name.len())
            } else {
                (2, 0)
            }
        });
        matches.truncate(MAX_COMMAND_SUGGESTIONS);
        self.command_palette.matches = matches;
        self.describe_selected_command();
    }

    fn describe_selected_command(&mut self) {
        let Some(index) = self
            .command_palette
            .matches
            .get(self.command_palette.lifecycle.selected)
            .copied()
        else {
            return;
        };
        let command = &self.completion_commands[index];
        let hint = if command.argument_hint.is_empty() {
            String::new()
        } else {
            format!(" {}", command.argument_hint)
        };
        let runtime_owned = self.runtime_catalog_contains(&command.name)
            && !reserved_private_local_command(&command.name);
        let renderer_owned = fixed_local_completion_contains(&command.name) && !runtime_owned;
        let exact_runtime_invocation =
            runtime_owned && self.composer.text() == format!("/{}", command.name);
        let waits_for_private_report_description =
            reserved_private_local_command(&command.name) && !command.argument_hint.is_empty();
        let enter_action = match (
            self.renderer_ui_language,
            (renderer_owned || exact_runtime_invocation) && !waits_for_private_report_description,
        ) {
            (UiLanguage::ZhCn, true) => "Enter 执行",
            (UiLanguage::EnUs, true) => "Enter run",
            (UiLanguage::ZhCn, false) => "Enter 接受",
            (UiLanguage::EnUs, false) => "Enter accept",
        };
        self.status = match self.renderer_ui_language {
            UiLanguage::ZhCn => format!(
                "/{}{} — {} · Up/Down 选择 · {enter_action} · Tab 补全",
                command.name, hint, command.description,
            ),
            UiLanguage::EnUs => format!(
                "/{}{} — {} · Up/Down choose · {enter_action} · Tab complete",
                command.name, hint, command.description,
            ),
        };
    }

    fn select_command_suggestion(&mut self, forward: bool) {
        let len = self.command_palette.matches.len();
        if len == 0 {
            return;
        }
        let code = if forward { KeyCode::Down } else { KeyCode::Up };
        let _ = handle_picker_input(
            &Event::Key(KeyEvent::new(code, KeyModifiers::NONE)),
            &mut self.command_palette.lifecycle,
            len,
            &PickerConfig {
                disable_search: true,
                ..picker_config_default()
            },
        );
        self.describe_selected_command();
    }

    fn complete_selected_command(&mut self) {
        let _ = self.accept_selected_command(false);
    }

    /// Accept the highlighted slash command before the ordinary chat Enter
    /// path can submit a partial token. Fixed renderer-owned commands retain
    /// their historical one-Enter execution. A runtime-advertised command also
    /// executes on the first Enter when the composer already contains its exact
    /// canonical token: that text is explicit user intent, while argument
    /// validity remains owned by the existing backend command handler. Partial
    /// tokens and Tab completion still only accept the selected name.
    fn accept_selected_command(&mut self, execute_on_enter: bool) -> Vec<HostAction> {
        let Some(index) = self
            .command_palette
            .matches
            .get(self.command_palette.lifecycle.selected)
            .copied()
        else {
            return Vec::new();
        };
        let command = self.completion_commands[index].clone();
        let runtime_owned = self.runtime_catalog_contains(&command.name)
            && !reserved_private_local_command(&command.name);
        let renderer_owned = fixed_local_completion_contains(&command.name) && !runtime_owned;
        let exact_runtime_invocation =
            runtime_owned && self.composer.text() == format!("/{}", command.name);
        if execute_on_enter && exact_runtime_invocation {
            // Do not rewrite the explicit token or infer arguments. Reuse the
            // ordinary transactional submission path so attachments, writer
            // failure recovery, runtime first-wins dispatch, and backend
            // validation retain their existing authorities.
            return self.submit_composer_with_priority(None);
        }
        let completed = format!("/{} ", command.name);
        self.reset_composer_history_navigation();
        self.composer.set_text(&completed);
        self.composer.set_cursor(completed.len());
        self.composer_state = TextAreaState::default();
        self.refresh_command_palette();
        // `/bug` and `/feedback` require a description. The first Enter in
        // the command palette accepts that reserved local completion only;
        // executing the now-bare command here would immediately clear the
        // composer and leave its usage hint visible for just one frame.
        let waits_for_private_report_description =
            reserved_private_local_command(&command.name) && !command.argument_hint.is_empty();
        if execute_on_enter && renderer_owned && !waits_for_private_report_description {
            return self.submit_composer_with_priority(None);
        }
        if execute_on_enter && waits_for_private_report_description {
            self.status = match self.renderer_ui_language {
                UiLanguage::ZhCn => {
                    format!("已接受 /{} · 请输入描述后按 Enter 提交", command.name)
                }
                UiLanguage::EnUs => format!(
                    "Accepted /{} · enter a description, then press Enter to submit",
                    command.name
                ),
            };
            return Vec::new();
        }
        let expected = if command.argument_hint.is_empty() {
            String::new()
        } else {
            match self.renderer_ui_language {
                UiLanguage::ZhCn => format!(" · 参数格式 {}", command.argument_hint),
                UiLanguage::EnUs => format!(" · expected {}", command.argument_hint),
            }
        };
        self.status = match (self.renderer_ui_language, execute_on_enter) {
            (UiLanguage::ZhCn, true) => {
                format!(
                    "已接受 /{}{expected} · 输入参数或再次按 Enter 发送",
                    command.name
                )
            }
            (UiLanguage::EnUs, true) => format!(
                "Accepted /{}{expected} · enter arguments or press Enter again to send",
                command.name
            ),
            (UiLanguage::ZhCn, false) => format!("已补全 /{}{expected}", command.name),
            (UiLanguage::EnUs, false) => format!("Completed /{}{expected}", command.name),
        };
        Vec::new()
    }

    pub fn handle_event(&mut self, event: Event) -> Vec<HostAction> {
        self.handle_event_at(event, Instant::now()).actions
    }

    pub(crate) fn synchronize_modal_tree(&mut self) {
        self.modal_tree.synchronize(
            self.history_search.is_some(),
            self.workspace_search.is_some(),
            self.model_picker.is_some(),
            self.model_management.is_some(),
            self.usage_plugin_management.is_some(),
            self.mcp_settings.is_some(),
            self.overlay
                .as_ref()
                .is_some_and(|overlay| overlay.lifecycle.visible),
            self.dialog.is_some(),
            self.fatal.is_some(),
        );
    }

    pub(crate) fn active_modal(&self) -> Option<ActiveModal> {
        self.modal_tree.active()
    }

    /// Route one terminal event using the timestamp captured by the sole
    /// terminal reader. Backend scheduling and frame backpressure must not
    /// collapse the physical spacing between scroll reports.
    pub(crate) fn handle_event_at(
        &mut self,
        event: Event,
        arrived_at: Instant,
    ) -> TerminalEventOutcome {
        self.handle_event_at_with_paste_provenance(event, arrived_at, PasteProvenance::Terminal)
    }

    pub(crate) fn handle_event_at_with_paste_provenance(
        &mut self,
        event: Event,
        arrived_at: Instant,
        paste_provenance: PasteProvenance,
    ) -> TerminalEventOutcome {
        debug_assert!(
            matches!(event, Event::Paste(_)) || paste_provenance == PasteProvenance::Terminal,
            "non-paste events cannot carry paste provenance"
        );
        if self.session_picker.is_some() && self.dialog.is_none() && self.fatal.is_none() {
            let (action, update) = self
                .session_picker
                .as_mut()
                .expect("checked session picker")
                .handle_event(&event);
            return TerminalEventOutcome {
                actions: self.session_picker_host_actions(action),
                needs_frame: update.needs_frame,
            };
        }
        self.synchronize_modal_tree();
        self.synchronize_mouse_scroll_target();
        if self.active_modal().is_none()
            && let Event::Key(key) = &event
        {
            self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::UpdateLinkHover {
                    modifier_held: link_modifier_for_key(key),
                },
            );
        }
        if let Event::Mouse(mouse) = &event
            && matches!(mouse.kind, MouseEventKind::Moved)
        {
            self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::PointerMoved {
                    pointer: Some((mouse.column, mouse.row)),
                    arrived_at,
                },
            );
        } else if matches!(event, Event::FocusLost) {
            self.retire_focus_scoped_pointer_state();
            self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::PointerMoved {
                    pointer: None,
                    arrived_at,
                },
            );
            self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::CancelPointerGesture,
            );
        }
        if let Event::Mouse(mouse) = &event
            && let Some(direction) = ScrollDirection::from_mouse_event(mouse)
        {
            self.last_mouse_position = Some((mouse.column, mouse.row));
            let Some(target) = self.mouse_scroll_target() else {
                return TerminalEventOutcome {
                    actions: Vec::new(),
                    needs_frame: false,
                };
            };
            let Some(viewport_height) = self.mouse_scroll_viewport_height(target) else {
                return TerminalEventOutcome {
                    actions: Vec::new(),
                    needs_frame: false,
                };
            };
            let lines = self
                .mouse_scroll
                .on_scroll_event_at(
                    arrived_at,
                    direction,
                    self.scroll_config.with_viewport_height(viewport_height),
                )
                .lines;
            return TerminalEventOutcome {
                actions: Vec::new(),
                needs_frame: self.apply_mouse_scroll_lines(target, lines),
            };
        }

        let actions = match event {
            Event::Key(key) if key.kind != KeyEventKind::Release => {
                self.handle_key(normalize_key_event(key), arrived_at)
            }
            Event::Paste(text) => match self.active_modal() {
                Some(ActiveModal::HistorySearch) => {
                    self.handle_history_search_event(Event::Paste(text))
                }
                Some(ActiveModal::WorkspaceSearch) => {
                    self.handle_workspace_search_event(Event::Paste(text), arrived_at)
                }
                Some(ActiveModal::ModelPicker) => {
                    self.handle_model_picker_event(Event::Paste(text))
                }
                Some(ActiveModal::ModelManagement) => {
                    if let Some(management) = self.model_management.as_mut() {
                        management.paste(&text);
                    }
                    Vec::new()
                }
                Some(ActiveModal::UsagePluginManagement) => {
                    if let Some(management) = self.usage_plugin_management.as_mut() {
                        management.paste(&text);
                    }
                    Vec::new()
                }
                Some(ActiveModal::McpSettings) => Vec::new(),
                Some(ActiveModal::Request)
                    if self.dialog.as_ref().is_some_and(|dialog| {
                        matches!(dialog, RequestDialog::SetupInput(_))
                            || matches!(
                                dialog,
                                RequestDialog::Question(QuestionDialog {
                                    focus: QuestionFocus::OtherInput,
                                    ..
                                })
                            )
                            || matches!(
                                dialog,
                                RequestDialog::Elicitation { mode, .. } if mode != "url"
                            )
                    }) =>
                {
                    self.handle_paste(text)
                }
                Some(ActiveModal::Overlay | ActiveModal::Request | ActiveModal::Fatal) => {
                    Vec::new()
                }
                None => {
                    if self.handle_transcript_search_paste(&text) {
                        Vec::new()
                    } else {
                        self.handle_bracketed_paste(text, paste_provenance)
                    }
                }
            },
            Event::Mouse(mouse) => {
                self.last_mouse_position = Some((mouse.column, mouse.row));
                if self.mouse_clicks_disabled
                    && matches!(
                        mouse.kind,
                        MouseEventKind::Down(_) | MouseEventKind::Up(_) | MouseEventKind::Drag(_)
                    )
                {
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::CancelPointerGesture,
                    );
                    return TerminalEventOutcome {
                        actions: Vec::new(),
                        needs_frame: true,
                    };
                }
                if matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left)) {
                    // A fresh press retires any incomplete prior gesture. A
                    // Drag belongs to the current text-selection gesture and
                    // clears only its pending link inside AgentView.
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::CancelPointerGesture,
                    );
                }
                // The modal tree resolves one surface before any content
                // interaction, so a hidden surface can never receive input
                // through the surface painted above it.
                let active_modal = self.active_modal();
                if active_modal.is_some()
                    && matches!(
                        mouse.kind,
                        MouseEventKind::Up(MouseButton::Left)
                            | MouseEventKind::Drag(MouseButton::Left)
                    )
                {
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::CancelPointerGesture,
                    );
                }
                match active_modal {
                    Some(ActiveModal::HistorySearch) => {
                        return TerminalEventOutcome {
                            actions: self.handle_history_search_event(Event::Mouse(mouse)),
                            needs_frame: true,
                        };
                    }
                    Some(ActiveModal::WorkspaceSearch) => {
                        return TerminalEventOutcome {
                            actions: self
                                .handle_workspace_search_event(Event::Mouse(mouse), arrived_at),
                            needs_frame: true,
                        };
                    }
                    Some(ActiveModal::ModelPicker) => {
                        return TerminalEventOutcome {
                            actions: self.handle_model_picker_event(Event::Mouse(mouse)),
                            needs_frame: true,
                        };
                    }
                    Some(ActiveModal::ModelManagement) => {
                        return TerminalEventOutcome {
                            actions: Vec::new(),
                            needs_frame: false,
                        };
                    }
                    Some(ActiveModal::UsagePluginManagement) => {
                        return TerminalEventOutcome {
                            actions: Vec::new(),
                            needs_frame: false,
                        };
                    }
                    Some(ActiveModal::McpSettings) => {
                        return TerminalEventOutcome {
                            actions: self.handle_mcp_settings_event(Event::Mouse(mouse)),
                            needs_frame: true,
                        };
                    }
                    Some(ActiveModal::Overlay) => {
                        let outcome = self
                            .overlay
                            .as_mut()
                            .map(|overlay| {
                                handle_modal_mouse(
                                    &mut overlay.window,
                                    mouse.kind,
                                    mouse.column,
                                    mouse.row,
                                )
                            })
                            .unwrap_or(ModalWindowOutcome::Unhandled);
                        if outcome == ModalWindowOutcome::CloseRequested {
                            if let Some(overlay) = self.overlay.as_mut() {
                                let _ = overlay.lifecycle.hide();
                            }
                            self.overlay = None;
                        } else if matches!(outcome, ModalWindowOutcome::TabChanged(_))
                            && let Some(overlay) = self.overlay.as_mut()
                        {
                            overlay.scroll = 0;
                        }
                        return TerminalEventOutcome {
                            actions: Vec::new(),
                            needs_frame: !matches!(outcome, ModalWindowOutcome::Unhandled),
                        };
                    }
                    Some(ActiveModal::Request)
                        if matches!(self.dialog, Some(RequestDialog::Setup(_))) =>
                    {
                        return TerminalEventOutcome {
                            actions: self.handle_setup_dialog_mouse(mouse),
                            needs_frame: true,
                        };
                    }
                    Some(ActiveModal::Request) => {
                        let (actions, changed) =
                            self.handle_request_dialog_mouse(mouse, arrived_at);
                        return TerminalEventOutcome {
                            actions,
                            needs_frame: changed,
                        };
                    }
                    Some(ActiveModal::Fatal) => {
                        return TerminalEventOutcome {
                            actions: Vec::new(),
                            needs_frame: false,
                        };
                    }
                    None => {}
                }
                if matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left))
                    && self
                        .renderer_side_question
                        .close_rect
                        .contains((mouse.column, mouse.row).into())
                {
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::DismissSideQuestion,
                    );
                    self.status = self
                        .renderer_ui_language
                        .text("已关闭旁路提问", "Dismissed side question")
                        .to_string();
                    return TerminalEventOutcome {
                        actions: Vec::new(),
                        needs_frame: true,
                    };
                }
                if matches!(mouse.kind, MouseEventKind::Moved) {
                    let hovered = self
                        .renderer_side_question
                        .close_rect
                        .contains((mouse.column, mouse.row).into());
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::SideQuestionCloseHover { hovered },
                    );
                }
                match mouse.kind {
                    MouseEventKind::Moved => {
                        self.enqueue_transcript_view_action(
                            crate::agent_view::TranscriptViewAction::UpdateLinkHover {
                                modifier_held: link_modifier_held(mouse.modifiers),
                            },
                        );
                    }
                    MouseEventKind::Up(MouseButton::Left) => {
                        self.enqueue_transcript_view_action(
                            crate::agent_view::TranscriptViewAction::PointerUp((
                                mouse.column,
                                mouse.row,
                            )),
                        );
                    }
                    MouseEventKind::Drag(MouseButton::Left) => {
                        self.enqueue_transcript_view_action(
                            crate::agent_view::TranscriptViewAction::PointerDrag {
                                point: (mouse.column, mouse.row),
                            },
                        );
                    }
                    _ => {}
                }
                if self.dialog.is_none()
                    && self.model_picker.is_none()
                    && self.mcp_settings.is_none()
                    && self.overlay.is_none()
                    && self.fatal.is_none()
                    && matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left))
                    && let Some((action, source)) = self
                        .mermaid_hitboxes
                        .iter()
                        .find(|(area, _, _)| area.contains((mouse.column, mouse.row).into()))
                        .map(|(_, action, source)| (*action, Arc::clone(source)))
                {
                    self.interaction_context = InteractionContext::Scrollback;
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: true },
                    );
                    self.handle_mermaid_affordance(action, source);
                    return TerminalEventOutcome {
                        actions: Vec::new(),
                        needs_frame: true,
                    };
                }
                let attachment_hit = self
                    .composer_attachment_hitboxes
                    .iter()
                    .find(|(area, _)| area.contains((mouse.column, mouse.row).into()))
                    .map(|(_, index)| *index)
                    .filter(|index| *index < self.attachments.len());
                if self.dialog.is_none()
                    && self.model_picker.is_none()
                    && self.mcp_settings.is_none()
                    && self.overlay.is_none()
                    && self.fatal.is_none()
                    && matches!(
                        mouse.kind,
                        MouseEventKind::Moved | MouseEventKind::Down(MouseButton::Left)
                    )
                {
                    if matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left)) {
                        self.composer_image_preview = attachment_hit;
                        self.composer_attachment_navigation_active = attachment_hit.is_some();
                    } else if !self.composer_attachment_navigation_active {
                        self.composer_image_preview = attachment_hit;
                    }
                    if attachment_hit.is_some() {
                        if matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left)) {
                            self.interaction_context = InteractionContext::Prompt;
                        }
                        return TerminalEventOutcome {
                            actions: Vec::new(),
                            needs_frame: true,
                        };
                    }
                }
                if self.composer_enabled()
                    && self
                        .composer_area
                        .contains((mouse.column, mouse.row).into())
                {
                    if matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left)) {
                        self.interaction_context = InteractionContext::Prompt;
                        self.enqueue_transcript_view_action(
                            crate::agent_view::TranscriptViewAction::FocusChanged {
                                scrollback: false,
                            },
                        );
                    }
                    let action =
                        self.composer
                            .handle_mouse(mouse, self.composer_area, self.composer_state);
                    if action == crabcode_ratatui_textarea::MouseAction::SelectionFinished {
                        self.deliver_composer_clipboard();
                    }
                } else if matches!(mouse.kind, MouseEventKind::Down(MouseButton::Left))
                    && self
                        .action_registry
                        .definition(TuiActionId::FocusScrollback)
                        .is_some()
                {
                    self.interaction_context = InteractionContext::Scrollback;
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: true },
                    );
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::PointerDown {
                            point: (mouse.column, mouse.row),
                            link_modifier_held: link_modifier_held(mouse.modifiers),
                        },
                    );
                }
                Vec::new()
            }
            Event::Resize(_, _) | Event::FocusGained | Event::FocusLost | Event::Key(_) => {
                Vec::new()
            }
        };
        TerminalEventOutcome {
            actions,
            needs_frame: true,
        }
    }

    fn mouse_scroll_target(&self) -> Option<MouseScrollTarget> {
        if self.fatal.is_some()
            || self.history_search.is_some()
            || self.workspace_search.is_some()
            || self.model_picker.is_some()
            || self.model_management.is_some()
            || self.usage_plugin_management.is_some()
            || self.mcp_settings.is_some()
        {
            return None;
        }
        if let Some(dialog) = self.dialog.as_ref() {
            if matches!(dialog, RequestDialog::Question(_)) {
                return self
                    .last_mouse_position
                    .filter(|position| {
                        self.dialog_pointer
                            .preview_area()
                            .is_some_and(|area| area.contains((*position).into()))
                    })
                    .map(|_| MouseScrollTarget::QuestionPreview);
            }
            if !matches!(dialog, RequestDialog::Permission { .. }) {
                return None;
            }
        }
        match self.overlay.as_ref().map(|overlay| overlay.kind) {
            Some(OverlayKind::BlockViewer) => Some(MouseScrollTarget::BlockViewer),
            Some(
                OverlayKind::Help
                | OverlayKind::Json
                | OverlayKind::ReloadSummary
                | OverlayKind::Context
                | OverlayKind::GoalConsole,
            ) => None,
            None => {
                if self.last_mouse_position.is_some_and(|position| {
                    self.renderer_side_question.area.contains(position.into())
                }) && self.renderer_side_question.focused
                {
                    Some(MouseScrollTarget::SideQuestion)
                } else {
                    Some(MouseScrollTarget::Transcript)
                }
            }
        }
    }

    fn synchronize_mouse_scroll_target(&mut self) {
        let target = self.mouse_scroll_target();
        if target != self.mouse_scroll_target_affinity {
            self.mouse_scroll.cancel_stream();
            self.mouse_scroll_target_affinity = target;
        }
    }

    fn mouse_scroll_viewport_height(&self, target: MouseScrollTarget) -> Option<u16> {
        match target {
            MouseScrollTarget::Transcript => {
                Some(u16::try_from(self.transcript_viewport_height).unwrap_or(u16::MAX))
            }
            MouseScrollTarget::SideQuestion => {
                Some(self.renderer_side_question.area.height.saturating_sub(2))
            }
            MouseScrollTarget::BlockViewer => self
                .overlay
                .as_ref()
                .filter(|overlay| overlay.kind == OverlayKind::BlockViewer)
                .and_then(|overlay| overlay.body_viewport_height),
            MouseScrollTarget::QuestionPreview => self
                .dialog_pointer
                .preview_area()
                .map(|area| area.height.max(1)),
        }
    }

    fn apply_mouse_scroll_lines(&mut self, target: MouseScrollTarget, lines: i32) -> bool {
        if lines == 0 {
            return false;
        }
        match target {
            MouseScrollTarget::Transcript => {
                let rows = u16::try_from(lines.unsigned_abs()).unwrap_or(u16::MAX);
                self.enqueue_transcript_view_action(if lines < 0 {
                    crate::agent_view::TranscriptViewAction::ScrollUp(rows)
                } else {
                    crate::agent_view::TranscriptViewAction::ScrollDown(rows)
                });
                #[cfg(test)]
                {
                    let before = (self.scroll.offset(), self.scroll.is_following());
                    if lines < 0 {
                        self.scroll.scroll_up(lines.unsigned_abs() as usize);
                    } else {
                        self.scroll.scroll_down(
                            lines as usize,
                            self.transcript_line_count,
                            self.transcript_viewport_height,
                        );
                    }
                    before != (self.scroll.offset(), self.scroll.is_following())
                }
                #[cfg(not(test))]
                {
                    true
                }
            }
            MouseScrollTarget::SideQuestion => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ScrollSideQuestion { rows: lines },
                );
                true
            }
            MouseScrollTarget::BlockViewer => {
                let Some(overlay) = self
                    .overlay
                    .as_mut()
                    .filter(|overlay| overlay.kind == OverlayKind::BlockViewer)
                else {
                    return false;
                };
                overlay.scroll_by(lines)
            }
            MouseScrollTarget::QuestionPreview => {
                let Some(RequestDialog::Question(dialog)) = self.dialog.as_mut() else {
                    return false;
                };
                let before = dialog.preview_scroll;
                dialog.preview_scroll = if lines < 0 {
                    dialog
                        .preview_scroll
                        .saturating_sub(lines.unsigned_abs() as usize)
                } else {
                    dialog
                        .preview_scroll
                        .saturating_add(lines as usize)
                        .min(dialog.preview_max_scroll)
                };
                before != dialog.preview_scroll
            }
        }
    }

    /// Flush residual scroll demand and finalize streams on their dedicated
    /// clock. This is renderer-only animation work and never emits a host
    /// action.
    pub(crate) fn set_mouse_scroll_redraw_cadence(&mut self, cadence: Duration) {
        self.mouse_scroll.set_redraw_cadence(cadence);
    }

    pub(crate) fn tick_mouse_scroll(&mut self) -> bool {
        self.synchronize_mouse_scroll_target();
        let lines = self.mouse_scroll.on_tick().lines;
        let Some(target) = self.mouse_scroll_target() else {
            return false;
        };
        self.apply_mouse_scroll_lines(target, lines)
    }

    pub(crate) fn mouse_scroll_deadline(&mut self, now: Instant) -> Option<Duration> {
        self.synchronize_mouse_scroll_target();
        self.mouse_scroll.scroll_clock_deadline(now)
    }

    fn active_keybinding_contexts(&self) -> Vec<CrabcodeKeybindingContext> {
        let mut contexts = Vec::with_capacity(5);
        if self.dialog.is_some() {
            if !self.dialog_response_inflight {
                match self.dialog.as_ref() {
                    Some(RequestDialog::Setup(SetupDialog {
                        kind: SetupDialogKind::OnboardingTheme { .. },
                        ..
                    })) => {
                        contexts.push(CrabcodeKeybindingContext::ThemePicker);
                        contexts.push(CrabcodeKeybindingContext::Confirmation);
                    }
                    Some(
                        RequestDialog::Permission { .. }
                        | RequestDialog::GroveTerms { .. }
                        | RequestDialog::Setup(_),
                    ) => {
                        contexts.push(CrabcodeKeybindingContext::Confirmation);
                    }
                    // AskUserQuestion owns a complete option/input/action
                    // state machine. Borrowing Confirmation here makes its
                    // historical `confirm:cycleMode` Shift+Tab binding win
                    // before the question dialog can process BackTab.
                    Some(RequestDialog::Question(_)) => {}
                    Some(RequestDialog::Elicitation { mode, .. }) if mode == "url" => {
                        contexts.push(CrabcodeKeybindingContext::Confirmation);
                    }
                    Some(RequestDialog::SetupInput(_) | RequestDialog::Elicitation { .. }) => {}
                    None => {}
                }
            }
        } else if self.history_search.is_some() {
            contexts.push(CrabcodeKeybindingContext::HistorySearch);
        } else if self.workspace_search.is_some() {
            // QuickOpen and GlobalSearch retain the fixed FuzzyPicker-owned
            // query/navigation lifecycle; only Global quit remains active.
        } else if self.model_picker.is_some() {
            contexts.push(CrabcodeKeybindingContext::ModelPicker);
            contexts.push(CrabcodeKeybindingContext::Select);
        } else if self
            .overlay
            .as_ref()
            .is_some_and(|overlay| overlay.kind == OverlayKind::Help)
        {
            contexts.push(CrabcodeKeybindingContext::Help);
            contexts.push(CrabcodeKeybindingContext::Tabs);
        } else if self.goal_console_open() {
            contexts.push(CrabcodeKeybindingContext::GoalConsole);
            // The opening chord is a Chat binding in the fixed historical
            // registry and remains a two-way toggle while this overlay owns
            // ordinary input.
            contexts.push(CrabcodeKeybindingContext::Chat);
        } else if self.overlay.is_some() {
            // Non-help overlays retain their renderer-native navigation.
        } else if self.composer_attachment_navigation_active {
            contexts.push(CrabcodeKeybindingContext::Attachments);
        } else if self.interaction_context == InteractionContext::Scrollback {
            contexts.push(CrabcodeKeybindingContext::Transcript);
            contexts.push(CrabcodeKeybindingContext::Scroll);
        } else {
            contexts.push(CrabcodeKeybindingContext::Chat);
            if !self.command_palette.matches.is_empty() {
                contexts.push(CrabcodeKeybindingContext::Autocomplete);
            }
        }
        contexts.push(CrabcodeKeybindingContext::Global);
        contexts
    }

    fn copy_oauth_browser_url(&mut self) -> bool {
        let Some(prompt) = self
            .oauth_browser_prompt
            .as_ref()
            .filter(|prompt| prompt.revealed)
        else {
            return false;
        };
        let url = prompt.url.clone();
        match crate::tui_clipboard::set_text(&url) {
            Ok(()) => {
                let Some(prompt) = self.oauth_browser_prompt.as_mut() else {
                    unreachable!("OAuth browser prompt existed before clipboard delivery")
                };
                // Historical direct TUI starts the acknowledgement window only
                // after the clipboard operation has actually completed.
                prompt.copied_until = Some(Instant::now() + OAUTH_BROWSER_COPIED_DURATION);
                self.status = self
                    .renderer_ui_language
                    .text("已复制身份验证网址", "Copied authentication URL")
                    .to_string();
            }
            Err(error) => {
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!("复制身份验证网址失败：{error}"),
                    UiLanguage::EnUs => format!("Failed to copy authentication URL: {error}"),
                };
            }
        }
        true
    }

    fn handle_key(&mut self, key: KeyEvent, arrived_at: Instant) -> Vec<HostAction> {
        self.synchronize_modal_tree();
        // Terminals that accept REPORT_EVENT_TYPES emit `Repeat` while a key
        // remains held. Lifecycle shortcuts require a second deliberate key
        // press: treating an auto-repeat as that confirmation can cancel the
        // active tool on the initial Ctrl-C and then immediately close the
        // whole TUI. Preserve repeats for editing/navigation, but never let
        // them confirm Interrupt/Quit.
        if key.kind == KeyEventKind::Repeat
            && matches!(
                self.action_registry
                    .lookup(&key, InteractionContext::Global),
                Some(TuiActionId::Interrupt | TuiActionId::Quit)
            )
        {
            return Vec::new();
        }
        if self.active_modal().is_none()
            && self.composer_image_preview.is_none()
            && self.handle_side_question_key(&key)
        {
            return Vec::new();
        }
        if self.active_modal() == Some(ActiveModal::HistorySearch) {
            let active_contexts = self.active_keybinding_contexts();
            match self
                .action_registry
                .resolve_keybinding(&key, &active_contexts)
            {
                CrabcodeKeybindingResolution::Match(TuiActionId::Quit) => {
                    self.request_confirmed_quit();
                    return Vec::new();
                }
                CrabcodeKeybindingResolution::Match(
                    action @ (TuiActionId::Redraw
                    | TuiActionId::HistorySearchNext
                    | TuiActionId::HistorySearchAccept
                    | TuiActionId::HistorySearchCancel
                    | TuiActionId::HistorySearchExecute),
                ) => return self.execute_interaction_action(action),
                CrabcodeKeybindingResolution::ChordStarted
                | CrabcodeKeybindingResolution::ChordCancelled => return Vec::new(),
                CrabcodeKeybindingResolution::Match(_)
                | CrabcodeKeybindingResolution::Command(_)
                | CrabcodeKeybindingResolution::Unmapped
                | CrabcodeKeybindingResolution::None => {}
            }
            return self.handle_history_search_event(Event::Key(key));
        }
        if self.active_modal() == Some(ActiveModal::WorkspaceSearch) {
            if self
                .action_registry
                .lookup(&key, InteractionContext::Global)
                == Some(TuiActionId::Quit)
            {
                self.request_confirmed_quit();
                return Vec::new();
            }
            return self.handle_workspace_search_event(Event::Key(key), arrived_at);
        }
        if self.active_modal() == Some(ActiveModal::McpSettings) {
            if self
                .action_registry
                .lookup(&key, InteractionContext::Global)
                == Some(TuiActionId::Quit)
            {
                self.request_confirmed_quit();
                return Vec::new();
            }
            return self.handle_mcp_settings_key(key);
        }
        if self.active_modal() == Some(ActiveModal::ModelManagement) {
            if self
                .action_registry
                .lookup(&key, InteractionContext::Global)
                == Some(TuiActionId::Quit)
            {
                self.request_confirmed_quit();
                return Vec::new();
            }
            return self.handle_model_management_key(key);
        }
        if self.active_modal() == Some(ActiveModal::UsagePluginManagement) {
            if self
                .action_registry
                .lookup(&key, InteractionContext::Global)
                == Some(TuiActionId::Quit)
            {
                self.request_confirmed_quit();
                return Vec::new();
            }
            return self.handle_usage_plugin_management_key(key);
        }
        let active_modal = self.active_modal();
        if matches!(
            active_modal,
            Some(ActiveModal::Overlay | ActiveModal::Fatal)
        ) {
            let global_action = self
                .action_registry
                .lookup(&key, InteractionContext::Global);
            if global_action == Some(TuiActionId::Quit) {
                self.request_confirmed_quit();
                return Vec::new();
            }
            if active_modal == Some(ActiveModal::Fatal)
                && global_action == Some(TuiActionId::Interrupt)
            {
                return self.handle_ctrl_c();
            }
            return if active_modal == Some(ActiveModal::Overlay) {
                self.handle_overlay_key(key)
            } else {
                Vec::new()
            };
        }
        if self.transcript_search.is_some() {
            if self
                .action_registry
                .lookup(&key, InteractionContext::Global)
                == Some(TuiActionId::Quit)
            {
                self.request_confirmed_quit();
                return Vec::new();
            }
            if let Some(actions) = self.handle_transcript_search_key(&key) {
                return actions;
            }
        }
        // Fixed minimal lifecycle: Ctrl-E is a direct key intercept because
        // minimal mode deliberately has no interactive scrollback context and
        // therefore removes ToggleAllThinking from its action registry.
        if self.minimal_mode
            && self.active_modal().is_none()
            && key.code == KeyCode::Char('e')
            && key.modifiers == KeyModifiers::CONTROL
        {
            self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::MinimalExpandLast,
            );
            return Vec::new();
        }
        if key.code == KeyCode::Char('c')
            && key.modifiers.is_empty()
            && self.copy_oauth_browser_url()
        {
            return Vec::new();
        }
        if self.interaction_context == InteractionContext::Scrollback
            && self.renderer_text_selection_active
            && ((key.code == KeyCode::Esc && key.modifiers.is_empty())
                || (key.code == KeyCode::Char('c') && key.modifiers == KeyModifiers::CONTROL))
        {
            let action = if key.code == KeyCode::Esc {
                self.renderer_text_selection_active = false;
                crate::agent_view::TranscriptViewAction::ClearTextSelection
            } else {
                crate::agent_view::TranscriptViewAction::CopyTextSelection
            };
            self.enqueue_transcript_view_action(action);
            return Vec::new();
        }
        if self.composer_image_preview.is_some() && !self.composer_attachment_navigation_active {
            self.clear_composer_image_preview();
            if key.code == KeyCode::Esc {
                return Vec::new();
            }
        }
        // Transcript link selection owns its first plain Esc. The next Esc is
        // then free to resolve as the historical transcript-exit action.
        if self.interaction_context == InteractionContext::Scrollback
            && key.code == KeyCode::Esc
            && key.modifiers.is_empty()
            && self.has_renderer_link_highlight()
        {
            self.clear_renderer_link_highlight(true);
            return Vec::new();
        }

        if !self.composer_attachment_navigation_active
            && self.dialog.is_none()
            && self.model_picker.is_none()
            && self.mcp_settings.is_none()
            && self.overlay.is_none()
            && self.fatal.is_none()
            && self.interaction_context == InteractionContext::Prompt
            && !self.attachments.is_empty()
        {
            if self.composer.is_empty()
                && self
                    .action_registry
                    .lookup_keybinding(&key, &[CrabcodeKeybindingContext::Attachments])
                    == CrabcodeKeybindingResolution::Match(TuiActionId::AttachmentRemove)
            {
                return self.execute_interaction_action(TuiActionId::AttachmentRemove);
            }
            if self.command_palette.matches.is_empty()
                && key.code == KeyCode::Down
                && key.modifiers.is_empty()
            {
                self.select_latest_attachment();
                return Vec::new();
            }
        }

        // Both fixed source TUIs give an open slash-command picker ownership
        // of plain Enter before the chat submit binding. This prevents a
        // partial token such as `/m` from reaching the unchanged backend slash
        // resolver as an unknown command.
        if self.interaction_context == InteractionContext::Prompt
            && !self.command_palette.matches.is_empty()
            && key.code == KeyCode::Enter
            && key.modifiers.is_empty()
        {
            return self.accept_selected_command(true);
        }

        // The fixed picker state machine gives its active query editor first
        // ownership of plain `j`/`k`; only an inactive search may interpret
        // them as selection aliases. The product-level Select registry is
        // resolved outside that state machine, so route the two colliding
        // characters into the picker before resolving Select bindings.
        if self.model_picker.as_ref().is_some_and(|picker| {
            picker.lifecycle().search_active
                && key.modifiers.is_empty()
                && matches!(key.code, KeyCode::Char('j' | 'k'))
        }) {
            return self.handle_model_picker_event(Event::Key(key));
        }

        let active_contexts = self.active_keybinding_contexts();
        match self
            .action_registry
            .resolve_keybinding(&key, &active_contexts)
        {
            CrabcodeKeybindingResolution::Match(action) => {
                let default_history_cursor_fallback = match action {
                    TuiActionId::HistoryPrevious => {
                        key.code == KeyCode::Up
                            && key.modifiers.is_empty()
                            && self.composer_history.selected.is_none()
                            && !self.composer_cursor_on_first_line()
                    }
                    TuiActionId::HistoryNext => {
                        key.code == KeyCode::Down
                            && key.modifiers.is_empty()
                            && self.composer_history.selected.is_none()
                    }
                    _ => false,
                };
                if default_history_cursor_fallback && self.composer_enabled() {
                    self.reset_composer_history_navigation();
                    self.composer.input(key);
                    self.deliver_composer_clipboard();
                    self.refresh_command_palette();
                    return Vec::new();
                }
                return self.execute_interaction_action(action);
            }
            CrabcodeKeybindingResolution::Command(command_name) => {
                // Fixed historical command handlers are active only with the
                // Chat surface and no modal overlay. Global command bindings
                // must not leak through a dialog merely because Global is
                // also an active context.
                if active_contexts.contains(&CrabcodeKeybindingContext::Chat) {
                    return self.execute_command_keybinding(&command_name);
                }
            }
            CrabcodeKeybindingResolution::ChordStarted
            | CrabcodeKeybindingResolution::ChordCancelled => return Vec::new(),
            CrabcodeKeybindingResolution::Unmapped | CrabcodeKeybindingResolution::None => {}
        }
        if self.composer_attachment_navigation_active {
            if key.code == KeyCode::Up && key.modifiers.is_empty() {
                self.clear_composer_image_preview();
            }
            // The historical attachment-selection state unfocuses its text
            // input. Only attachment bindings, raw Up, and Global bindings
            // are meaningful until selection exits.
            return Vec::new();
        }
        if self
            .action_registry
            .lookup(&key, InteractionContext::Global)
            == Some(TuiActionId::Quit)
        {
            self.request_confirmed_quit();
            return Vec::new();
        }
        match self.active_modal() {
            Some(ActiveModal::Fatal) => return Vec::new(),
            Some(ActiveModal::Request) => return self.handle_dialog_key(key),
            Some(ActiveModal::Overlay) => return self.handle_overlay_key(key),
            Some(ActiveModal::ModelPicker) => return self.handle_model_picker_key(key),
            Some(ActiveModal::ModelManagement) => {
                return self.handle_model_management_key(key);
            }
            Some(ActiveModal::UsagePluginManagement) => {
                return self.handle_usage_plugin_management_key(key);
            }
            Some(ActiveModal::McpSettings) => return self.handle_mcp_settings_key(key),
            Some(ActiveModal::HistorySearch) => {
                return self.handle_history_search_event(Event::Key(key));
            }
            Some(ActiveModal::WorkspaceSearch) => {
                return self.handle_workspace_search_event(Event::Key(key), arrived_at);
            }
            None => {}
        }
        if self
            .action_registry
            .lookup(&key, InteractionContext::Global)
            == Some(TuiActionId::OpenHelp)
        {
            return self.execute_interaction_action(TuiActionId::OpenHelp);
        }
        if self.interaction_context == InteractionContext::Prompt
            && key.code == KeyCode::Tab
            && key.modifiers.is_empty()
            && self.composer.is_empty()
            && self.projection.prompt_suggestion().is_some()
        {
            if let Some(suggestion) = self.projection.prompt_suggestion() {
                let suggestion = utf8_prefix_within(suggestion, MAX_COMPOSER_TEXT_BYTES);
                self.composer.set_text(suggestion);
                self.composer.set_cursor(suggestion.len());
            }
            return Vec::new();
        }
        if self
            .action_registry
            .lookup(&key, InteractionContext::Global)
            == Some(TuiActionId::ToggleTranscript)
        {
            return self.execute_interaction_action(TuiActionId::ToggleTranscript);
        }
        if let Some(action) = self.action_registry.lookup(&key, self.interaction_context) {
            return self.execute_interaction_action(action);
        }
        if self.interaction_context == InteractionContext::Scrollback {
            return Vec::new();
        }
        match key {
            KeyEvent {
                code: KeyCode::Enter,
                modifiers,
                ..
            } if modifiers == (KeyModifiers::CONTROL | KeyModifiers::SHIFT) => {
                self.submit_composer_with_priority(Some("later"))
            }
            KeyEvent {
                code: KeyCode::Enter,
                modifiers: KeyModifiers::CONTROL,
                ..
            } => self.submit_composer_with_priority(Some("now")),
            KeyEvent {
                code: KeyCode::Enter,
                ..
            } => {
                if self.composer.text().len() >= MAX_COMPOSER_TEXT_BYTES {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("已达到输入区上限（{MAX_COMPOSER_TEXT_BYTES} 字节）")
                        }
                        UiLanguage::EnUs => {
                            format!("Composer limit ({MAX_COMPOSER_TEXT_BYTES} bytes) reached")
                        }
                    };
                    return Vec::new();
                }
                self.reset_composer_history_navigation();
                self.composer.insert_str("\n");
                self.refresh_command_palette();
                Vec::new()
            }
            KeyEvent {
                code: KeyCode::Up, ..
            } if self.composer_history.selected.is_some()
                || self.composer_cursor_on_first_line() =>
            {
                self.composer_history_previous();
                Vec::new()
            }
            KeyEvent {
                code: KeyCode::Down,
                ..
            } if self.composer_history.selected.is_some() => {
                self.composer_history_next();
                Vec::new()
            }
            _ if self.composer_enabled() => {
                if is_text_input_key(&key)
                    && let KeyCode::Char(character) = key.code
                    && self
                        .composer
                        .text()
                        .len()
                        .saturating_add(character.len_utf8())
                        > MAX_COMPOSER_TEXT_BYTES
                {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("已达到输入区上限（{MAX_COMPOSER_TEXT_BYTES} 字节）")
                        }
                        UiLanguage::EnUs => {
                            format!("Composer limit ({MAX_COMPOSER_TEXT_BYTES} bytes) reached")
                        }
                    };
                    return Vec::new();
                }
                self.reset_composer_history_navigation();
                self.composer.input(key);
                self.deliver_composer_clipboard();
                self.refresh_command_palette();
                Vec::new()
            }
            _ => Vec::new(),
        }
    }

    fn handle_side_question_key(&mut self, key: &KeyEvent) -> bool {
        let panel = self.renderer_side_question;
        if !panel.active || panel.area.area() == 0 {
            return false;
        }
        let dismiss = (key.modifiers.is_empty()
            && matches!(key.code, KeyCode::Esc | KeyCode::Enter | KeyCode::Char(' ')))
            || (key.modifiers == KeyModifiers::CONTROL
                && matches!(key.code, KeyCode::Char('c' | 'd')));
        if dismiss {
            self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::DismissSideQuestion,
            );
            self.status = match (self.renderer_ui_language, panel.loading) {
                (UiLanguage::ZhCn, true) => "已关闭正在处理的旁路提问".to_string(),
                (UiLanguage::ZhCn, false) => "已关闭旁路提问".to_string(),
                (UiLanguage::EnUs, true) => "Dismissed in-flight side question".to_string(),
                (UiLanguage::EnUs, false) => "Dismissed side question".to_string(),
            };
            return true;
        }

        let page = panel.area.height.saturating_sub(2).max(1) as i32;
        let rows = match (key.code, key.modifiers) {
            (KeyCode::Up, KeyModifiers::NONE) | (KeyCode::Char('p'), KeyModifiers::CONTROL) => {
                Some(-3)
            }
            (KeyCode::Down, KeyModifiers::NONE) | (KeyCode::Char('n'), KeyModifiers::CONTROL) => {
                Some(3)
            }
            (KeyCode::PageUp, KeyModifiers::NONE) => Some(-page),
            (KeyCode::PageDown, KeyModifiers::NONE) => Some(page),
            _ => None,
        };
        let Some(rows) = rows else {
            return false;
        };
        self.enqueue_transcript_view_action(
            crate::agent_view::TranscriptViewAction::ScrollSideQuestion { rows },
        );
        // The historical panel owns these keys even when the current response
        // fits; consuming them prevents its focused navigation from leaking
        // into transcript/composer state.
        true
    }

    fn execute_interaction_action(&mut self, action: TuiActionId) -> Vec<HostAction> {
        match action {
            TuiActionId::Interrupt => return self.handle_ctrl_c(),
            TuiActionId::Quit => self.request_confirmed_quit(),
            TuiActionId::Redraw => {
                // The terminal owner consumes this one-shot after normal
                // input dispatch and routes it into the fixed full-repaint
                // branch. No renderer action crosses the direct-runtime wire.
                self.pending_force_repaint = true;
            }
            TuiActionId::OpenHelp => self.open_help(),
            TuiActionId::ToggleTranscript => {
                if self.interaction_context == InteractionContext::Scrollback {
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: false },
                    );
                    self.transcript_search = None;
                    self.pending_transcript_search_reveal = None;
                    self.interaction_context = InteractionContext::Prompt;
                    self.clear_renderer_link_highlight(false);
                    self.status = self
                        .renderer_ui_language
                        .text("输入区已聚焦", "Composer focused")
                        .to_string();
                } else {
                    self.enqueue_transcript_view_action(
                        crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: true },
                    );
                    self.interaction_context = InteractionContext::Scrollback;
                    #[cfg(test)]
                    self.activate_scrollback_selection();
                    self.status = self
                        .renderer_ui_language
                        .text(
                            "对话记录已聚焦 · Ctrl-O 返回输入区",
                            "Transcript focused · Ctrl-O returns to composer",
                        )
                        .to_string();
                }
            }
            TuiActionId::CancelPrompt => return self.cancel_active_turn(),
            TuiActionId::UndoPrompt => {
                if self.composer_enabled() && self.composer.undo() {
                    self.reset_composer_history_navigation();
                    self.refresh_command_palette();
                    self.status = self
                        .renderer_ui_language
                        .text("已撤销上一次草稿编辑", "Undid the previous draft edit")
                        .to_string();
                }
            }
            TuiActionId::StashPrompt => self.toggle_composer_stash(),
            TuiActionId::OpenExternalEditor => self.request_external_editor(),
            TuiActionId::FocusPrompt => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: false },
                );
                self.transcript_search = None;
                self.pending_transcript_search_reveal = None;
                self.interaction_context = InteractionContext::Prompt;
                self.status = self
                    .renderer_ui_language
                    .text("输入区已聚焦", "Composer focused")
                    .to_string();
            }
            TuiActionId::FocusScrollback => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: true },
                );
                self.interaction_context = InteractionContext::Scrollback;
                #[cfg(test)]
                self.activate_scrollback_selection();
                self.status = self
                    .renderer_ui_language
                    .text(
                        "对话记录已聚焦 · Tab 返回输入区",
                        "Transcript focused · Tab returns to composer",
                    )
                    .to_string();
            }
            TuiActionId::ExitTranscript => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: false },
                );
                self.transcript_search = None;
                self.pending_transcript_search_reveal = None;
                self.interaction_context = InteractionContext::Prompt;
                self.clear_renderer_link_highlight(false);
                self.status = self
                    .renderer_ui_language
                    .text("输入区已聚焦", "Composer focused")
                    .to_string();
            }
            TuiActionId::SelectNext => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::SelectNext,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                self.select_transcript_item(TranscriptSelectionDirection::Down);
            }
            TuiActionId::SelectPrevious => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::SelectPrevious,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                self.select_transcript_item(TranscriptSelectionDirection::Up);
            }
            TuiActionId::CollapseSelected => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::CollapseSelected,
                );
                #[cfg(test)]
                self.mutate_selected_display_mode(|item, _current| {
                    projected_item_collapse_mode(item)
                });
            }
            TuiActionId::ExpandSelected => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ExpandSelected,
                );
                #[cfg(test)]
                self.mutate_selected_display_mode(|_item, _current| {
                    TranscriptDisplayMode::Expanded
                });
            }
            TuiActionId::ToggleSelectedFold => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ToggleFoldSelected,
                );
                #[cfg(test)]
                self.mutate_selected_display_mode(projected_item_next_fold_mode);
            }
            TuiActionId::ToggleExpandAll => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ToggleExpandAll,
                );
                #[cfg(test)]
                self.toggle_expand_all();
            }
            TuiActionId::ToggleAllThinking => {
                self.enqueue_transcript_view_action(if self.minimal_mode {
                    crate::agent_view::TranscriptViewAction::MinimalExpandLast
                } else {
                    crate::agent_view::TranscriptViewAction::ToggleThinking
                });
                #[cfg(test)]
                if !self.minimal_mode {
                    self.toggle_all_thinking();
                }
            }
            TuiActionId::ScrollLineUp => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ScrollUp(1),
                );
                #[cfg(test)]
                self.scroll.scroll_up(1);
            }
            TuiActionId::ScrollLineDown => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ScrollDown(1),
                );
                #[cfg(test)]
                self.scroll.scroll_down(
                    1,
                    self.transcript_line_count,
                    self.transcript_viewport_height,
                );
            }
            TuiActionId::ScrollHalfPageUp => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::HalfPageUp,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                self.scroll.scroll_up(self.transcript_viewport_height / 2);
            }
            TuiActionId::ScrollHalfPageDown => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::HalfPageDown,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                self.scroll.scroll_down(
                    self.transcript_viewport_height / 2,
                    self.transcript_line_count,
                    self.transcript_viewport_height,
                );
            }
            TuiActionId::ScrollPageUp => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::PageUp,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                {
                    self.scroll.scroll_up(self.transcript_page_scroll_rows());
                    self.select_transcript_viewport_edge(true);
                }
            }
            TuiActionId::ScrollPageDown => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::PageDown,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                {
                    let rows = self.transcript_page_scroll_rows();
                    self.scroll.scroll_down(
                        rows,
                        self.transcript_line_count,
                        self.transcript_viewport_height,
                    );
                    self.select_transcript_viewport_edge(false);
                }
            }
            TuiActionId::ScrollTop => {
                self.enqueue_transcript_view_action(crate::agent_view::TranscriptViewAction::Top);
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                {
                    self.scroll.set_offset(
                        0,
                        self.transcript_line_count,
                        self.transcript_viewport_height,
                    );
                    self.select_transcript_viewport_edge(true);
                }
            }
            TuiActionId::ScrollBottom => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::Bottom,
                );
                #[cfg(test)]
                {
                    let _ = self.links.take_current();
                }
                #[cfg(test)]
                {
                    self.scroll
                        .follow(self.transcript_line_count, self.transcript_viewport_height);
                    self.select_transcript_viewport_edge(false);
                }
            }
            TuiActionId::NextTurn => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::NextTurn,
                );
                #[cfg(test)]
                self.navigate_turn(TranscriptSelectionDirection::Down);
            }
            TuiActionId::PreviousTurn => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::PreviousTurn,
                );
                #[cfg(test)]
                self.navigate_turn(TranscriptSelectionDirection::Up);
            }
            TuiActionId::NextResponse => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::NextResponse,
                );
                #[cfg(test)]
                self.navigate_response_anchor(TranscriptSelectionDirection::Down);
            }
            TuiActionId::PreviousResponse => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::PreviousResponse,
                );
                #[cfg(test)]
                self.navigate_response_anchor(TranscriptSelectionDirection::Up);
            }
            TuiActionId::ToggleRaw => {
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::ToggleRawSelected,
                );
                #[cfg(test)]
                self.toggle_selected_raw();
            }
            TuiActionId::CopyTextSelection => self.enqueue_transcript_view_action(
                crate::agent_view::TranscriptViewAction::CopyTextSelection,
            ),
            TuiActionId::CopyBlockContent => self.copy_selected_block_content(),
            TuiActionId::CopyBlockMeta => self.copy_selected_block_meta(),
            TuiActionId::OpenBlockViewer => {
                #[cfg(not(test))]
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::OpenHighlightedLinkOrBlockViewer,
                );
                #[cfg(test)]
                {
                    if let Some(selected) = self.links.take_current() {
                        self.open_renderer_link_target(selected.target);
                    } else {
                        self.open_selected_block_viewer_without_link();
                    }
                }
            }
            TuiActionId::CycleLinkForward | TuiActionId::CycleLinkBackward => {
                let forward = action == TuiActionId::CycleLinkForward;
                self.enqueue_transcript_view_action(
                    crate::agent_view::TranscriptViewAction::CycleHighlightedLink { forward },
                );
                #[cfg(test)]
                {
                    let ui_language = self.renderer_ui_language;
                    self.status = self.links.cycle(forward).map_or_else(
                        || {
                            ui_language
                                .text(
                                    "当前没有可见的对话链接",
                                    "No visible transcript links available",
                                )
                                .to_string()
                        },
                        |target| match ui_language {
                            UiLanguage::ZhCn => format!("已选择可见链接：{target}"),
                            UiLanguage::EnUs => format!("Selected visible link: {target}"),
                        },
                    );
                }
            }
            TuiActionId::KillBackgroundTask => return self.stop_selected_background_task(),
            TuiActionId::SubmitPrompt => {
                return self.submit_composer_with_priority(None);
            }
            TuiActionId::NewlinePrompt => {
                if self.composer.text().len() >= MAX_COMPOSER_TEXT_BYTES {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("已达到输入区上限（{MAX_COMPOSER_TEXT_BYTES} 字节）")
                        }
                        UiLanguage::EnUs => {
                            format!("Composer limit ({MAX_COMPOSER_TEXT_BYTES} bytes) reached")
                        }
                    };
                } else {
                    self.reset_composer_history_navigation();
                    self.composer.insert_str("\n");
                    self.refresh_command_palette();
                }
            }
            TuiActionId::OpenHistorySearch => self.open_history_search(),
            TuiActionId::HistorySearchNext => self.select_next_history_match(),
            TuiActionId::HistorySearchAccept => self.accept_selected_history(),
            TuiActionId::HistorySearchCancel => self.close_history_search(),
            TuiActionId::HistorySearchExecute => {
                return self.execute_selected_history();
            }
            TuiActionId::OpenGlobalSearch => {
                self.open_workspace_search(WorkspaceSearchKind::GlobalSearch)
            }
            TuiActionId::OpenQuickOpen => {
                self.open_workspace_search(WorkspaceSearchKind::QuickOpen)
            }
            TuiActionId::HistoryPrevious => self.composer_history_previous(),
            TuiActionId::HistoryNext => self.composer_history_next(),
            TuiActionId::OpenModelPicker => self.open_model_picker(),
            TuiActionId::ImagePaste => self.start_clipboard_probe(),
            TuiActionId::AutocompleteAccept => self.complete_selected_command(),
            TuiActionId::AutocompleteDismiss => {
                self.command_palette = CommandPaletteState::default();
                self.status = self
                    .renderer_ui_language
                    .text("命令建议已关闭", "Command suggestions dismissed")
                    .to_string();
            }
            TuiActionId::AutocompletePrevious => self.select_command_suggestion(false),
            TuiActionId::AutocompleteNext => self.select_command_suggestion(true),
            TuiActionId::ConfirmYes
            | TuiActionId::ConfirmNo
            | TuiActionId::ConfirmPrevious
            | TuiActionId::ConfirmNext
            | TuiActionId::ConfirmNextField
            | TuiActionId::ConfirmPreviousField
            | TuiActionId::ConfirmToggle => {
                return self.handle_confirmation_action(action);
            }
            TuiActionId::ToggleSyntaxHighlighting => {
                let disabled = if let Some(RequestDialog::Setup(SetupDialog {
                    kind:
                        SetupDialogKind::OnboardingTheme {
                            syntax_highlighting_disabled,
                            syntax_toggle_enabled: true,
                        },
                    ..
                })) = self.dialog.as_mut()
                {
                    *syntax_highlighting_disabled = !*syntax_highlighting_disabled;
                    Some(*syntax_highlighting_disabled)
                } else {
                    None
                };
                if let Some(disabled) = disabled {
                    // Fixed ThemePicker writes this renderer setting as soon
                    // as Ctrl+T is pressed; the final setup response remains
                    // the existing persistence authority.
                    self.set_renderer_syntax_highlighting_disabled(disabled);
                }
            }
            TuiActionId::AttachmentNext => self.cycle_composer_attachment(true),
            TuiActionId::AttachmentPrevious => self.cycle_composer_attachment(false),
            TuiActionId::AttachmentRemove => self.remove_selected_composer_attachment(),
            TuiActionId::AttachmentExit => self.clear_composer_image_preview(),
            TuiActionId::ToggleGoalConsole => self.toggle_goal_console(),
            TuiActionId::DismissGoalConsole => {
                if self.goal_console_open() {
                    self.overlay = None;
                }
            }
            TuiActionId::DismissHelp => {
                if self
                    .overlay
                    .as_ref()
                    .is_some_and(|overlay| overlay.kind == OverlayKind::Help)
                {
                    self.overlay = None;
                }
            }
            TuiActionId::NextTab => self.change_help_tab(true),
            TuiActionId::PreviousTab => self.change_help_tab(false),
            TuiActionId::SelectDialogNext => {
                if let Some(picker) = self.model_picker.as_mut() {
                    picker.focus_next();
                }
            }
            TuiActionId::SelectDialogPrevious => {
                if let Some(picker) = self.model_picker.as_mut() {
                    picker.focus_previous();
                }
            }
            TuiActionId::SelectDialogAccept => {
                if self.model_picker.is_some() {
                    return self.accept_selected_model();
                }
            }
            TuiActionId::SelectDialogCancel => {
                if self.model_picker.is_some() {
                    return self.handle_model_picker_event(Event::Key(KeyEvent::new(
                        KeyCode::Esc,
                        KeyModifiers::NONE,
                    )));
                }
            }
            TuiActionId::UnavailableHistorical(action_name) => {
                self.status = match self.renderer_ui_language {
                    UiLanguage::ZhCn => format!(
                        "固定历史快捷键操作 {action_name} 依赖尚未移植的 TUI 界面；输入未转发"
                    ),
                    UiLanguage::EnUs => format!(
                        "Fixed historical keybinding action {action_name} requires an unported TUI \
                         surface; input was not forwarded"
                    ),
                };
            }
        }
        Vec::new()
    }

    fn execute_command_keybinding(&mut self, command_name: &str) -> Vec<HostAction> {
        let command = format!("/{command_name}");
        if let Some(actions) = self.handle_local_command(&command) {
            return actions;
        }

        // Historical command keybindings submit the synthetic slash command
        // without clearing, replacing, attaching to, or recording the user's
        // current draft. Reuse the existing direct SendUser boundary; no new
        // backend request or protocol subtype is introduced.
        self.status = match self.renderer_ui_language {
            UiLanguage::ZhCn => {
                format!("已通过快捷键执行 {command}；输入区草稿保持不变")
            }
            UiLanguage::EnUs => {
                format!("Executed {command} from keybinding; composer draft preserved")
            }
        };
        vec![HostAction::SendUser {
            content: Value::String(command),
            priority: self.busy().then(|| "next".to_string()),
        }]
    }

    fn handle_mermaid_affordance(&mut self, action: MermaidAffordanceAction, source: Arc<str>) {
        if action == MermaidAffordanceAction::CopySource {
            match crate::tui_clipboard::set_text(&source) {
                Ok(()) => {
                    self.status = self
                        .renderer_ui_language
                        .text("已复制 Mermaid 源码", "Copied Mermaid source")
                        .to_string();
                }
                Err(error) => {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => format!("复制 Mermaid 源码失败：{error}"),
                        UiLanguage::EnUs => {
                            format!("Failed to copy Mermaid source: {error}")
                        }
                    };
                }
            }
            return;
        }
        let session_id = self.projection.session_id().map(str::to_string);
        let content_cols =
            representative_content_cols(self.transcript_content_width.saturating_add(12));
        let request = self
            .mermaid_runtime
            .get_or_insert_with(MermaidRuntime::new)
            .request(
                source.to_string(),
                action,
                session_id.as_deref(),
                0,
                true,
                content_cols,
            );
        match request {
            MermaidRequest::Immediate { action, path } => {
                self.complete_mermaid_action(action, path);
            }
            MermaidRequest::Queued | MermaidRequest::AlreadyPending => {
                self.status = self
                    .renderer_ui_language
                    .text("正在渲染 Mermaid 图表…", "Rendering Mermaid diagram…")
                    .to_string();
            }
            MermaidRequest::NotReady => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "会话获得权威 ID 后才能生成 Mermaid 图片",
                        "Mermaid image is unavailable until the session has an authoritative id",
                    )
                    .to_string();
            }
            MermaidRequest::WorkerUnavailable => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "Mermaid 渲染工作进程不可用",
                        "Mermaid render worker is unavailable",
                    )
                    .to_string();
            }
        }
    }

    fn poll_mermaid_results(&mut self) -> bool {
        let completions = self
            .mermaid_runtime
            .as_mut()
            .map(MermaidRuntime::poll)
            .unwrap_or_default();
        let changed = !completions.is_empty();
        for completion in completions {
            match completion.outcome {
                MermaidOutcome::Ready { path } => {
                    self.complete_mermaid_action(completion.action, path);
                }
                MermaidOutcome::Failed { reason } => {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => {
                            format!("Mermaid 图片渲染失败（{reason}）；已保留终端图表")
                        }
                        UiLanguage::EnUs => format!(
                            "Mermaid image rendering failed ({reason}); terminal diagram retained"
                        ),
                    };
                }
            }
        }
        changed
    }

    fn complete_mermaid_action(
        &mut self,
        action: MermaidAffordanceAction,
        path: std::path::PathBuf,
    ) {
        match action {
            MermaidAffordanceAction::Open => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "正在打开渲染后的 Mermaid 图片",
                        "Opening rendered Mermaid image",
                    )
                    .to_string();
                self.pending_link_open = Some(LinkTarget::File(Arc::from(path.as_path())));
            }
            MermaidAffordanceAction::CopyPath => {
                let display = path.display().to_string();
                match crate::tui_clipboard::set_text(&display) {
                    Ok(()) => {
                        self.status = match self.renderer_ui_language {
                            UiLanguage::ZhCn => format!("已复制 Mermaid 图片路径：{display}"),
                            UiLanguage::EnUs => {
                                format!("Copied Mermaid image path: {display}")
                            }
                        };
                    }
                    Err(error) => {
                        self.status = match self.renderer_ui_language {
                            UiLanguage::ZhCn => format!("复制 Mermaid 图片路径失败：{error}"),
                            UiLanguage::EnUs => {
                                format!("Failed to copy Mermaid image path: {error}")
                            }
                        };
                    }
                }
            }
            MermaidAffordanceAction::CopySource => {
                self.status = self
                    .renderer_ui_language
                    .text(
                        "Mermaid 内部操作不匹配：复制源码无需渲染",
                        "Internal Mermaid action mismatch: source copy does not require rendering",
                    )
                    .to_string();
            }
        }
    }

    pub(crate) fn mermaid_is_rendering(&self, source: &str) -> bool {
        self.mermaid_runtime
            .as_ref()
            .is_some_and(|runtime| runtime.is_rendering(source))
    }

    #[cfg(test)]
    pub(crate) fn last_mouse_position(&self) -> Option<(u16, u16)> {
        self.last_mouse_position
    }

    /// Take a user-confirmed link request. The outer terminal owner performs
    /// the OS handoff only after it has stopped the input reader and restored
    /// the shell.
    pub(crate) fn take_link_open_request(&mut self) -> Option<LinkTarget> {
        self.pending_link_open.take()
    }

    pub(crate) fn open_renderer_link_target(&mut self, target: LinkTarget) {
        match target {
            LinkTarget::Mermaid { action, source } => {
                self.handle_mermaid_affordance(action, source);
            }
            target => self.pending_link_open = Some(target),
        }
    }

    pub(crate) fn take_terminal_notification_request(
        &mut self,
    ) -> Option<TerminalNotificationRequest> {
        self.pending_terminal_notification.take()
    }

    pub(crate) fn take_force_repaint_request(&mut self) -> bool {
        std::mem::take(&mut self.pending_force_repaint)
    }

    fn worker_permission_terminal_notification_allowed(&self) -> bool {
        // Fixed useInboxPoller gate: `!isLoading && !focusedInputDialog`.
        // The projection's exact idle state owns `isLoading`; every native
        // modal that owns input is represented locally and requires silence.
        self.projection.session_state() == Some("idle")
            && !self.stream_requesting
            && self.dialog.is_none()
            && self.pending_dialogs.is_empty()
            && self.history_search.is_none()
            && self.workspace_search.is_none()
            && self.model_picker.is_none()
            && self.mcp_settings.is_none()
            && !self
                .overlay
                .as_ref()
                .is_some_and(|overlay| overlay.lifecycle.visible)
            && self.fatal.is_none()
            && self.pending_terminal_notification.is_none()
    }

    fn request_external_editor(&mut self) {
        if !self.composer_enabled() || self.pending_external_editor.is_some() {
            return;
        }
        if !self.deferred_input_jobs.is_empty() {
            self.status = self
                .renderer_ui_language
                .text(
                    "仍在处理粘贴内容，暂时无法使用外部编辑器编辑提示词。",
                    "External prompt editing is not available while a paste is still being processed.",
                )
                .to_string();
            return;
        }
        self.pending_external_editor = Some(self.composer.text().to_string());
    }

    /// Take the captured composer draft. The terminal owner performs the
    /// blocking editor handoff only after stopping input and suspending the
    /// renderer.
    pub(crate) fn take_external_editor_request(&mut self) -> Option<String> {
        self.pending_external_editor.take()
    }

    pub(crate) fn take_external_file_open_request(&mut self) -> Option<ExternalFileOpenRequest> {
        self.pending_external_file_open.take()
    }

    pub(crate) fn complete_external_editor(
        &mut self,
        original_text: &str,
        outcome: PromptEditOutcome,
    ) {
        if self.composer.text() != original_text {
            self.status = self
                .renderer_ui_language
                .text(
                    "外部编辑器打开期间草稿已发生变化；已保留较新的草稿。",
                    "The draft changed while the external editor was open; the newer draft was kept.",
                )
                .to_string();
            return;
        }
        match outcome {
            PromptEditOutcome::Content(content) if content != original_text => {
                if content.len() > MAX_COMPOSER_TEXT_BYTES {
                    self.status = match self.renderer_ui_language {
                        UiLanguage::ZhCn => format!(
                            "外部编辑器结果超过输入区 {MAX_COMPOSER_TEXT_BYTES} 字节上限；已保留原草稿。"
                        ),
                        UiLanguage::EnUs => format!(
                            "External editor result exceeded the {MAX_COMPOSER_TEXT_BYTES}-byte composer limit; the original draft was kept."
                        ),
                    };
                    return;
                }
                self.reset_composer_history_navigation();
                self.composer.set_text(&content);
                self.composer.set_cursor(content.len());
                self.composer_state = TextAreaState::default();
                self.refresh_command_palette();
            }
            PromptEditOutcome::Content(_) | PromptEditOutcome::NoChange => {}
            PromptEditOutcome::Failed(message) => {
                self.status = if self.renderer_ui_language == UiLanguage::EnUs {
                    message
                } else if let Some(error) = message.strip_prefix("External editor failed: ") {
                    format!("外部编辑器失败：{error}")
                } else if message
                    == format!(
                        "External editor result exceeded the {MAX_COMPOSER_TEXT_BYTES}-byte composer limit; the original draft was kept."
                    )
                {
                    format!(
                        "外部编辑器结果超过输入区 {MAX_COMPOSER_TEXT_BYTES} 字节上限；已保留原草稿。"
                    )
                } else {
                    format!("外部编辑器未正常退出：{message}")
                };
            }
        }
    }

