fn is_extra_usage_browser_opened_output(content: &str) -> bool {
    let Some(body) = content
        .strip_prefix("<local-command-stdout>")
        .and_then(|body| body.strip_suffix("</local-command-stdout>"))
    else {
        return false;
    };
    let url = body
        .strip_prefix("Browser opened to manage extra usage. If it didn't open, visit: ")
        .or_else(|| {
            body.strip_prefix("Please visit ")
                .and_then(|body| body.strip_suffix(" to manage extra usage."))
        });
    matches!(
        url,
        Some(EXTRA_USAGE_ACCOUNT_URL | EXTRA_USAGE_ORGANIZATION_URL)
    )
}

