    #[test]
    fn shell_phase_is_sticky_and_independent_from_native_welcome_commit() {
        let mut fresh = app();
        assert_eq!(fresh.shell_phase(), ShellPhase::Welcome);
        assert!(fresh.welcome_visible());
        assert!(fresh.minimal_welcome_pending());

        fresh.push_startup_notice("runtime diagnostic".to_string());
        assert_eq!(
            fresh.shell_phase(),
            ShellPhase::Welcome,
            "a BootPrefix notice is not conversation content"
        );

        fresh.mark_minimal_welcome_committed();
        assert_eq!(fresh.shell_phase(), ShellPhase::Welcome);
        assert!(fresh.welcome_visible());
        assert!(!fresh.minimal_welcome_pending());

        let send = HostAction::SendUser {
            content: Value::String("first task".to_string()),
            priority: None,
        };
        fresh.action_admitted(&send);
        assert_eq!(fresh.shell_phase(), ShellPhase::Conversation);
        assert!(!fresh.welcome_visible());
        fresh.action_failed(&send, "writer unavailable");
        assert_eq!(
            fresh.shell_phase(),
            ShellPhase::Conversation,
            "queue admission is the sticky conversation boundary even if later delivery fails"
        );

        fresh.reset_renderer_session_projection_state();
        assert_eq!(fresh.shell_phase(), ShellPhase::Welcome);
        assert!(fresh.minimal_welcome_pending());

        let resumed = TuiApp::new(
            &json!({}),
            InitialSessionRequest::ResumeExact {
                session_id: "existing-session".to_string(),
            },
            None,
        );
        assert_eq!(resumed.shell_phase(), ShellPhase::Conversation);
        assert!(!resumed.minimal_welcome_pending());
    }

    #[test]
    fn only_visible_non_replayed_conversation_records_exit_welcome() {
        let mut fresh = app();
        fresh.handle_runtime_event(raw(
            1,
            json!({
                "type":"user",
                "message":{"role":"user","content":"replayed history"},
                "uuid":"replayed-user",
                "timestamp":"2026-08-12T00:00:00.000Z",
                "isReplay":true
            }),
            EnvelopeClass::User,
        ));
        assert_eq!(fresh.shell_phase(), ShellPhase::Welcome);

        fresh.handle_runtime_event(raw(
            2,
            json!({
                "type":"user",
                "message":{"role":"user","content":"real task"},
                "uuid":"visible-user",
                "timestamp":"2026-08-12T00:00:01.000Z"
            }),
            EnvelopeClass::User,
        ));
        assert_eq!(fresh.shell_phase(), ShellPhase::Conversation);
        assert!(!fresh.minimal_welcome_pending());

        fresh.reset_renderer_session_projection_state();
        fresh.handle_runtime_event(raw(
            3,
            json!({
                "type":"assistant",
                "uuid":"visible-assistant",
                "session_id":"assistant-session",
                "parent_tool_use_id":null,
                "message":{
                    "id":"visible-assistant-message",
                    "content":[{"type":"text","text":"real response"}]
                }
            }),
            EnvelopeClass::Assistant,
        ));
        assert_eq!(fresh.shell_phase(), ShellPhase::Conversation);
        assert!(!fresh.minimal_welcome_pending());
    }

    #[test]
    fn welcome_command_truth_uses_the_visible_completion_authority() {
        let mut app = app();
        assert!(app.welcome_command("help").is_some());
        assert!(app.welcome_command("/model").is_some());
        assert!(app.welcome_command("resume").is_none());
        assert!(app.welcome_command("release-notes").is_none());

        app.commands.push(SlashCommandChoice {
            name: "resume".to_string(),
            description: "Resume a session".to_string(),
            argument_hint: String::new(),
            hidden: true,
            builtin: true,
        });
        app.rebuild_completion_commands();
        assert!(app.welcome_command("resume").is_none());

        app.commands.push(SlashCommandChoice {
            name: "release-notes".to_string(),
            description: "View release notes".to_string(),
            argument_hint: String::new(),
            hidden: false,
            builtin: true,
        });
        app.rebuild_completion_commands();
        assert!(app.welcome_command("release-notes").is_some());

        app.set_slash_commands_enabled(false);
        assert!(app.welcome_command("help").is_none());
        assert!(app.welcome_command("model").is_none());
    }

    fn question_pending(input: Value) -> PendingControl {
        PendingControl {
            request_id: "question-request-1".to_string(),
            subtype: "can_use_tool".to_string(),
            request: json!({
                "subtype":"can_use_tool",
                "tool_name":ASK_USER_QUESTION_TOOL_NAME,
                "tool_use_id":"question-tool-1",
                "agent_id":"worker-a",
                "input":input
            }),
            raw_sequence: 1,
        }
    }

    fn basic_question_input() -> Value {
        json!({
            "questions":[{
                "question":"Which deployment?",
                "header":"Deploy",
                "options":[
                    {
                        "label":"Staging",
                        "description":"Deploy to staging",
                        "recommended":true,
                        "preview":"staging preview\nline two"
                    },
                    {"label":"Production","description":"Deploy to production"}
                ],
                "multiSelect":false
            }]
        })
    }

    fn parsed_question(input: Value) -> RequestDialog {
        dialog_from_pending_with_language(&question_pending(input), UiLanguage::EnUs)
            .expect("valid AskUserQuestion dialog")
    }

    #[test]
    fn question_parser_allocates_collision_safe_ids_without_preselecting_recommended() {
        let dialog = parsed_question(json!({
            "questions":[
                {
                    "question":"First question?",
                    "header":"First",
                    "options":[
                        {"label":"Alpha","description":"First option"},
                        {
                            "id":"question-1-2-option-1",
                            "label":"Beta",
                            "description":"Second option",
                            "recommended":true
                        }
                    ]
                },
                {
                    "id":"question-1",
                    "question":"Second question?",
                    "header":"Second",
                    "options":[
                        {"label":"Gamma","description":"Third option"},
                        {"label":"Delta","description":"Fourth option"}
                    ]
                }
            ]
        }));
        let RequestDialog::Question(dialog) = dialog else {
            panic!("AskUserQuestion must use the specialized question dialog");
        };
        assert_eq!(dialog.agent_id.as_deref(), Some("worker-a"));
        assert_eq!(dialog.questions[0].id, "question-1-2");
        assert_eq!(dialog.questions[0].options[0].id, "question-1-2-option-1-2");
        assert_eq!(dialog.questions[1].id, "question-1");
        assert!(dialog.questions[0].options[1].recommended);
        assert!(dialog.answers.iter().all(|answer| {
            !answer.other_selected && answer.selected.iter().all(|selected| !selected)
        }));
        assert_eq!(
            dialog.normalized_input["questions"][0]["id"],
            "question-1-2"
        );
        assert_eq!(
            dialog.normalized_input["questions"][0]["options"][0]["id"],
            "question-1-2-option-1-2"
        );
        assert_eq!(
            dialog.normalized_input["questions"][1]["options"][0]["recommended"],
            false
        );
    }

    #[test]
    fn question_parser_bounds_generated_option_ids_for_maximum_parent_and_collision() {
        let question_id = "q".repeat(128);
        let reserved_base = format!("{}-option-1", "q".repeat(119));
        let generated_after_collision = format!("{}-option-1-2", "q".repeat(117));
        let dialog = parsed_question(json!({
            "questions":[{
                "id":question_id,
                "question":"Which color?",
                "header":"Color",
                "options":[
                    {"label":"Red","description":"Use red."},
                    {
                        "id":reserved_base,
                        "label":"Blue",
                        "description":"Use blue."
                    }
                ]
            }]
        }));
        let RequestDialog::Question(question_dialog) = &dialog else {
            panic!("AskUserQuestion must use the specialized question dialog");
        };
        assert_eq!(question_dialog.questions[0].id, question_id);
        assert_eq!(
            question_dialog.questions[0].options[0].id,
            generated_after_collision
        );
        assert_eq!(question_dialog.questions[0].options[0].id.len(), 128);
        assert_eq!(question_dialog.questions[0].options[1].id, reserved_base);
        question_identifier(
            &question_dialog.questions[0].options[0].id,
            "generated option",
        )
        .expect("generated option remains a valid protocol identifier");

        let mut app = app();
        app.dialog = Some(dialog);
        assert!(
            app.handle_dialog_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE))
                .is_empty()
        );
        let actions = app.handle_dialog_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        let [HostAction::RespondPermission { response, .. }] = actions.as_slice() else {
            panic!("bounded generated ID must remain submittable");
        };
        assert_eq!(
            response["updatedInput"]["response"]["answers"][0]["questionId"],
            question_id
        );
        assert_eq!(
            response["updatedInput"]["response"]["answers"][0]["selectedOptionIds"],
            json!([generated_after_collision])
        );
    }

