    #[test]
    fn validated_session_transition_resets_old_renderer_state_and_keeps_new_envelope() {
        let mut app = app();
        app.mark_minimal_welcome_committed();
        app.handle_runtime_event(raw(
            1,
            json!({
                "type":"assistant",
                "uuid":"assistant-old",
                "session_id":"session-old",
                "parent_tool_use_id":null,
                "message":{
                    "id":"message-old",
                    "content":[{"type":"text","text":"old transcript"}]
                }
            }),
            EnvelopeClass::Assistant,
        ));
        let old_key = app.projection.items()[0].key.clone();
        app.selected_transcript_key = Some(old_key.clone());
        app.stream_requesting = true;
        app.interrupt_pending = true;
        app.set_live_context_usage_for_test(91_000, 128_000, 71);
        app.context_usage_refresh_pending = true;
        app.context_usage_refresh_dirty = true;
        app.active_tasks
            .insert("background-task".to_string(), "still running".to_string());

        app.handle_runtime_event(raw(
            2,
            json!({
                "type":"assistant",
                "uuid":"assistant-new",
                "session_id":"session-new",
                "parent_tool_use_id":null,
                "message":{
                    "id":"message-new",
                    "content":[{"type":"text","text":"new transcript"}]
                }
            }),
            EnvelopeClass::Assistant,
        ));

        assert_eq!(app.projection.session_id(), Some("session-new"));
        assert_eq!(app.projection.items().len(), 1);
        assert_eq!(app.projection.items()[0].text, "new transcript");
        assert_ne!(app.projection.items()[0].key, old_key);
        assert!(app.selected_transcript_key.is_none());
        assert!(!app.transcript_item_interactions.contains_key(&old_key));
        assert!(
            app.transcript_item_interactions
                .contains_key(&app.projection.items()[0].key)
        );
        assert!(!app.stream_requesting);
        assert!(!app.interrupt_pending);
        assert!(app.live_context_usage().is_none());
        assert!(!app.context_usage_refresh_pending);
        assert!(!app.context_usage_refresh_dirty);
        assert!(
            !app.context_usage_is_baseline(),
            "the real assistant envelope that opened the new session already carries conversation context"
        );
        assert_eq!(app.shell_phase(), ShellPhase::Conversation);
        assert!(!app.minimal_welcome_pending());
        assert_eq!(
            app.active_tasks.get("background-task").map(String::as_str),
            Some("still running"),
            "fixed /clear preserves backend-owned background tasks"
        );
    }

