    #[test]
    fn held_ctrl_c_repeat_interrupts_once_without_quitting_the_tui() {
        let mut app = app();
        app.stream_requesting = true;
        let press = KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL);
        let mut repeat = press;
        repeat.kind = KeyEventKind::Repeat;

        assert_eq!(
            app.handle_event(Event::Key(press)),
            vec![HostAction::Interrupt]
        );
        assert!(app.interrupt_pending);
        assert!(!app.should_quit);

        assert!(app.handle_event(Event::Key(repeat)).is_empty());
        assert!(app.interrupt_pending);
        assert!(
            !app.should_quit,
            "a key-repeat report is not a second deliberate Ctrl-C press"
        );
    }

