    #[test]
    fn external_editor_chord_swallows_invalid_completion_and_expires_after_one_second() {
        let mut app = app();
        app.composer.set_text("draft");
        app.composer.set_cursor("draft".len());
        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('x'),
            KeyModifiers::CONTROL,
        )));
        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('z'),
            KeyModifiers::NONE,
        )));
        assert_eq!(app.composer.text(), "draft");
        assert!(app.take_external_editor_request().is_none());
        assert!(!app.action_registry.has_pending_chord());

        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('x'),
            KeyModifiers::CONTROL,
        )));
        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('q'),
            KeyModifiers::CONTROL,
        )));
        assert!(
            !app.should_quit && app.pending_action_confirmation.is_none(),
            "the historical chord interceptor also swallows global quit keys"
        );

        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('x'),
            KeyModifiers::CONTROL,
        )));
        app.action_registry.expire_pending_chord();
        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('z'),
            KeyModifiers::NONE,
        )));
        assert_eq!(
            app.composer.text(),
            "draftz",
            "the first key after timeout is processed normally"
        );
    }

    #[test]
    fn external_editor_outcomes_preserve_failure_and_make_success_undoable() {
        let mut app = app();
        app.composer.set_text("original");
        app.composer.set_cursor(4);
        app.complete_external_editor(
            "original",
            PromptEditOutcome::Failed("Vim exited with code 3".to_string()),
        );
        assert_eq!(app.composer.text(), "original");
        assert_eq!(app.composer.cursor(), 4);
        assert_eq!(app.status, "Vim exited with code 3");

        app.complete_external_editor("original", PromptEditOutcome::Content("edited".to_string()));
        assert_eq!(app.composer.text(), "edited");
        assert_eq!(app.composer.cursor(), "edited".len());
        assert!(
            app.composer.undo(),
            "historical prompt editing records the replaced draft for undo"
        );
        assert_eq!(app.composer.text(), "original");
        assert_eq!(app.composer.cursor(), 4);
    }

