    #[test]
    fn setup_handoff_gates_end_session_and_the_first_visible_presentation() {
        let mut app = TuiApp::new(&json!({}), InitialSessionRequest::New, None);
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initializing;
        assert!(!app.shutdown_end_session_allowed());
        assert!(!app.initial_presentation_ready());

        app.dialog = Some(RequestDialog::Setup(SetupDialog {
            request_id: "setup-visible".to_string(),
            title: "Setup".to_string(),
            body: Vec::new(),
            kind: SetupDialogKind::OnboardingPreflight,
            choices: Vec::new(),
            selected: 0,
            links: Vec::new(),
            multi_selected: Vec::new(),
        }));
        assert!(app.initial_presentation_ready());
        assert!(!app.shutdown_end_session_allowed());

        app.dialog = Some(RequestDialog::Permission {
            request_id: "permission-visible".to_string(),
            tool_name: "Read".to_string(),
            display_name: None,
            description: None,
            input: json!({}),
            suggestions: None,
            choices: Vec::new(),
            selected: 0,
        });
        assert!(app.initial_presentation_ready());
        assert!(!app.shutdown_end_session_allowed());

        app.dialog = None;
        app.oauth_browser_prompt = Some(OAuthBrowserPrompt::new_at(
            "Opening browser".to_string(),
            "Open manually".to_string(),
            "(c to copy)".to_string(),
            "https://acosmi.test/login".to_string(),
            Instant::now(),
            true,
        ));
        assert!(
            app.initial_presentation_ready(),
            "a non-modal OAuth prompt must be presentable before initialize completes"
        );
        assert!(!app.shutdown_end_session_allowed());

        app.oauth_browser_prompt = None;
        app.dialog = None;
        app.fatal = Some("setup stopped".to_string());
        assert!(app.initial_presentation_ready());
        assert!(!app.shutdown_end_session_allowed());

        app.fatal = None;
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;
        assert!(app.initial_presentation_ready());
        assert!(app.shutdown_end_session_allowed());
    }

