    #[test]
    fn renderer_owned_setup_copy_follows_default_and_selected_language_without_mutating_authority_copy()
     {
        assert_eq!(UiLanguage::default(), UiLanguage::ZhCn);
        let external = with_fields(
            setup_base("external_crabcode_md"),
            json!({
                "title":"Authority title",
                "body":["Authority body"],
                "include_paths":["/outside/CRABCODE.md"],
                "security_url":"https://docs.test/security"
            }),
        );
        let pending = setup_pending(external);

        let RequestDialog::Setup(zh_cn) =
            setup_dialog_from_pending(&pending).expect("default Chinese setup dialog")
        else {
            panic!("external instructions dialog expected")
        };
        assert_eq!(zh_cn.title, "Authority title");
        assert_eq!(
            zh_cn.body,
            vec![
                "Authority body".to_string(),
                "外部指令 1：/outside/CRABCODE.md".to_string()
            ]
        );
        assert_eq!(
            zh_cn
                .choices
                .iter()
                .map(|choice| choice.label.as_str())
                .collect::<Vec<_>>(),
            vec!["允许外部指令文件", "拒绝外部指令文件"]
        );
        assert_eq!(zh_cn.links[0].label, "安全文档");
        assert_eq!(zh_cn.links[0].url, "https://docs.test/security");

        let RequestDialog::Setup(en_us) = setup_dialog_from_pending_with_renderer_context(
            &pending,
            Some(CrabCodeThemeKind::Dark),
            Some(false),
            UiLanguage::EnUs,
        )
        .expect("English setup dialog") else {
            panic!("external instructions dialog expected")
        };
        assert_eq!(en_us.title, "Authority title");
        assert_eq!(
            en_us.body,
            vec![
                "Authority body".to_string(),
                "External instruction 1: /outside/CRABCODE.md".to_string()
            ]
        );
        assert_eq!(
            en_us
                .choices
                .iter()
                .map(|choice| choice.label.as_str())
                .collect::<Vec<_>>(),
            vec![
                "Allow external instruction files",
                "Deny external instruction files"
            ]
        );
        assert_eq!(en_us.links[0].label, "Security documentation");
        assert_eq!(en_us.links[0].url, "https://docs.test/security");
    }

    #[test]
    fn onboarding_language_switch_localizes_only_renderer_owned_serial_successor_copy() {
        let workspace = tempfile::tempdir().expect("workspace");
        let canonical = std::fs::canonicalize(workspace.path()).expect("canonical workspace");
        let mut app = contextualized_setup_app(&canonical);
        let language = with_fields(
            setup_base("onboarding"),
            json!({
                "stage":"language",
                "title":"Choose language",
                "body":["Authority language body"],
                "options":[
                    {"value":"zh-CN","label":"中文（简体）"},
                    {"value":"en-US","label":"English"}
                ]
            }),
        );
        assert!(
            app.handle_setup_control_opened(setup_pending_with_id("language", language))
                .is_empty()
        );
        assert!(
            app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)))
                .is_empty()
        );
        let actions = app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::NONE,
        )));
        let [action @ HostAction::RespondStartupInteraction { response, .. }] = actions.as_slice()
        else {
            panic!("one language response expected")
        };
        assert_eq!(response["locale"], "en-US");
        assert_eq!(app.renderer_ui_language, UiLanguage::EnUs);
        app.action_admitted(action);
        assert!(
            app.dialog.is_none(),
            "the admitted setup response must release the exclusive dialog before its successor"
        );

        let security = with_fields(
            setup_base("onboarding"),
            json!({
                "stage":"security",
                "title":"权威标题",
                "body":["权威正文"],
                "security_url":"https://docs.test/security"
            }),
        );
        assert!(
            app.handle_setup_control_opened(setup_pending_with_id("security", security))
                .is_empty()
        );
        let Some(RequestDialog::Setup(dialog)) = app.dialog.as_ref() else {
            panic!("serial security setup dialog expected")
        };
        assert_eq!(dialog.title, "权威标题");
        assert_eq!(dialog.body, vec!["权威正文"]);
        assert_eq!(dialog.choices[0].label, "Continue");
        assert_eq!(dialog.links[0].label, "Security documentation");
        assert_eq!(dialog.links[0].url, "https://docs.test/security");
    }

