    #[test]
    fn model_argument_forms_preserve_fixed_help_info_and_backend_owned_alias_semantics() {
        let mut app = app();
        app.handle_runtime_event(raw(
            0,
            json!({
                "type":"system",
                "subtype":"init",
                "apiKeySource":"none",
                "crab_code_version":"1.0.0",
                "cwd":"/workspace",
                "tools":[],
                "mcp_servers":[],
                "model":"m",
                "permissionMode":"default",
                "slash_commands":[],
                "output_style":"default",
                "skills":[],
                "plugins":[],
                "uuid":"init-model-arguments",
                "session_id":"30000000-0000-4000-8000-000000000001"
            }),
            EnvelopeClass::System(crate::sdk_runtime::SystemSubtype::Init),
        ));

        for arg in MODEL_HELP_ARGS {
            assert_eq!(
                app.handle_local_command(&format!("/model {arg}")),
                Some(Vec::new()),
                "fixed help argument {arg} must remain renderer-local"
            );
            assert!(
                app.status.contains("/model [modelName]"),
                "help argument {arg} returned unexpected status: {}",
                app.status
            );
        }
        for arg in MODEL_INFO_ARGS {
            assert_eq!(
                app.handle_local_command(&format!("/model {arg}")),
                Some(Vec::new()),
                "fixed info argument {arg} must not be sent as a model id"
            );
            assert_eq!(app.status, "Current model: Model M");
        }

        for model in ["best", "planmode", "BEST", "PlanMode[1m]", "MiXeD/Model"] {
            assert_eq!(
                app.handle_local_command(&format!("/model {model}")),
                Some(vec![HostAction::SendControl {
                    request: json!({"subtype":"set_model","model":model}),
                    purpose: OutboundPurpose::SetModel,
                }]),
                "the renderer must preserve {model:?}; alias and custom-model resolution belong to the backend"
            );
        }
        assert_eq!(
            app.handle_local_command("/model info"),
            Some(vec![HostAction::SendControl {
                request: json!({"subtype":"set_model","model":"info"}),
                purpose: OutboundPurpose::SetModel,
            }]),
            "the literal `info` was not a fixed COMMON_INFO_ARGS member"
        );
        assert_eq!(
            app.handle_local_command("/model HELP"),
            Some(vec![HostAction::SendControl {
                request: json!({"subtype":"set_model","model":"HELP"}),
                purpose: OutboundPurpose::SetModel,
            }]),
            "fixed common argument matching was case-sensitive"
        );
    }

