    #[test]
    fn attachment_selection_cycles_removes_and_exits_without_backend_actions() {
        let mut app = app();
        app.attachments = vec![
            composer_image("one.png"),
            composer_image("two.png"),
            composer_image("three.png"),
        ];
        app.composer.set_text("keep this caption");
        app.composer.set_cursor(app.composer.text().len());
        assert!(
            app.handle_event(Event::Key(
                KeyEvent::new(KeyCode::Down, KeyModifiers::NONE,)
            ))
            .is_empty()
        );
        assert_eq!(app.composer_image_preview, Some(2));
        assert!(app.composer_attachment_navigation_active);
        assert_eq!(app.composer.text(), "keep this caption");

        assert!(
            app.handle_event(Event::Key(KeyEvent::new(
                KeyCode::Right,
                KeyModifiers::NONE,
            )))
            .is_empty()
        );
        assert_eq!(app.composer_image_preview, Some(0));
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Left, KeyModifiers::NONE)));
        assert_eq!(app.composer_image_preview, Some(2));

        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Delete,
            KeyModifiers::NONE,
        )));
        assert_eq!(
            app.attachments
                .iter()
                .map(|image| image.filename.as_str())
                .collect::<Vec<_>>(),
            vec!["one.png", "two.png"]
        );
        assert_eq!(app.composer_image_preview, Some(1));
        assert!(app.composer_attachment_navigation_active);

        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)));
        assert_eq!(app.composer_image_preview, None);
        assert!(!app.composer_attachment_navigation_active);

        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)));
        assert_eq!(app.composer_image_preview, Some(1));
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)));
        assert_eq!(app.composer_image_preview, None);

        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)));
        assert_eq!(app.composer_image_preview, Some(1));
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Up, KeyModifiers::NONE)));
        assert_eq!(app.composer_image_preview, None);
        assert!(!app.composer_attachment_navigation_active);
    }

    #[test]
    fn attachment_backspace_edits_text_before_removing_the_last_image() {
        let mut backspace = app();
        backspace.attachments.push(composer_image("one.png"));
        backspace.composer.set_text("x");
        backspace.composer.set_cursor(1);

        backspace.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Backspace,
            KeyModifiers::NONE,
        )));
        assert!(backspace.composer.is_empty());
        assert_eq!(
            backspace.attachments.len(),
            1,
            "non-empty composer text owns Backspace first"
        );

        backspace.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Backspace,
            KeyModifiers::NONE,
        )));
        assert!(backspace.attachments.is_empty());
        assert!(backspace.composer_image_preview.is_none());

        let mut delete = app();
        delete.attachments.push(composer_image("delete.png"));
        delete.composer.set_text("xy");
        delete.composer.set_cursor(0);
        delete.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Delete,
            KeyModifiers::NONE,
        )));
        assert_eq!(delete.composer.text(), "y");
        assert_eq!(
            delete.attachments.len(),
            1,
            "non-empty composer text owns Delete first"
        );

        delete.composer.set_text("");
        delete.composer.set_cursor(0);
        delete.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Delete,
            KeyModifiers::NONE,
        )));
        assert!(delete.attachments.is_empty());
    }

    #[test]
    fn input_paste_image_preferred_over_caption_and_send_waits_for_probe() {
        let mut app = app();
        let (sender, receiver) = std::sync::mpsc::sync_channel(1);
        app.deferred_input_jobs
            .push_back(DeferredInputJob::Clipboard(DeferredClipboardProbe {
                receiver,
                insert_at: 0,
                started_at: Instant::now(),
                source: ClipboardProbeSource::ClipboardKey,
            }));
        sender
            .send(Ok(ClipboardCapture {
                text: Some("caption must not be inserted".to_string()),
                image: Some(LoadedComposerImage {
                    filename: "clipboard.png".to_string(),
                    data_url: "data:image/png;base64,AA==".to_string(),
                    mime: "image/png".to_string(),
                    width: 1,
                    height: 1,
                    encoded_bytes: 1,
                    preview_identity: crate::crabcode_image_overlay::next_image_identity(),
                    terminal_preview: None,
                }),
                image_error: None,
                probe_dropped: false,
            }))
            .expect("deliver clipboard fixture");

        assert!(
            app.submit_composer().is_empty(),
            "send must wait until image-vs-caption precedence is known"
        );
        assert!(app.submit_after_deferred_input);
        let actions = app.poll_deferred_input();
        let [HostAction::SendUser { content, priority }] = actions.as_slice() else {
            panic!("deferred clipboard send expected");
        };
        assert_eq!(priority, &None);
        assert_eq!(
            content,
            &json!([{
                "type":"image",
                "source":{"type":"base64","media_type":"image/png","data":"AA=="}
            }])
        );
        assert!(app.composer.is_empty());
        assert_eq!(app.attachments.len(), 0, "send snapshots then clears");
        assert!(
            app.pending_composer_submission
                .as_ref()
                .is_some_and(
                    |submission| submission.text.is_empty() && submission.attachments.len() == 1
                ),
            "two-phase delivery must retain the exact attachment snapshot"
        );
    }

