    #[test]
    fn initialize_commands_preserve_metadata_and_leave_execution_to_the_backend_slash_resolver() {
        let mut app = TuiApp::new(
            &json!({
                "commands": [
                    {
                        "name": "review",
                        "description": "Review a change",
                        "argumentHint": "<path>"
                    },
                    {
                        "name": "reload",
                        "description": "Reload context",
                        "argumentHint": ""
                    }
                ]
            }),
            InitialSessionRequest::New,
            None,
        );
        app.release_startup_barrier_for_test();
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;
        assert_eq!(
            app.commands,
            vec![
                SlashCommandChoice {
                    name: "review".to_string(),
                    description: "Review a change".to_string(),
                    argument_hint: "<path>".to_string(),
                    hidden: false,
                    builtin: false,
                },
                SlashCommandChoice {
                    name: "reload".to_string(),
                    description: "Reload context".to_string(),
                    argument_hint: String::new(),
                    hidden: false,
                    builtin: false,
                }
            ]
        );

        app.handle_event(Event::Paste("/reload".to_string()));
        assert_eq!(app.visible_command_suggestions().count(), 2);
        assert_eq!(
            app.visible_command_suggestions()
                .next()
                .map(|(_, command)| command.name.as_str()),
            Some("reload"),
            "the fixed historical suggestion order puts an exact name before a prefix sibling"
        );
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)));
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)));
        assert_eq!(
            app.composer.text(),
            "/reload-plugins ",
            "Down advances from the initially selected exact match to its prefix sibling"
        );

        app.composer.set_text("/future-command exact");
        app.composer.set_cursor(app.composer.text().len());
        let actions = app.submit_composer();
        assert_eq!(
            actions,
            vec![HostAction::SendUser {
                content: Value::String("/future-command exact".to_string()),
                priority: None
            }],
            "the renderer must not invent an execution result for an unknown slash name; the existing backend slash resolver rejects or executes it"
        );
    }

    #[test]
    fn unavailable_local_tokens_fail_closed_without_changing_the_viewport() {
        let mut app = TuiApp::new(&json!({}), InitialSessionRequest::New, None);
        app.scroll.set_offset(19, 100, 10);
        let original_scroll = app.scroll;

        for command in KNOWN_UNAVAILABLE_LOCAL_COMMANDS.tokens() {
            let command = format!("/{command}");
            let actions = app
                .handle_local_command(&command)
                .unwrap_or_else(|| panic!("{command} must be stopped by the renderer"));
            assert!(
                actions.is_empty(),
                "{command} must not acquire backend authority"
            );
            assert!(
                app.status.contains("命令未发送"),
                "{command}: {}",
                app.status
            );
            assert!(
                !app.status.contains("command was not sent"),
                "{command}: {}",
                app.status
            );
        }
        let _ = app
            .handle_local_command("/voice")
            .expect("/voice must fail closed");
        assert_eq!(app.status, "/voice 在纯 TUI 中不可用；命令未发送");

        app.renderer_ui_language = UiLanguage::EnUs;
        let _ = app
            .handle_local_command("/voice")
            .expect("/voice must fail closed");
        assert_eq!(
            app.status,
            "/voice is unavailable in the pure TUI; command was not sent"
        );
        assert_eq!(
            app.scroll, original_scroll,
            "/clear must not masquerade as the historical new-session transition by resetting only the viewport"
        );
    }

    #[test]
    fn gated_runtime_tokens_fail_closed_with_reason_specific_copy() {
        let cases = [
            (
                "/files",
                "/files 仅特定构建提供，当前构建未启用；命令未发送",
                "/files is only available in specific builds; command was not sent",
            ),
            (
                "/advisor",
                "/advisor 未对当前账户、订阅或实验放行；命令未发送",
                "/advisor is not enabled for this account, subscription, or experiment; command was not sent",
            ),
            (
                "/terminal-setup",
                "/terminal-setup 在当前终端环境不适用；命令未发送",
                "/terminal-setup does not apply to this terminal environment; command was not sent",
            ),
            (
                "/compact",
                "/compact 在当前会话未启用；命令未发送",
                "/compact is not enabled in this session; command was not sent",
            ),
            (
                "/voice",
                "/voice 在纯 TUI 中不可用；命令未发送",
                "/voice is unavailable in the pure TUI; command was not sent",
            ),
        ];
        for (command, chinese, english) in cases {
            let mut app = TuiApp::new(&json!({}), InitialSessionRequest::New, None);
            let actions = app
                .handle_local_command(command)
                .unwrap_or_else(|| panic!("{command} must be stopped by the renderer"));
            assert!(
                actions.is_empty(),
                "{command} must not acquire backend authority"
            );
            assert_eq!(app.status, chinese);
            app.renderer_ui_language = UiLanguage::EnUs;
            let actions = app
                .handle_local_command(command)
                .unwrap_or_else(|| panic!("{command} must be stopped by the renderer"));
            assert!(
                actions.is_empty(),
                "{command} must not acquire backend authority"
            );
            assert_eq!(app.status, english);
        }

        let mut app = TuiApp::new(&json!({}), InitialSessionRequest::New, None);
        for (token, _) in GATED_RUNTIME_COMMAND_TOKENS {
            let command = format!("/{token}");
            let actions = app
                .handle_local_command(&command)
                .unwrap_or_else(|| panic!("{command} must be stopped by the renderer"));
            assert!(
                actions.is_empty(),
                "{command} must not acquire backend authority"
            );
            assert!(
                app.status.contains("命令未发送"),
                "{command}: {}",
                app.status
            );
        }
    }

    #[test]
    fn localized_link_failure_chrome_preserves_target_and_reason() {
        let target = LinkTarget::File(Arc::from(Path::new("/tmp/证据/evidence.txt")));
        let reason = "OS-DYNAMIC-拒绝 / errno=13";
        let mut app = TuiApp::new(&json!({}), InitialSessionRequest::New, None);

        app.link_open_failed(&target, reason);
        assert_eq!(app.status, "文件处理程序不可用 · 目标已显示在浮层中");
        let overlay = app.overlay.as_ref().expect("Chinese link failure overlay");
        assert_eq!(overlay.title, "文件处理程序不可用");
        assert_eq!(
            overlay.body,
            "无法打开所选的文件（OS-DYNAMIC-拒绝 / errno=13）。\n\n目标：\n/tmp/证据/evidence.txt"
        );

        app.renderer_ui_language = UiLanguage::EnUs;
        app.link_open_failed(&target, reason);
        assert_eq!(
            app.status,
            "file handler unavailable · target shown in overlay"
        );
        let overlay = app.overlay.as_ref().expect("English link failure overlay");
        assert_eq!(overlay.title, "file handler unavailable");
        assert_eq!(
            overlay.body,
            "Could not open the selected file (OS-DYNAMIC-拒绝 / errno=13).\n\nTarget:\n/tmp/证据/evidence.txt"
        );
    }

    #[test]
    fn local_command_sets_are_unique_disjoint_and_fail_closed() {
        use std::collections::BTreeSet;

        let retained = [
            "bug",
            "color",
            "context",
            "exit",
            "feedback",
            "help",
            "login",
            "logout",
            "marketplace",
            "mcp",
            "model",
            "plugin",
            "plugins",
            "quit",
            "reload-plugins",
            "rename",
            "usage",
            "btw",
        ]
        .into_iter()
        .collect::<BTreeSet<_>>();
        let expected_unavailable = UNAVAILABLE_LOCAL_COMMAND_TOKENS
            .iter()
            .map(|token| format!("/{token}"))
            .collect::<BTreeSet<_>>();
        let actual_unavailable = KNOWN_UNAVAILABLE_LOCAL_COMMANDS
            .tokens()
            .map(|token| format!("/{token}"))
            .collect::<BTreeSet<_>>();
        assert_eq!(
            actual_unavailable, expected_unavailable,
            "the fail-closed guard must expose exactly the closed pure-TUI deny set"
        );
        assert_eq!(
            expected_unavailable.len(),
            UNAVAILABLE_LOCAL_COMMAND_TOKENS.len(),
            "unavailable command tokens must be unique"
        );

        let completed_local = FIXED_LOCAL_COMMAND_COMPLETIONS
            .iter()
            .map(|(name, _, _)| *name)
            .filter(|name| *name != "find")
            .collect::<BTreeSet<_>>();
        assert_eq!(
            completed_local, retained,
            "native command completions must retain the reviewed local command set"
        );
        assert!(
            completed_local
                .iter()
                .all(|token| !UNAVAILABLE_LOCAL_COMMAND_TOKENS.contains(token)),
            "implemented and unavailable local command sets must be disjoint"
        );
        assert!(
            GATED_RUNTIME_COMMAND_TOKENS
                .iter()
                .all(|(token, _)| !UNAVAILABLE_LOCAL_COMMAND_TOKENS.contains(token)),
            "gated runtime tokens must be disjoint from the unported set"
        );
        assert!(
            completed_local
                .iter()
                .all(|token| { gated_runtime_command_reason(token).is_none() }),
            "implemented local commands must not collide with gated runtime tokens"
        );
        for boundary_token in [
            "chrome",
            "desktop",
            "mobile",
            "remote",
            "bridge-kick",
            "office",
            "rc",
            "remote-control",
            "remote-status",
        ] {
            assert!(
                UNAVAILABLE_LOCAL_COMMAND_TOKENS.contains(&boundary_token),
                "non-TUI boundary token {boundary_token} must fail closed"
            );
        }
        for gated_token in [
            "compact-history",
            "init",
            "insights",
            "local-models",
            "pr-comments",
            "proxy",
            "review",
            "security-review",
            "statusline",
            "vision",
            "version",
        ] {
            assert!(
                gated_runtime_command_reason(gated_token).is_some(),
                "runtime-catalog boundary token {gated_token} must remain gated"
            );
            assert!(
                !UNAVAILABLE_LOCAL_COMMAND_TOKENS.contains(&gated_token),
                "gated runtime token {gated_token} must not remain in the unported set"
            );
        }
    }

