    #[test]
    fn btw_uses_the_existing_side_question_control_with_runtime_first_wins() {
        let mut app = app();
        assert_eq!(
            app.handle_local_command("/btw \u{feff}why now?\u{2028}"),
            Some(vec![HostAction::SendControl {
                request: json!({
                    "subtype": "side_question",
                    "question": "why now?"
                }),
                purpose: OutboundPurpose::SideQuestion {
                    question: "why now?".to_string(),
                },
            }])
        );
        assert_eq!(
            app.take_transcript_view_actions(),
            vec![crate::agent_view::TranscriptViewAction::StartSideQuestion {
                question: "why now?".to_string(),
            }]
        );

        assert_eq!(
            app.handle_local_command("/btw \u{feff}\u{2028}"),
            Some(Vec::new())
        );
        assert_eq!(app.status, "Usage: /btw <your question>");
        assert!(app.take_transcript_view_actions().is_empty());

        let mut collision = TuiApp::new(
            &json!({
                "commands": [{
                    "name": "btw",
                    "description": "Runtime-owned command",
                    "argumentHint": "<runtime>"
                }]
            }),
            InitialSessionRequest::New,
            None,
        );
        assert_eq!(
            collision.handle_local_command("/btw runtime owns this"),
            None,
            "an exact initialize-catalog name keeps the whole invocation on the existing backend slash resolver"
        );
        assert!(collision.take_transcript_view_actions().is_empty());
    }

    #[test]
    fn side_question_control_response_projects_only_the_existing_response_shape() {
        let mut answered = app();
        assert!(
            answered
                .apply_control_response(
                    OutboundPurpose::SideQuestion {
                        question: "q".to_string(),
                    },
                    true,
                    json!({"response": {"response": "answer"}}),
                    1,
                )
                .is_empty()
        );
        assert_eq!(
            answered.take_transcript_view_actions(),
            vec![
                crate::agent_view::TranscriptViewAction::FinishSideQuestion {
                    question: "q".to_string(),
                    result: Ok("answer".to_string()),
                }
            ]
        );

        let mut failed = app();
        assert!(
            failed
                .apply_control_response(
                    OutboundPurpose::SideQuestion {
                        question: "q".to_string(),
                    },
                    false,
                    json!({"error": "side fork failed"}),
                    2,
                )
                .is_empty()
        );
        assert_eq!(
            failed.take_transcript_view_actions(),
            vec![
                crate::agent_view::TranscriptViewAction::FinishSideQuestion {
                    question: "q".to_string(),
                    result: Err("side fork failed".to_string()),
                }
            ]
        );

        for (response, request_id) in [(Value::Null, 3), (Value::String(String::new()), 4)] {
            let mut empty = app();
            assert!(
                empty
                    .apply_control_response(
                        OutboundPurpose::SideQuestion {
                            question: "q".to_string(),
                        },
                        true,
                        json!({"response": {"response": response}}),
                        request_id,
                    )
                    .is_empty()
            );
            assert_eq!(
                empty.take_transcript_view_actions(),
                vec![
                    crate::agent_view::TranscriptViewAction::FinishSideQuestion {
                        question: "q".to_string(),
                        result: Err("No response received".to_string()),
                    }
                ],
                "the fixed historical renderer maps a falsey side-question response to its explicit no-response error"
            );
            assert!(empty.fatal.is_none());
        }

        let mut delivery_failed = app();
        let outbound = HostAction::SendControl {
            request: json!({"subtype": "side_question", "question": "q"}),
            purpose: OutboundPurpose::SideQuestion {
                question: "q".to_string(),
            },
        };
        delivery_failed.action_failed(&outbound, "stdin closed");
        assert_eq!(
            delivery_failed.take_transcript_view_actions(),
            vec![
                crate::agent_view::TranscriptViewAction::FinishSideQuestion {
                    question: "q".to_string(),
                    result: Err("Runtime action failed: stdin closed".to_string()),
                }
            ]
        );

        let mut malformed = app();
        malformed.apply_control_response(
            OutboundPurpose::SideQuestion {
                question: "q".to_string(),
            },
            true,
            json!({"response": {"answer": "guessed alias"}}),
            5,
        );
        assert!(malformed.fatal.as_deref().is_some_and(|reason| {
            reason.contains("side_question response omitted string-or-null response")
        }));
        assert!(
            malformed.take_transcript_view_actions().is_empty(),
            "an incompatible backend response cannot be guessed into renderer state"
        );
    }

    #[test]
