    #[test]
    fn fixed_history_search_actions_next_accept_cancel_and_execute_use_existing_boundaries() {
        let mut execute = app();
        execute.remember_composer_submission("deploy older");
        execute.remember_composer_submission("deploy newest");
        execute.composer.set_text("deploy");
        execute.composer.set_cursor("deploy".len());

        assert!(
            execute
                .handle_event(Event::Key(KeyEvent::new(
                    KeyCode::Char('r'),
                    KeyModifiers::CONTROL,
                )))
                .is_empty()
        );
        assert_eq!(
            execute
                .history_search
                .as_ref()
                .and_then(HistorySearchState::selected_entry)
                .map(|entry| entry.display.as_str()),
            Some("deploy newest")
        );
        assert!(
            execute
                .handle_event(Event::Key(KeyEvent::new(
                    KeyCode::Char('r'),
                    KeyModifiers::CONTROL,
                )))
                .is_empty()
        );
        assert_eq!(
            execute
                .history_search
                .as_ref()
                .and_then(HistorySearchState::selected_entry)
                .map(|entry| entry.display.as_str()),
            Some("deploy older"),
            "historySearch:next advances toward the next older matching prompt"
        );
        assert_eq!(
            execute.handle_event(Event::Key(KeyEvent::new(
                KeyCode::Enter,
                KeyModifiers::NONE,
            ))),
            vec![HostAction::SendUser {
                content: Value::String("deploy older".to_string()),
                priority: None,
            }],
            "historySearch:execute reuses the existing direct SendUser boundary"
        );
        assert!(execute.history_search.is_none());

        let mut accept = app();
        accept.remember_composer_submission("deploy selected");
        accept.composer.set_text("deploy");
        accept.composer.set_cursor("deploy".len());
        accept.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('r'),
            KeyModifiers::CONTROL,
        )));
        assert!(
            accept
                .handle_event(Event::Key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)))
                .is_empty()
        );
        assert!(accept.history_search.is_none());
        assert_eq!(accept.composer.text(), "deploy selected");

        let mut cancel = app();
        cancel.remember_composer_submission("draft from history");
        cancel.composer.set_text("draft");
        cancel.composer.set_cursor(2);
        cancel.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Char('r'),
            KeyModifiers::CONTROL,
        )));
        assert!(
            cancel
                .handle_event(Event::Key(KeyEvent::new(
                    KeyCode::Char('c'),
                    KeyModifiers::CONTROL,
                )))
                .is_empty()
        );
        assert!(cancel.history_search.is_none());
        assert_eq!(cancel.composer.text(), "draft");
        assert_eq!(cancel.composer.cursor(), 2);
    }

    #[test]
