    #[test]
    fn global_search_enter_requests_only_a_canonical_one_based_editor_handoff() {
        let workspace = tempfile::tempdir().expect("workspace");
        std::fs::create_dir_all(workspace.path().join("src")).expect("mkdir");
        let source = workspace.path().join("src/lib.rs");
        std::fs::write(&source, "first\nexact Needle match\nthird\n").expect("write");
        let canonical = std::fs::canonicalize(workspace.path()).expect("canonical workspace");
        let mut app = app();
        app.setup_source_cwd = Some(canonical);
        app.composer.set_text("preserved draft");
        app.composer.set_cursor(4);

        assert!(
            app.execute_interaction_action(TuiActionId::OpenGlobalSearch)
                .is_empty()
        );
        for character in "needle".chars() {
            assert!(
                app.handle_event(Event::Key(KeyEvent::new(
                    KeyCode::Char(character),
                    KeyModifiers::NONE,
                )))
                .is_empty()
            );
        }
        settle_workspace_search(&mut app);
        assert!(
            app.handle_event(Event::Key(KeyEvent::new(
                KeyCode::Enter,
                KeyModifiers::NONE,
            )))
            .is_empty()
        );
        let request = app
            .take_external_file_open_request()
            .expect("renderer-private file handoff");
        assert_eq!(
            request.path,
            std::fs::canonicalize(source).expect("canonical source")
        );
        assert_eq!(request.line, Some(2));
        assert_eq!(app.composer.text(), "preserved draft");
        assert_eq!(app.composer.cursor(), 4);
        assert!(app.workspace_search.is_none());
    }

    #[test]
    fn help_v2_tabs_partition_known_builtin_and_unclassified_runtime_commands() {
        let mut app = app();
        app.completion_commands = vec![
            SlashCommandChoice {
                name: "model".to_string(),
                description: "Switch model".to_string(),
                argument_hint: "[model]".to_string(),
                hidden: false,
                builtin: true,
            },
            SlashCommandChoice {
                name: "project-workflow".to_string(),
                description: "Project-local workflow".to_string(),
                argument_hint: String::new(),
                hidden: false,
                builtin: false,
            },
        ];
        app.open_help();
        let overlay = app.overlay.as_ref().expect("help overlay");
        assert_eq!(overlay.window.tab_count, 3);
        assert_eq!(
            overlay
                .help_tabs
                .iter()
                .map(|tab| tab.label)
                .collect::<Vec<_>>(),
            ["general", "commands", "custom-commands"]
        );
        assert!(overlay.help_tabs[1].body.contains("/model [model]"));
        assert!(!overlay.help_tabs[1].body.contains("project-workflow"));
        assert!(overlay.help_tabs[2].body.contains("/project-workflow"));

        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)));
        assert_eq!(
            app.overlay
                .as_ref()
                .map(|overlay| overlay.window.active_tab),
            Some(1)
        );
        app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::BackTab,
            KeyModifiers::SHIFT,
        )));
        assert_eq!(
            app.overlay
                .as_ref()
                .map(|overlay| overlay.window.active_tab),
            Some(0)
        );
    }

    #[test]
    fn catalog_metadata_hides_discovery_without_revoking_typed_dispatch_and_partitions_help() {
        let mut app = TuiApp::new(
            &json!({"commands":[
                {
                    "name":"hidden-builtin",
                    "description":"Typed compatibility command",
                    "argumentHint":"",
                    "hidden":true,
                    "builtin":true
                },
                {
                    "name":"visible-builtin",
                    "description":"Visible built-in command",
                    "argumentHint":"<value>",
                    "builtin":true
                },
                {
                    "name":"workspace-command",
                    "description":"Workspace command",
                    "argumentHint":""
                }
            ]}),
            InitialSessionRequest::New,
            None,
        );
        app.release_startup_barrier_for_test();
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;

        assert!(app.runtime_catalog_contains("/hidden-builtin"));
        assert!(
            !app.completion_commands
                .iter()
                .any(|command| command.name == "hidden-builtin")
        );
        app.composer.set_text("/hidden-builtin exact");
        app.composer.set_cursor(app.composer.text().len());
        assert_eq!(
            app.submit_composer(),
            vec![HostAction::SendUser {
                content: Value::String("/hidden-builtin exact".to_string()),
                priority: None,
            }]
        );

        app.open_help();
        let help = app.overlay.as_ref().expect("help overlay");
        assert!(help.help_tabs[1].body.contains("/visible-builtin <value>"));
        assert!(!help.help_tabs[1].body.contains("hidden-builtin"));
        assert!(help.help_tabs[2].body.contains("/workspace-command"));
        assert!(!help.help_tabs[2].body.contains("visible-builtin"));
    }

    /// The producer publishes one command's alternate spellings as `hidden`
    /// rows. Discovery must collapse to a single row per command while every
    /// spelling stays typed-dispatchable, including the gated session tokens
    /// whose fail-closed copy only applies when the catalog lacks the token.
    #[test]
    fn hidden_alias_catalog_rows_collapse_discovery_without_revoking_dispatch() {
        let mut app = TuiApp::new(
            &json!({"commands":[
                {
                    "name":"clear",
                    "description":"Clear conversation history",
                    "argumentHint":"",
                    "builtin":true
                },
                {
                    "name":"new",
                    "description":"Clear conversation history",
                    "argumentHint":"",
                    "hidden":true,
                    "builtin":true
                },
                {
                    "name":"reset",
                    "description":"Clear conversation history",
                    "argumentHint":"",
                    "hidden":true,
                    "builtin":true
                }
            ]}),
            InitialSessionRequest::New,
            None,
        );
        app.release_startup_barrier_for_test();
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;

        assert_eq!(
            app.completion_commands
                .iter()
                .filter(|command| command.description == "Clear conversation history")
                .map(|command| command.name.as_str())
                .collect::<Vec<_>>(),
            vec!["clear"],
            "one command must contribute exactly one discoverable row"
        );

        for alias in ["/reset", "/new"] {
            assert!(
                app.runtime_catalog_contains(alias),
                "{alias} must stay in the unfiltered runtime catalog"
            );
        }

        app.composer.set_text("/reset");
        app.composer.set_cursor(app.composer.text().len());
        app.refresh_command_palette();
        assert!(
            app.visible_command_suggestions()
                .all(|(_, command)| command.name != "reset" && command.name != "new"),
            "alias spellings must never be offered as their own command"
        );

        assert_eq!(
            app.submit_composer(),
            vec![HostAction::SendUser {
                content: Value::String("/reset".to_string()),
                priority: None,
            }],
            "a hidden alias must still execute verbatim"
        );
    }

    #[test]
    fn background_catalog_refresh_atomically_updates_dispatch_palette_help_and_ack() {
        let mut app = TuiApp::new(
            &json!({"commands":[{
                "name":"old-command",
                "description":"Old command",
                "argumentHint":""
            }]}),
            InitialSessionRequest::New,
            None,
        );
        app.release_startup_barrier_for_test();
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;
        app.composer.set_text("/fresh-command");
        app.composer.set_cursor(app.composer.text().len());
        app.refresh_command_palette();
        assert!(app.command_palette.matches.is_empty());
        app.open_help();
        app.overlay.as_mut().expect("help").window.active_tab = 2;

        let request = json!({
            "subtype":CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE,
            "protocol_version":CRABCODE_TUI_COMMAND_CATALOG_PROTOCOL_VERSION,
            "commands":[
                {
                    "name":"fresh-command",
                    "description":"Fresh built-in",
                    "argumentHint":"<value>",
                    "builtin":true
                },
                {
                    "name":"hidden-command",
                    "description":"Exact dispatch only",
                    "argumentHint":"",
                    "hidden":true
                },
                {
                    "name":"mcp:tool (MCP)",
                    "description":"MCP command",
                    "argumentHint":""
                }
            ]
        });
        let actions = app.handle_runtime_event(raw(
            91,
            json!({
                "type":"control_request",
                "request_id":"catalog-refresh-1",
                "request":request.clone()
            }),
            EnvelopeClass::ControlRequest {
                request_id: "catalog-refresh-1".to_string(),
                subtype: CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE.to_string(),
            },
        ));

        assert_eq!(
            actions,
            vec![HostAction::RespondStartupInteraction {
                request_id: "catalog-refresh-1".to_string(),
                subtype: CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE.to_string(),
                response: json!({"protocol_version":1,"received":true}),
            }]
        );
        assert!(!app.runtime_catalog_contains("/old-command"));
        assert!(app.runtime_catalog_contains("/fresh-command"));
        assert!(app.runtime_catalog_contains("/hidden-command"));
        assert!(app.runtime_catalog_contains("/mcp:tool (MCP)"));
        assert!(
            app.completion_commands
                .iter()
                .any(|command| command.name == "fresh-command")
        );
        assert!(
            !app.completion_commands
                .iter()
                .any(|command| command.name == "hidden-command")
        );
        assert!(
            app.completion_commands
                .iter()
                .any(|command| command.name == "mcp:tool (MCP)")
        );
        assert_eq!(
            app.visible_command_suggestions()
                .next()
                .map(|(_, command)| command.name.as_str()),
            Some("fresh-command")
        );
        let help = app.overlay.as_ref().expect("open Help was refreshed");
        assert_eq!(help.window.active_tab, 2, "active Help tab is preserved");
        assert!(help.help_tabs[1].body.contains("/fresh-command <value>"));
        assert!(!help.help_tabs[1].body.contains("hidden-command"));
        assert!(!help.help_tabs[2].body.contains("old-command"));
        assert!(
            app.projection
                .pending_control("catalog-refresh-1")
                .is_some()
        );

        app.action_succeeded(&actions[0]);
        assert!(
            app.projection
                .pending_control("catalog-refresh-1")
                .is_none()
        );
        app.overlay = None;
        app.composer.set_text("/hidden-command exact");
        app.composer.set_cursor(app.composer.text().len());
        assert_eq!(
            app.submit_composer(),
            vec![HostAction::SendUser {
                content: Value::String("/hidden-command exact".to_string()),
                priority: None,
            }]
        );
    }

    #[test]
    fn catalog_refresh_is_fail_closed_before_initialize_or_on_malformed_snapshot() {
        let old_commands = json!({"commands":[{
            "name":"old-command",
            "description":"Old command",
            "argumentHint":""
        }]});
        let valid_request = json!({
            "subtype":CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE,
            "protocol_version":CRABCODE_TUI_COMMAND_CATALOG_PROTOCOL_VERSION,
            "commands":[{
                "name":"fresh-command",
                "description":"Fresh command",
                "argumentHint":""
            }]
        });

        let mut pre_initialize = TuiApp::new(&old_commands, InitialSessionRequest::New, None);
        assert!(
            pre_initialize
                .handle_projection_effect(ProjectionEffect::ReverseControlOpened(PendingControl {
                    request_id: "catalog-too-early".to_string(),
                    subtype: CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE.to_string(),
                    request: valid_request,
                    raw_sequence: 1,
                }))
                .is_empty()
        );
        assert!(pre_initialize.fatal.is_some());
        assert!(pre_initialize.runtime_catalog_contains("/old-command"));
        assert!(!pre_initialize.runtime_catalog_contains("/fresh-command"));

        let mut malformed = TuiApp::new(&old_commands, InitialSessionRequest::New, None);
        malformed.release_startup_barrier_for_test();
        malformed.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;
        assert!(
            malformed
                .handle_projection_effect(ProjectionEffect::ReverseControlOpened(PendingControl {
                    request_id: "catalog-duplicate".to_string(),
                    subtype: CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE.to_string(),
                    request: json!({
                        "subtype":CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE,
                        "protocol_version":1,
                        "commands":[
                            {"name":"duplicate","description":"","argumentHint":""},
                            {"name":"duplicate","description":"","argumentHint":""}
                        ]
                    }),
                    raw_sequence: 2,
                }))
                .is_empty()
        );
        assert!(malformed.fatal.is_some());
        assert!(malformed.runtime_catalog_contains("/old-command"));
        assert!(!malformed.runtime_catalog_contains("/duplicate"));

        let mut ack_failed = TuiApp::new(&old_commands, InitialSessionRequest::New, None);
        ack_failed.action_failed(
            &HostAction::RespondStartupInteraction {
                request_id: "catalog-ack-failed".to_string(),
                subtype: CRABCODE_TUI_COMMAND_CATALOG_CHANGED_SUBTYPE.to_string(),
                response: json!({"protocol_version":1,"received":true}),
            },
            "fixture writer closed",
        );
        assert!(
            ack_failed
                .fatal
                .as_deref()
                .is_some_and(|reason| reason.contains("catalog-ack-failed")),
            "a refresh whose ACK cannot be delivered must not leave the publisher waiting forever"
        );
    }

    #[test]
    fn in_memory_history_preserves_multiline_navigation_and_exact_draft() {
        let mut app = app();
        for text in ["first", "second\nline"] {
            app.composer.set_text(text);
            app.composer.set_cursor(text.len());
            let action = app.submit_composer().remove(0);
            app.action_succeeded(&action);
        }

        let attachment = LoadedComposerImage {
            filename: "draft.png".to_string(),
            data_url: "data:image/png;base64,AA==".to_string(),
            mime: "image/png".to_string(),
            width: 1,
            height: 1,
            encoded_bytes: 1,
            preview_identity: crate::crabcode_image_overlay::next_image_identity(),
            terminal_preview: None,
        };
        app.composer.set_text("draft\nbody");
        app.composer.set_cursor(3);
        app.attachments.push(attachment.clone());

        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Up, KeyModifiers::NONE)));
        assert_eq!(app.composer.text(), "second\nline");
        assert_eq!(app.composer.cursor(), 0);
        assert!(app.attachments.is_empty());
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Up, KeyModifiers::NONE)));
        assert_eq!(app.composer.text(), "first");
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)));
        assert_eq!(app.composer.text(), "second\nline");
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE)));
        assert_eq!(app.composer.text(), "draft\nbody");
        assert_eq!(app.composer.cursor(), 3);
        assert_eq!(app.attachments, vec![attachment]);

        app.composer.set_cursor(app.composer.text().len());
        app.handle_event(Event::Key(KeyEvent::new(KeyCode::Up, KeyModifiers::NONE)));
        assert_eq!(
            app.composer.text(),
            "draft\nbody",
            "Up inside a later logical line remains an editor movement, not history navigation"
        );
        assert!(app.composer_history.selected.is_none());
    }

    #[test]
    fn direct_control_commands_emit_only_existing_sdk_shapes() {
        let mut app = app();
        let cases = [
            (
                "/mcp enable server-a",
                json!({"subtype":"mcp_toggle","serverName":"server-a","enabled":true}),
            ),
            (
                "/mcp disable server-a",
                json!({"subtype":"mcp_toggle","serverName":"server-a","enabled":false}),
            ),
            (
                "/mcp reconnect server-a",
                json!({"subtype":"mcp_reconnect","serverName":"server-a"}),
            ),
            ("/reload-plugins", json!({"subtype":"reload_plugins"})),
        ];
        for (command, expected) in cases {
            let actions = app
                .handle_local_command(command)
                .expect("recognized local direct control");
            let [HostAction::SendControl { request, .. }] = actions.as_slice() else {
                panic!("one control expected for {command}");
            };
            assert_eq!(request, &expected, "wire drift for {command}");
        }
        let spaced = app
            .handle_local_command("/mcp reconnect server with spaces")
            .expect("recognized");
        assert!(matches!(
            spaced.as_slice(),
            [HostAction::SendControl { request, .. }]
                if request["serverName"] == "server with spaces"
        ));

        for base_surface in [
            "/mcp",
            "/mcp no-redirect",
            "/mcp no-redirect ignored suffix",
            "/mcp status",
            "/mcp auth server-a",
            "/mcp clear-auth server-a",
            "/mcp toggle server-a on",
            "/mcp reconnect",
            "/mcp Enable server-a",
        ] {
            assert_eq!(
                app.handle_local_command(base_surface),
                Some(vec![HostAction::SendControl {
                    request: json!({"subtype": "mcp_status"}),
                    purpose: OutboundPurpose::McpStatus,
                }]),
                "{base_surface} must open the fixed base MCP settings surface"
            );
        }

        for (bulk, enabled) in [
            ("/mcp enable", true),
            ("/mcp enable all", true),
            ("/mcp disable", false),
            ("/mcp disable all", false),
        ] {
            assert_eq!(
                app.handle_local_command(bulk),
                Some(vec![HostAction::SendControl {
                    request: json!({"subtype": "mcp_status"}),
                    purpose: OutboundPurpose::McpStatusForBulkToggle { enabled },
                }]),
                "{bulk} must retain the fixed literal-all bulk semantics"
            );
        }

        assert!(matches!(
            app.handle_local_command("/mcp \u{feff}reconnect\u{2028}server\u{feff}name"),
            Some(actions)
                if matches!(
                    actions.as_slice(),
                    [HostAction::SendControl { request, .. }]
                        if request == &json!({
                            "subtype":"mcp_reconnect",
                            "serverName":"server name"
                        })
                )
        ));
        assert_eq!(
            app.handle_local_command("/mcp \u{0085}enable\u{0085}server"),
            Some(vec![HostAction::SendControl {
                request: json!({"subtype":"mcp_status"}),
                purpose: OutboundPurpose::McpStatus,
            }]),
            "ECMAScript /\\s+/ excludes U+0085 even though Rust Unicode whitespace includes it"
        );
    }

    #[test]
    fn historical_mcp_bulk_toggle_uses_authoritative_status_and_serial_existing_controls() {
        let mut enable_app = app();
        assert_eq!(
            enable_app.handle_local_command("/mcp enable"),
            Some(vec![HostAction::SendControl {
                request: json!({"subtype": "mcp_status"}),
                purpose: OutboundPurpose::McpStatusForBulkToggle { enabled: true },
            }])
        );
        let actions = enable_app.apply_control_response(
            OutboundPurpose::McpStatusForBulkToggle { enabled: true },
            true,
            json!({"response":{"mcpServers":[
                {"name":"connected","status":"connected"},
                {"name":"filesystem","status":"disabled"},
                {"name":"ide","status":"disabled"}
            ]}}),
            1,
        );
        assert_eq!(
            actions,
            vec![HostAction::SendControl {
                request: json!({
                    "subtype": "mcp_toggle",
                    "serverName": "filesystem",
                    "enabled": true
                }),
                purpose: OutboundPurpose::McpBulkToggleStep {
                    server_name: "filesystem".to_string(),
                    enabled: true,
                    remaining: Vec::new(),
                    completed: 0,
                },
            }],
            "enable-all selects only disabled non-IDE servers from fixed status data"
        );
        let refresh = enable_app.apply_control_response(
            OutboundPurpose::McpBulkToggleStep {
                server_name: "filesystem".to_string(),
                enabled: true,
                remaining: Vec::new(),
                completed: 0,
            },
            true,
            json!({"response": {}}),
            2,
        );
        assert_eq!(enable_app.status, "Enabled 1 MCP server(s)");
        assert_eq!(
            refresh,
            vec![HostAction::SendControl {
                request: json!({"subtype": "mcp_status"}),
                purpose: OutboundPurpose::McpStatusRefresh,
            }]
        );

        let mut disable_app = app();
        let actions = disable_app.apply_control_response(
            OutboundPurpose::McpStatusForBulkToggle { enabled: false },
            true,
            json!({"response":{"mcpServers":[
                {"name":"zeta","status":"pending"},
                {"name":"already-disabled","status":"disabled"},
                {"name":"alpha","status":"failed"},
                {"name":"ide","status":"connected"}
            ]}}),
            3,
        );
        assert!(matches!(
            actions.as_slice(),
            [HostAction::SendControl {
                request,
                purpose: OutboundPurpose::McpBulkToggleStep {
                    server_name,
                    enabled: false,
                    remaining,
                    completed: 0,
                },
            }] if request["serverName"] == "alpha"
                && server_name == "alpha"
                && remaining.as_slice() == ["zeta"]
        ));
        let actions = disable_app.apply_control_response(
            OutboundPurpose::McpBulkToggleStep {
                server_name: "alpha".to_string(),
                enabled: false,
                remaining: vec!["zeta".to_string()],
                completed: 0,
            },
            true,
            json!({"response": {}}),
            4,
        );
        assert!(matches!(
            actions.as_slice(),
            [HostAction::SendControl {
                request,
                purpose: OutboundPurpose::McpBulkToggleStep {
                    server_name,
                    enabled: false,
                    remaining,
                    completed: 1,
                },
            }] if request["serverName"] == "zeta"
                && server_name == "zeta"
                && remaining.is_empty()
        ));
    }

    #[test]
    fn mcp_status_opens_a_native_safe_projection_without_raw_json_or_ide() {
        let mut app = app();
        assert!(app.overlay.is_none());
        app.apply_control_response(
            OutboundPurpose::McpStatus,
            true,
            json!({"response":{"mcpServers":[
                {
                    "name":"dynamic-z",
                    "status":"connected",
                    "scope":"dynamic",
                    "config":{"type":"stdio","command":"node","args":["server.js"],"env":{"SECRET_ENV":"do-not-render"}},
                    "serverInfo":{"name":"fixture","version":"1.2.3"},
                    "tools":[{
                        "name":"read_file",
                        "description":"Read one file",
                        "annotations":{"readOnly":true,"destructive":false,"openWorld":false}
                    }],
                    "capabilities":{"experimental":{"fixture":true}},
                    "lifecycleStatus":"ready"
                },
                {
                    "name":"remote-user",
                    "status":"connected",
                    "scope":"user",
                    "config":{
                        "type":"http",
                        "url":"https://mcp.example.test",
                        "headers":{"Authorization":"Bearer do-not-render"}
                    },
                    "tools":[{"name":"search","annotations":{"openWorld":true}}],
                    "lifecycleStatus":"ready"
                },
                {
                    "name":"project-a",
                    "status":"disabled",
                    "scope":"project",
                    "config":{"type":"stdio","command":"project-server"},
                    "lifecycleStatus":"inactive"
                },
                {
                    "name":"ide",
                    "status":"connected",
                    "scope":"dynamic",
                    "config":{"type":"stdio","command":"ide-server"},
                    "lifecycleStatus":"ready"
                }
            ]}}),
            1,
        );

        assert!(
            app.fatal.is_none(),
            "the existing typed status shape must parse"
        );
        assert!(
            app.overlay.is_none(),
            "MCP settings must not masquerade as a raw-JSON overlay"
        );
        let settings = app.mcp_settings.as_ref().expect("native MCP surface");
        assert_eq!(
            settings
                .servers()
                .iter()
                .map(|server| server.name.as_str())
                .collect::<Vec<_>>(),
            ["project-a", "remote-user", "dynamic-z"],
            "fixed scope grouping and the IDE exclusion must be renderer-local"
        );
        assert_eq!(settings.view(), McpSettingsView::List);

        let projection_debug = format!("{settings:?}");
        assert!(!projection_debug.contains("do-not-render"));
        assert!(!projection_debug.contains("SECRET_ENV"));
        assert!(!projection_debug.contains("Authorization"));
        let dynamic = settings
            .servers()
            .iter()
            .find(|server| server.name == "dynamic-z")
            .expect("dynamic server");
        assert_eq!(
            dynamic.config,
            Some(McpServerConfigPresentation {
                transport: McpServerTransport::Stdio,
                url: None,
                command: Some("node".to_string()),
                args: vec!["server.js".to_string()],
                sdk_name: None,
            })
        );
        assert_eq!(
            dynamic.tools,
            vec![McpToolState {
                name: "read_file".to_string(),
                description: Some("Read one file".to_string()),
                annotations: McpToolAnnotationsState {
                    read_only: Some(true),
                    destructive: Some(false),
                    open_world: Some(false),
                },
            }]
        );
    }

    #[test]
    fn mcp_menu_exposes_only_actions_proven_by_the_existing_status_projection() {
        fn server(
            name: &str,
            status: &str,
            transport: McpServerTransport,
            has_tools: bool,
        ) -> McpServerState {
            McpServerState {
                name: name.to_string(),
                status: status.to_string(),
                error: None,
                server_info: None,
                config: Some(McpServerConfigPresentation {
                    transport,
                    url: matches!(
                        transport,
                        McpServerTransport::Sse
                            | McpServerTransport::Http
                            | McpServerTransport::AcosmiProxy
                    )
                    .then(|| "https://mcp.example.test".to_string()),
                    command: (transport == McpServerTransport::Stdio).then(|| "server".to_string()),
                    args: Vec::new(),
                    sdk_name: None,
                }),
                scope: Some("user".to_string()),
                lifecycle_status: Some("ready".to_string()),
                lifecycle_reason: None,
                tools: has_tools
                    .then(|| McpToolState {
                        name: "tool".to_string(),
                        description: None,
                        annotations: McpToolAnnotationsState::default(),
                    })
                    .into_iter()
                    .collect(),
            }
        }
        fn actions(settings: &McpSettingsState, server: &McpServerState) -> Vec<McpMenuAction> {
            settings
                .server_menu_options(server)
                .iter()
                .map(|option| option.action)
                .collect()
        }

        let remote_connected = server("remote", "connected", McpServerTransport::Http, true);
        let remote_needs_auth = server("remote-auth", "needs-auth", McpServerTransport::Sse, false);
        let stdio_needs_auth = server("stdio-auth", "needs-auth", McpServerTransport::Stdio, false);
        let proxy_connected = server("proxy", "connected", McpServerTransport::AcosmiProxy, true);
        let disabled = server("disabled", "disabled", McpServerTransport::Http, false);
        let settings = McpSettingsState::from_servers(
            &[
                remote_connected.clone(),
                remote_needs_auth.clone(),
                stdio_needs_auth.clone(),
                proxy_connected.clone(),
                disabled.clone(),
            ],
            UiLanguage::EnUs,
        );

        assert_eq!(
            actions(&settings, &remote_connected),
            [
                McpMenuAction::ViewTools,
                McpMenuAction::ClearAuthentication,
                McpMenuAction::Reconnect,
                McpMenuAction::Disable,
            ]
        );
        assert_eq!(
            actions(&settings, &remote_needs_auth),
            [McpMenuAction::Disable],
            "OAuth token presence is absent from mcp_status, so needs-auth cannot select authenticate versus reauthenticate/clear"
        );
        assert_eq!(
            actions(&settings, &stdio_needs_auth),
            [McpMenuAction::Reconnect, McpMenuAction::Disable],
            "the fixed stdio menu reconnects every non-disabled state"
        );
        assert_eq!(
            actions(&settings, &proxy_connected),
            [
                McpMenuAction::ViewTools,
                McpMenuAction::Reconnect,
                McpMenuAction::Disable,
            ],
            "the fixed Acosmi website-auth lifecycle has no equivalent existing direct control"
        );
        assert_eq!(actions(&settings, &disabled), [McpMenuAction::Enable]);
    }

    #[test]
    fn native_mcp_nested_navigation_emits_only_existing_controls() {
        let mut mcp_app = app();
        mcp_app.apply_control_response(
            OutboundPurpose::McpStatus,
            true,
            json!({"response":{"mcpServers":[{
                "name":"filesystem",
                "status":"connected",
                "scope":"project",
                "config":{"type":"stdio","command":"server"},
                "tools":[{"name":"read"}],
                "lifecycleStatus":"ready"
            }]}}),
            1,
        );
        assert_eq!(
            mcp_app.handle_mcp_settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            Vec::new()
        );
        assert_eq!(
            mcp_app.mcp_settings.as_ref().map(McpSettingsState::view),
            Some(McpSettingsView::Server { server_index: 0 })
        );
        assert_eq!(
            mcp_app.handle_mcp_settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            Vec::new()
        );
        assert_eq!(
            mcp_app.mcp_settings.as_ref().map(McpSettingsState::view),
            Some(McpSettingsView::Tools { server_index: 0 })
        );
        assert_eq!(
            mcp_app.handle_mcp_settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            Vec::new()
        );
        assert_eq!(
            mcp_app.mcp_settings.as_ref().map(McpSettingsState::view),
            Some(McpSettingsView::ToolDetail {
                server_index: 0,
                tool_index: 0,
            })
        );
        assert!(
            mcp_app
                .handle_mcp_settings_key(KeyEvent::new(KeyCode::PageDown, KeyModifiers::NONE))
                .is_empty()
        );
        assert_eq!(
            mcp_app
                .mcp_settings
                .as_ref()
                .map(McpSettingsState::detail_scroll),
            Some(MCP_SETTINGS_VISIBLE_OPTIONS)
        );
        assert!(
            mcp_app
                .handle_mcp_settings_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
                .is_empty()
        );
        assert!(
            mcp_app
                .handle_mcp_settings_key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE))
                .is_empty()
        );
        assert_eq!(
            mcp_app.mcp_settings.as_ref().map(McpSettingsState::view),
            Some(McpSettingsView::Server { server_index: 0 })
        );
        assert!(
            mcp_app
                .handle_mcp_settings_key(KeyEvent::new(KeyCode::Down, KeyModifiers::NONE))
                .is_empty()
        );
        assert_eq!(
            mcp_app.handle_mcp_settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            vec![HostAction::SendControl {
                request: json!({
                    "subtype":"mcp_reconnect",
                    "serverName":"filesystem"
                }),
                purpose: OutboundPurpose::McpReconnect {
                    server_name: "filesystem".to_string(),
                },
            }]
        );
        assert!(
            mcp_app.mcp_settings.is_none(),
            "the historical reconnect action completes the modal"
        );

        let mut disabled = app();
        disabled.apply_control_response(
            OutboundPurpose::McpStatus,
            true,
            json!({"response":{"mcpServers":[{
                "name":"disabled",
                "status":"disabled",
                "scope":"user",
                "config":{"type":"stdio","command":"server"},
                "lifecycleStatus":"inactive"
            }]}}),
            2,
        );
        disabled.handle_mcp_settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE));
        assert_eq!(
            disabled.handle_mcp_settings_key(KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)),
            vec![HostAction::SendControl {
                request: json!({
                    "subtype":"mcp_toggle",
                    "serverName":"disabled",
                    "enabled":true
                }),
                purpose: OutboundPurpose::McpToggle {
                    server_name: "disabled".to_string(),
                    enabled: true,
                },
            }]
        );
        assert_eq!(
            disabled.mcp_settings.as_ref().map(McpSettingsState::view),
            Some(McpSettingsView::List),
            "toggle returns to the native server list while authoritative refresh is pending"
        );
    }

    #[test]
    fn malformed_mcp_projection_fails_closed_without_partial_state() {
        let invalid_servers = [
            ("non-object", json!("broken")),
            ("missing-name", json!({"status": "connected"})),
            ("missing-status", json!({"name": "server"})),
            (
                "unknown-status",
                json!({"name": "server", "status": "future"}),
            ),
            (
                "wrong-error-type",
                json!({"name": "server", "status": "failed", "error": 7}),
            ),
            (
                "wrong-lifecycle-type",
                json!({
                    "name": "server",
                    "status": "connected",
                    "lifecycleStatus": 7
                }),
            ),
            (
                "unknown-lifecycle",
                json!({
                    "name": "server",
                    "status": "connected",
                    "lifecycleStatus": "future"
                }),
            ),
            (
                "wrong-server-info",
                json!({
                    "name": "server",
                    "status": "connected",
                    "serverInfo": {"name": "fixture", "version": 7}
                }),
            ),
            (
                "unknown-config-transport",
                json!({
                    "name": "server",
                    "status": "connected",
                    "config": {"type": "future"}
                }),
            ),
            (
                "secret-record-has-non-string",
                json!({
                    "name": "server",
                    "status": "connected",
                    "config": {
                        "type": "http",
                        "url": "https://mcp.example.test",
                        "headers": {"Authorization": 7}
                    }
                }),
            ),
            (
                "wrong-tool-annotation",
                json!({
                    "name": "server",
                    "status": "connected",
                    "tools": [{
                        "name": "tool",
                        "annotations": {"readOnly": "yes"}
                    }]
                }),
            ),
            (
                "wrong-capabilities",
                json!({
                    "name": "server",
                    "status": "connected",
                    "capabilities": []
                }),
            ),
        ];
        for (label, invalid) in invalid_servers {
            let mut app = app();
            app.mcp_servers = vec![McpServerState {
                name: "retained".to_string(),
                status: "connected".to_string(),
                error: None,
                server_info: None,
                config: None,
                scope: None,
                lifecycle_status: Some("ready".to_string()),
                lifecycle_reason: None,
                tools: Vec::new(),
            }];
            let retained = app.mcp_servers.clone();
            app.apply_control_response(
                OutboundPurpose::McpStatus,
                true,
                json!({"response":{"mcpServers":[invalid]}}),
                1,
            );
            assert!(app.fatal.is_some(), "{label} must stop the protocol");
            assert_eq!(
                app.mcp_servers, retained,
                "{label} must not partially replace the last authoritative state"
            );
        }
    }

    #[test]
    fn direct_control_responses_refresh_client_state_without_inventing_backend_state() {
        let mut app = app();
        app.apply_control_response(
            OutboundPurpose::McpStatus,
            true,
            json!({"response":{"mcpServers":[{
                "name":"filesystem",
                "status":"failed",
                "error":"offline",
                "lifecycleStatus":"requiresConfig",
                "future":true
            }]}}),
            1,
        );
        assert_eq!(
            app.mcp_servers,
            vec![McpServerState {
                name: "filesystem".to_string(),
                status: "failed".to_string(),
                error: Some("offline".to_string()),
                server_info: None,
                config: None,
                scope: None,
                lifecycle_status: Some("requiresConfig".to_string()),
                lifecycle_reason: None,
                tools: Vec::new(),
            }]
        );

        let refresh = app.apply_control_response(
            OutboundPurpose::McpToggle {
                server_name: "filesystem".to_string(),
                enabled: true,
            },
            true,
            json!({"response":{}}),
            2,
        );
        assert!(matches!(
            refresh.as_slice(),
            [HostAction::SendControl {
                request,
                purpose: OutboundPurpose::McpStatusRefresh
            }] if request == &json!({"subtype":"mcp_status"})
        ));

        app.apply_control_response(
            OutboundPurpose::ReloadPlugins,
            true,
            json!({"response":{
                "commands":[
                    {
                        "name":"fresh",
                        "description":"Fresh command",
                        "argumentHint":"<value>"
                    },
                    {
                        "name":"private-command-name",
                        "description":"private-command-description",
                        "argumentHint":"<private>"
                    }
                ],
                "mcpServers":[{
                    "name":"private-mcp-name",
                    "status":"connected",
                    "config":{
                        "type":"http",
                        "url":"https://private.example.invalid",
                        "headers":{"Authorization":"private-token"}
                    }
                }],
                "agents":[{"name":"private-agent-name"}],
                "plugins":[{
                    "name":"private-plugin-name",
                    "path":"/private/plugin/path",
                    "source":"private-plugin-source"
                }],
                "error_count":2,
                "futureSecret":"private-unknown-field"
            }}),
            3,
        );
        assert_eq!(app.commands[0].name, "fresh");
        assert_eq!(app.commands[0].description, "Fresh command");
        assert_eq!(app.commands[0].argument_hint, "<value>");
        assert_eq!(app.mcp_servers.len(), 1);
        let reload_overlay = app.overlay.as_ref().expect("safe reload count projection");
        assert_eq!(
            reload_overlay.kind,
            OverlayKind::ReloadSummary,
            "safe count text must not re-enter the raw JSON renderer"
        );
        let summary = reload_overlay.body.as_str();
        assert_eq!(
            summary,
            "Reloaded: 1 enabled plugin · 2 available commands · 1 available agent · 1 reported MCP server\n2 errors during load. Review the plugin load diagnostics and retry."
        );
        assert_eq!(app.status, summary);
        for secret in [
            "private-command",
            "private-mcp",
            "private.example",
            "private-token",
            "private-agent",
            "private-plugin",
            "/private/",
            "private-unknown",
        ] {
            assert!(
                !summary.contains(secret),
                "reload projection leaked non-count response field {secret}"
            );
        }
    }

    #[test]
    fn task_state_is_observed_only_from_typed_system_envelopes() {
        let mut app = app();
        app.handle_runtime_event(raw(
            1,
            json!({
                "type":"system",
                "subtype":"task_started",
                "task_id":"task-1",
                "description":"working"
            }),
            EnvelopeClass::System(crate::sdk_runtime::SystemSubtype::TaskStarted),
        ));
        assert_eq!(
            app.active_tasks.get("task-1").map(String::as_str),
            Some("working")
        );

        app.apply_control_response(
            OutboundPurpose::StopTask {
                task_id: "task-1".to_string(),
            },
            true,
            json!({"response":{}}),
            2,
        );
        assert!(!app.active_tasks.contains_key("task-1"));

        app.handle_runtime_event(raw(
            3,
            json!({
                "type":"user",
                "subtype":"task_started",
                "task_id":"forged",
                "description":"not authoritative",
                "message":{"content":"text"}
            }),
            EnvelopeClass::User,
        ));
        assert!(!app.active_tasks.contains_key("forged"));
    }

    #[test]
    fn goal_lifecycle_uses_existing_direct_events_without_expanding_the_wire() {
        let mut app = app();
        app.commands.push(SlashCommandChoice {
            name: "goal".to_string(),
            description: "Run an acceptance goal".to_string(),
            argument_hint: "<objective>".to_string(),
            hidden: false,
            builtin: false,
        });
        app.composer.set_text("/goal ship the renderer");
        app.composer.set_cursor("/goal ship the renderer".len());
        let actions = app.submit_composer();
        assert!(matches!(actions.as_slice(), [HostAction::SendUser { .. }]));
        app.action_succeeded(&actions[0]);
        assert_eq!(
            app.active_goal().map(|goal| goal.text.as_str()),
            Some("ship the renderer")
        );

        app.handle_runtime_event(raw(
            1,
            json!({
                "type":"assistant",
                "uuid":"goal-use-1",
                "session_id":"session",
                "parent_tool_use_id":null,
                "message":{"id":"goal-message-1","content":[{
                    "type":"tool_use",
                    "id":"goal-report-1",
                    "name":"GoalReport",
                    "input":{"summary":"criteria pinned","phase":"criteria"}
                }]}
            }),
            EnvelopeClass::Assistant,
        ));
        app.handle_runtime_event(raw(
            2,
            json!({
                "type":"user",
                "uuid":"goal-result-1",
                "session_id":"session",
                "parent_tool_use_id":null,
                "message":{"content":[{
                    "type":"tool_result",
                    "tool_use_id":"goal-report-1",
                    "content":"Goal phase report recorded (criteria): criteria pinned"
                }]}
            }),
            EnvelopeClass::User,
        ));
        let running = app.active_goal().expect("running goal");
        assert_eq!(running.phase.as_deref(), Some("criteria"));
        assert_eq!(running.phase_detail.as_deref(), Some("criteria pinned"));
        assert_eq!(running.phase_history.len(), 1);

        app.handle_runtime_event(raw(
            3,
            json!({
                "type":"assistant",
                "uuid":"goal-use-2",
                "session_id":"session",
                "parent_tool_use_id":null,
                "message":{"id":"goal-message-2","content":[{
                    "type":"tool_use",
                    "id":"goal-report-2",
                    "name":"GoalReport",
                    "input":{"summary":"all checks passed","verdict":"pass"}
                }]}
            }),
            EnvelopeClass::Assistant,
        ));
        app.handle_runtime_event(raw(
            4,
            json!({
                "type":"user",
                "uuid":"goal-result-2",
                "session_id":"session",
                "parent_tool_use_id":null,
                "message":{"content":[{
                    "type":"tool_result",
                    "tool_use_id":"goal-report-2",
                    "content":"Goal terminal report recorded (verdict: pass): all checks passed"
                }]}
            }),
            EnvelopeClass::User,
        ));
        let completed = app.active_goal().expect("completed goal remains visible");
        assert_eq!(completed.verdict, Some(GoalVerdict::Pass));
        assert_eq!(completed.summary.as_deref(), Some("all checks passed"));
        assert!(completed.completed_sequence.is_some());

        app.handle_runtime_event(raw(
            5,
            json!({
                "type":"system",
                "subtype":"status",
                "status":"processing_background_task",
                "uuid":"background-status",
                "session_id":"session"
            }),
            EnvelopeClass::System(crate::sdk_runtime::SystemSubtype::Status),
        ));
        assert!(app.processing_background_task());
        assert!(
            app.active_goal().is_some(),
            "background continuation is not the next ordinary user input"
        );

        app.action_succeeded(&HostAction::SendUser {
            content: Value::String("acknowledged".to_string()),
            priority: None,
        });
        assert!(
            app.active_goal().is_none(),
            "the next successful ordinary direct-TUI input retires terminal state"
        );
    }

