    #[test]
    fn historical_fullscreen_mouse_click_gate_preserves_move_and_wheel_input() {
        use crossterm::event::{MouseButton, MouseEvent, MouseEventKind};

        let start = Instant::now() + Duration::from_secs(1);
        let mut app = app();
        app.set_mouse_clicks_disabled(true);
        app.interaction_context = InteractionContext::Prompt;
        app.composer_area = ratatui::layout::Rect::new(0, 10, 40, 5);
        app.transcript_line_count = 200;
        app.transcript_viewport_height = 20;
        app.mouse_scroll = MouseScrollState::new_at(start);

        let _ = app.handle_event_at(
            Event::Mouse(MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: 70,
                row: 2,
                modifiers: KeyModifiers::NONE,
            }),
            start,
        );
        assert_eq!(
            app.interaction_context,
            InteractionContext::Prompt,
            "disabled clicks cannot move focus into scrollback"
        );

        let _ = app.handle_event_at(
            Event::Mouse(MouseEvent {
                kind: MouseEventKind::Moved,
                column: 9,
                row: 4,
                modifiers: KeyModifiers::NONE,
            }),
            start + Duration::from_millis(1),
        );
        assert_eq!(app.last_mouse_position(), Some((9, 4)));

        let _ = app.handle_event_at(
            Event::Mouse(MouseEvent {
                kind: MouseEventKind::ScrollUp,
                column: 7,
                row: 11,
                modifiers: KeyModifiers::NONE,
            }),
            start + Duration::from_millis(2),
        );
        assert_eq!(
            app.mouse_scroll
                .debug_snapshot(&app.scroll_config, start + Duration::from_millis(2),)
                .stream
                .expect("wheel remains enabled")
                .events,
            1
        );
    }

    #[test]
    fn fullscreen_router_keeps_one_text_selection_gesture_across_drag() {
        let start = Instant::now() + Duration::from_secs(1);
        let mut app = app();
        app.composer_area = ratatui::layout::Rect::new(0, 20, 40, 5);

        let _ = app.handle_event_at(
            Event::Mouse(MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: 3,
                row: 4,
                modifiers: KeyModifiers::NONE,
            }),
            start,
        );
        assert_eq!(
            app.take_transcript_view_actions(),
            VecDeque::from([
                crate::agent_view::TranscriptViewAction::CancelPointerGesture,
                crate::agent_view::TranscriptViewAction::FocusChanged { scrollback: true },
                crate::agent_view::TranscriptViewAction::PointerDown {
                    point: (3, 4),
                    link_modifier_held: false,
                },
            ]),
        );

        let _ = app.handle_event_at(
            Event::Mouse(MouseEvent {
                kind: MouseEventKind::Drag(MouseButton::Left),
                column: 9,
                row: 5,
                modifiers: KeyModifiers::NONE,
            }),
            start + Duration::from_millis(1),
        );
        assert_eq!(
            app.take_transcript_view_actions(),
            VecDeque::from([crate::agent_view::TranscriptViewAction::PointerDrag {
                point: (9, 5),
            }]),
            "a drag must reach the press owner without an intervening cancellation",
        );

        let _ = app.handle_event_at(
            Event::Mouse(MouseEvent {
                kind: MouseEventKind::Up(MouseButton::Left),
                column: 9,
                row: 5,
                modifiers: KeyModifiers::NONE,
            }),
            start + Duration::from_millis(2),
        );
        assert_eq!(
            app.take_transcript_view_actions(),
            VecDeque::from([crate::agent_view::TranscriptViewAction::PointerUp((9, 5))]),
        );
    }

