    #[test]
    fn renderer_private_local_command_matrix_never_reserves_chat_delivery() {
        for command in [
            "/model manage",
            "/usage",
            "/plugin",
            "/plugins",
            "/marketplace",
            "/color blue",
            "/rename private command fixture",
        ] {
            let mut app = app();
            app.composer.set_text(command);
            app.composer.set_cursor(command.len());

            let actions = app.submit_composer();

            assert!(
                !actions.is_empty(),
                "{command} must start its private action"
            );
            assert!(
                actions
                    .iter()
                    .all(|action| matches!(action, HostAction::SendPrivateRuntimeAction { .. })),
                "{command} must remain on the closed renderer-private lane"
            );
            assert!(
                app.pending_composer_submission.is_none(),
                "{command} must not reserve a SendUser/SendControl delivery transaction"
            );
            assert_eq!(
                app.composer_history.entries.back().map(String::as_str),
                Some(command),
                "the accepted private command remains retryable from local history"
            );
            assert!(app.composer.is_empty());
            assert!(!app.should_quit);
            assert!(app.fatal.is_none());
        }
    }

    #[test]
    fn closing_model_management_releases_input_and_retires_old_instance_results() {
        let mut app = TuiApp::new(
            &json!({
                "commands": [{
                    "name": "local-models",
                    "description": "Manage local models",
                    "argumentHint": "[subcommand]"
                }]
            }),
            InitialSessionRequest::New,
            None,
        );
        app.release_startup_barrier_for_test();
        app.setup_lifecycle_phase = SetupLifecyclePhase::Initialized;

        app.composer.set_text("/model manage");
        app.composer.set_cursor("/model manage".len());
        let old_actions = app.submit_composer();
        let [
            old_action @ HostAction::SendPrivateRuntimeAction {
                purpose: PrivateRuntimePurpose::ModelCustomList,
                ..
            },
        ] = old_actions.as_slice()
        else {
            panic!("model management must request its custom-model snapshot");
        };
        let old_request_id = admit_private_action(&mut app, old_action);
        app.action_succeeded(old_action);
        assert!(app.pending_composer_submission.is_none());

        assert!(
            app.handle_event(Event::Key(KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)))
                .is_empty()
        );
        assert!(app.model_management.is_none());

        for character in "/local-models".chars() {
            assert!(
                app.handle_event(Event::Key(KeyEvent::new(
                    KeyCode::Char(character),
                    KeyModifiers::NONE,
                )))
                .is_empty()
            );
        }
        assert_eq!(
            app.composer.text(),
            "/local-models",
            "the first physical input after closing the panel must reach the prompt"
        );

        let new_actions = app.handle_event(Event::Key(KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::NONE,
        )));
        let [
            new_action @ HostAction::SendPrivateRuntimeAction {
                purpose: PrivateRuntimePurpose::ModelLocalSnapshot,
                ..
            },
        ] = new_actions.as_slice()
        else {
            panic!(
                "the exact runtime token must open native local-model management on its first Enter"
            );
        };
        let new_request_id = admit_private_action(&mut app, new_action);
        app.action_succeeded(new_action);
        assert!(app.pending_composer_submission.is_none());
        assert!(
            app.model_management
                .as_ref()
                .is_some_and(ModelManagementState::is_busy)
        );

        assert!(
            app.handle_private_runtime_result(
                Some(old_request_id),
                Some("model.custom.list".to_string()),
                None,
                &custom_model_list_result(),
            )
            .is_empty()
        );
        assert!(
            app.model_management
                .as_ref()
                .is_some_and(ModelManagementState::is_busy),
            "the retired custom-list result cannot consume the replacement local snapshot"
        );

        assert!(
            app.handle_private_runtime_result(
                Some(new_request_id),
                Some("runtime_action_error".to_string()),
                None,
                &json!({
                    "result": {"kind":"runtime_action_error","code":"fixture-local-error"}
                }),
            )
            .is_empty()
        );
        let management = app
            .model_management
            .as_ref()
            .expect("the replacement panel remains open after its correlated error");
        assert!(!management.is_busy());
        assert!(
            management
                .notice()
                .is_some_and(|notice| notice.contains("fixture-local-error"))
        );
        assert!(!app.should_quit);
        assert!(app.fatal.is_none());
    }

    #[test]
    fn closing_usage_management_retires_same_token_results_from_the_old_instance() {
        let mut app = app();
        app.composer.set_text("/usage");
        app.composer.set_cursor("/usage".len());
        let old_actions = app.submit_composer();
        let old_request_id = admit_private_action(&mut app, &old_actions[0]);
        assert!(app.pending_composer_submission.is_none());

        assert!(
            app.handle_usage_plugin_management_key(
                KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE,)
            )
            .is_empty()
        );
        assert!(app.usage_plugin_management.is_none());

        app.composer.set_text("/usage");
        app.composer.set_cursor("/usage".len());
        let new_actions = app.submit_composer();
        let new_request_id = admit_private_action(&mut app, &new_actions[0]);
        assert!(matches!(
            (&old_actions[0], &new_actions[0]),
            (
                HostAction::SendPrivateRuntimeAction {
                    purpose: PrivateRuntimePurpose::UsageRead { token: 1 },
                    ..
                },
                HostAction::SendPrivateRuntimeAction {
                    purpose: PrivateRuntimePurpose::UsageRead { token: 1 },
                    ..
                }
            )
        ));

        assert!(
            app.handle_private_runtime_result(
                Some(old_request_id),
                Some("usage_snapshot".to_string()),
                None,
                &usage_snapshot_result(),
            )
            .is_empty()
        );
        assert!(
            app.usage_plugin_management
                .as_ref()
                .is_some_and(UsagePluginManagementState::is_busy),
            "an old instance's token=1 result cannot settle the new instance's token=1 request"
        );

        assert!(
            app.handle_private_runtime_result(
                Some(new_request_id),
                Some("usage_snapshot".to_string()),
                None,
                &usage_snapshot_result(),
            )
            .is_empty()
        );
        assert!(
            app.usage_plugin_management
                .as_ref()
                .is_some_and(|management| !management.is_busy())
        );
        assert!(!app.should_quit);
        assert!(app.fatal.is_none());
    }

